CREATE TABLE `zbp_blog_plugin_ytecn_nana_prise` (
  `ID` int NOT NULL AUTO_INCREMENT,
  `UserID` int NOT NULL DEFAULT '0',
  `PostID` int NOT NULL DEFAULT '0',
  `IP` varchar(15) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`ID`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



CREATE TABLE `zbp_category` (
  `cate_ID` int NOT NULL AUTO_INCREMENT,
  `cate_Name` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `cate_Order` int NOT NULL DEFAULT '0',
  `cate_Type` int NOT NULL DEFAULT '0',
  `cate_Count` int NOT NULL DEFAULT '0',
  `cate_Alias` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `cate_Intro` mediumtext COLLATE utf8mb4_general_ci NOT NULL,
  `cate_RootID` int NOT NULL DEFAULT '0',
  `cate_ParentID` int NOT NULL DEFAULT '0',
  `cate_Template` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `cate_LogTemplate` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `cate_Meta` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `cate_Group` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `cate_CreateTime` int NOT NULL DEFAULT '0',
  `cate_UpdateTime` int NOT NULL DEFAULT '0',
  `cate_PostTime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`cate_ID`),
  KEY `zbp_cate_Order` (`cate_Order`)
) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



CREATE TABLE `zbp_comment` (
  `comm_ID` int NOT NULL AUTO_INCREMENT,
  `comm_LogID` int NOT NULL DEFAULT '0',
  `comm_IsChecking` tinyint NOT NULL DEFAULT '0',
  `comm_RootID` int NOT NULL DEFAULT '0',
  `comm_ParentID` int NOT NULL DEFAULT '0',
  `comm_AuthorID` int NOT NULL DEFAULT '0',
  `comm_Name` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `comm_Email` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `comm_HomePage` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `comm_Content` mediumtext COLLATE utf8mb4_general_ci NOT NULL,
  `comm_PostTime` int NOT NULL DEFAULT '0',
  `comm_IP` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `comm_Agent` mediumtext COLLATE utf8mb4_general_ci NOT NULL,
  `comm_Meta` longtext COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`comm_ID`),
  KEY `zbp_comm_LRI` (`comm_LogID`,`comm_RootID`,`comm_IsChecking`),
  KEY `zbp_comm_IsChecking` (`comm_IsChecking`)
) ENGINE=MyISAM AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



CREATE TABLE `zbp_config` (
  `conf_ID` int NOT NULL AUTO_INCREMENT,
  `conf_Name` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `conf_Value` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `conf_Key` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`conf_ID`),
  KEY `zbp_conf_Name` (`conf_Name`)
) ENGINE=MyISAM AUTO_INCREMENT=733 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



CREATE TABLE `zbp_member` (
  `mem_ID` int NOT NULL AUTO_INCREMENT,
  `mem_Guid` varchar(36) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mem_Level` tinyint NOT NULL DEFAULT '0',
  `mem_Status` tinyint NOT NULL DEFAULT '0',
  `mem_Name` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mem_Password` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mem_Email` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mem_HomePage` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mem_IP` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mem_PostTime` int NOT NULL DEFAULT '0',
  `mem_Alias` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mem_Intro` mediumtext COLLATE utf8mb4_general_ci NOT NULL,
  `mem_Articles` int NOT NULL DEFAULT '0',
  `mem_Pages` int NOT NULL DEFAULT '0',
  `mem_Comments` int NOT NULL DEFAULT '0',
  `mem_Uploads` int NOT NULL DEFAULT '0',
  `mem_Template` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mem_Meta` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `mem_CreateTime` int NOT NULL DEFAULT '0',
  `mem_UpdateTime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`mem_ID`),
  KEY `zbp_mem_Name` (`mem_Name`),
  KEY `zbp_mem_Alias` (`mem_Alias`),
  KEY `zbp_mem_Level` (`mem_Level`)
) ENGINE=MyISAM AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



CREATE TABLE `zbp_module` (
  `mod_ID` int NOT NULL AUTO_INCREMENT,
  `mod_Name` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mod_FileName` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mod_Content` mediumtext COLLATE utf8mb4_general_ci NOT NULL,
  `mod_SidebarID` int NOT NULL DEFAULT '0',
  `mod_HtmlID` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mod_Type` varchar(5) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mod_MaxLi` int NOT NULL DEFAULT '0',
  `mod_Source` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `mod_IsHideTitle` tinyint NOT NULL DEFAULT '0',
  `mod_Meta` longtext COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`mod_ID`)
) ENGINE=MyISAM AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



CREATE TABLE `zbp_post` (
  `log_ID` int NOT NULL AUTO_INCREMENT,
  `log_CateID` int NOT NULL DEFAULT '0',
  `log_AuthorID` int NOT NULL DEFAULT '0',
  `log_Tag` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `log_Status` tinyint NOT NULL DEFAULT '0',
  `log_Type` int NOT NULL DEFAULT '0',
  `log_Alias` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `log_IsTop` int NOT NULL DEFAULT '0',
  `log_IsLock` tinyint NOT NULL DEFAULT '0',
  `log_Title` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `log_Intro` mediumtext COLLATE utf8mb4_general_ci NOT NULL,
  `log_Content` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `log_PostTime` int NOT NULL DEFAULT '0',
  `log_CommNums` int NOT NULL DEFAULT '0',
  `log_ViewNums` int NOT NULL DEFAULT '0',
  `log_Template` varchar(250) COLLATE utf8mb4_general_ci NOT NULL DEFAULT '',
  `log_Meta` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `log_CreateTime` int NOT NULL DEFAULT '0',
  `log_UpdateTime` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`log_ID`),
  KEY `zbp_log_TPISC` (`log_Type`,`log_PostTime`,`log_IsTop`,`log_Status`,`log_CateID`)
) ENGINE=MyISAM AUTO_INCREMENT=677 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



