INSERT INTO `zbp_module` (`mod_ID`, `mod_Name`, `mod_FileName`, `mod_Content`, `mod_SidebarID`, `mod_HtmlID`, `mod_Type`, `mod_MaxLi`, `mod_Source`, `mod_IsHideTitle`, `mod_Meta`) VALUES ('22', 'oneword', 'oneword', '<div id=\"apiContent\"></div>\r\n\r\n    <script>\r\n        // 使用 fetch 函数调用 API\r\n        fetch(\'./yiyan/api/json.php\')\r\n            .then(response => response.json()) // 将响应解析为 JSON\r\n            .then(data => {\r\n                // 提取 content 字段的内容\r\n                const content = data.data.content.content;\r\n\r\n                // 创建一个新的 div 元素\r\n                const contentDiv = document.createElement(\'div\');\r\n\r\n                // 设置 div 的内容为提取的 content\r\n                contentDiv.innerText = content;\r\n\r\n                // 将新创建的 div 插入到页面中的指定位置\r\n                document.getElementById(\'apiContent\').appendChild(contentDiv);\r\n            })\r\n            .catch(error => console.error(\'Error:\', error));\r\n    </script>', '0', 'oneword', 'div', '0', 'user', '1', '');
