INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('59', '0', '1', '', '0', '0', '', '0', '0', 'C4D 给正方体使用细分做小倒角', '关闭细分，用切刀（K）在边线附近先切线，然后再打开细分看效果<!--autointro-->', '<p>关闭细分，用切刀（K）在边线附近先切线，然后再打开细分看效果</p>', '1622716998', '0', '226', '', '', '0', '1622716998');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('60', '0', '1', '', '0', '0', '', '0', '0', 'C4D 挤压工具（挤出）', '物体要先转成可编辑状态，快捷键C--以下操作为移动面然后选面，按住ctrl推拉鼠标，可拖着轴往外拉，这种操作不可定数值如果不按ctrl的话会变成拖着一个面移动，会带动周围的面拱起--以下操作为挤压面选面，按快捷键D切换到挤压工具，沿着轴向拖拉，右侧属性区会显示移动距离，或者切换到挤压工具后，属性直接输入数值，不用鼠标拖拉轴了<!--autointro-->', '<p>物体要先转成可编辑状态，快捷键C</p><p>--以下操作为移动面</p><p>然后选面，按住ctrl推拉鼠标，可拖着轴往外拉，这种操作不可定数值</p><p>如果不按ctrl的话会变成拖着一个面移动，会带动周围的面拱起</p><p>--以下操作为挤压面</p><p>选面，按快捷键D切换到挤压工具，沿着轴向拖拉，右侧属性区会显示移动距离，或者切换到挤压工具后，属性直接输入数值，不用鼠标拖拉轴了</p><p><br/></p><p><br/></p>', '1623030710', '0', '242', '', '', '0', '1623030710');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('61', '0', '1', '', '0', '0', '', '0', '0', 'win10 ltsc 企业版安装打印机共享给其他局域网电脑使用', '启用guest，并把guest加入users组设置用户权限分配设置共享和安全选项卡添加guest用户<!--autointro-->', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>启用guest，并把guest加入users组</p><p><br/></p><p><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/06/202106151623729261467559.png\" style=\"\" title=\"QQ截图20210615114222.png\"/></p><p><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/06/202106151623729265141655.png\" style=\"\" title=\"QQ截图20210615114256.png\"/></p></li><li><p>设置用户权限分配</p><p><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/06/202106151623729311329818.png\" title=\"QQ截图20210615114654.png\" alt=\"QQ截图20210615114654.png\"/></p></li><li><p>设置共享和安全选项卡添加guest用户<br/></p></li></ol>', '1623729207', '0', '229', '', '', '0', '1623729207');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('62', '0', '1', '', '0', '0', '', '0', '0', '下载不能下载的抖音视频以及不带水印的源视频', '再抖音上点分享小箭头按钮，选择复制链接，发送到电脑上，再电脑上用遨游浏览器打开，然后在右上角工具按钮里找到资源嗅探器，点图钉按钮固定在工具按钮旁边，如果未启动，先点三条杠，点更多工具，扩展工具，启用资源嗅探器。按Ctrl+F5强制刷新网页，资源嗅探器里面就可以看到获取到视频的真实地址了，筛选视频，下载到本地即可。<!--autointro-->', '<p>再抖音上点分享小箭头按钮，选择复制链接，发送到电脑上，</p><p>再电脑上用遨游浏览器打开，然后在右上角工具按钮里找到资源嗅探器，点图钉按钮固定在工具按钮旁边，如果未启动，先点三条杠，点更多工具，扩展工具，启用资源嗅探器。</p><p>按Ctrl+F5强制刷新网页，资源嗅探器里面就可以看到获取到视频的真实地址了，筛选视频，下载到本地即可。</p><p><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/06/202106251624593718675913.png\" title=\"QQ截图20210625120140.png\" alt=\"QQ截图20210625120140.png\"/></p>', '1624593413', '0', '193', '', '', '0', '1624593413');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('63', '0', '1', '', '0', '0', '', '0', '0', 'flash制作元件跟随路径移动的动画', '在库里新建元件新建图层，在动画的第一帧位置把素材元件拉进场景指定动画的时长，设置关键帧在第一帧和最后一帧中间右击，创建传统补间动画新建图层，在图层上右击勾选引导图层在动画的第一帧位置，在引导层上绘制路径在动画的最后一帧位置，给引导层添加空白帧，使路径的时间和动画时间一致把元件的图层拖到引导层的上面在动画第一帧位置，把元件图层对齐到路径开始位置在动画最后一帧位置，把元件图层对齐到路径结束位置拖动元件图层到引导层上进行关联<!--autointro-->', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>在库里新建元件</p></li><li><p>新建图层，在动画的第一帧位置把素材元件拉进场景</p></li><li><p>指定动画的时长，设置关键帧</p></li><li><p>在第一帧和最后一帧中间右击，创建传统补间动画<br/></p></li><li><p>新建图层，在图层上右击勾选引导图层</p></li><li><p>在动画的第一帧位置，在引导层上绘制路径</p></li><li><p>在动画的最后一帧位置，给引导层添加空白帧，使路径的时间和动画时间一致</p></li><li><p>把元件的图层拖到引导层的上面</p></li><li><p>在动画第一帧位置，把元件图层对齐到路径开始位置</p></li><li><p>在动画最后一帧位置，把元件图层对齐到路径结束位置</p></li><li><p>拖动元件图层到引导层上进行关联</p><p><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/07/202107291627528283323714.png\" title=\"QQ截图20210729111110.png\" alt=\"QQ截图20210729111110.png\"/><br/></p><p><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/07/202107291627528178224120.png\" title=\"QQ截图20210729110841.png\" alt=\"QQ截图20210729110841.png\"/><br/></p></li></ol>', '1627527847', '0', '207', '', '', '0', '1627527847');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('64', '0', '1', '', '0', '0', '', '0', '0', '2.5寸硬盘不认盘', '尝试屏蔽供电接口第三根脚试试<!--autointro-->', '<p>尝试屏蔽供电接口第三根脚试试</p><p><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/07/202107291627546371798698.png\" title=\"未标题-1.png\" alt=\"未标题-1.png\"/></p>', '1627546334', '0', '201', '', '', '0', '1627546334');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('65', '2', '1', '{15}', '0', '0', '', '0', '0', '群晖docker安装Emby并开启硬件解码', '<p><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\"></span></p><!--autointro-->', '<p><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">群晖支持硬件解码的必要条件是：</span></p><p><br/></p><ul style=\"box-sizing: border-box; margin-bottom: 20px; margin-left: 20px; padding-left: 0px; list-style-position: initial; list-style-image: initial; word-break: break-word; color: rgb(64, 64, 64); font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\" class=\" list-paddingleft-2\"><li><p>群晖系统为DS 918+</p></li><li><p>CPU支持硬件解码</p></li></ul><p><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">通过ssh连接到群晖，输入</span><code style=\"box-sizing: border-box; font-size: 12px; font-family: Consolas, Monaco, &quot;Andale Mono&quot;, &quot;Ubuntu Mono&quot;, monospace; padding: 2px 4px; border: none; vertical-align: middle; white-space: pre-wrap; color: rgb(199, 37, 78); background-color: rgb(242, 242, 242);\">ls /dev/dri</code><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">，如果和下图一样，那么恭喜你，你可以开启硬件解码</span><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\"></span><br/></p><p><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\"><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/07/202107301627634716258611.png\" title=\"QQ截图20210730164503.png\" alt=\"QQ截图20210730164503.png\"/></span></p><p><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\"><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">需要说明的是，emby开启硬件加速功能是需要会员的，当然也有免费的替代品——Jellyfin，Jellyfin是emby的一个分支，拥有emby的大部分功能，大家可以自行选择。</span></span></p><p><br/></p><h3 style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 16px; color: rgb(64, 64, 64); text-rendering: optimizelegibility; font-size: 22px; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; white-space: normal; background-color: rgb(255, 255, 255);\">在docker中安装emby</h3><h4 style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 16px; color: rgb(64, 64, 64); text-rendering: optimizelegibility; font-size: 20px; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; white-space: normal; background-color: rgb(255, 255, 255);\">下载emby镜像</h4><p><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">在docker注册表中搜索emby，选择</span><code style=\"box-sizing: border-box; font-size: 12px; font-family: Consolas, Monaco, &quot;Andale Mono&quot;, &quot;Ubuntu Mono&quot;, monospace; padding: 2px 4px; border: none; vertical-align: middle; white-space: pre-wrap; color: rgb(199, 37, 78); background-color: rgb(242, 242, 242);\">emby/embyserver</code><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">下载</span><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\"><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\"></span></span><br/></p><p><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\"><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/07/202107301627634765512074.png\" title=\"QQ截图20210730164548.png\" alt=\"QQ截图20210730164548.png\"/></span></p><p><br/></p><h4 style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 16px; color: rgb(64, 64, 64); text-rendering: optimizelegibility; font-size: 20px; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; white-space: normal; background-color: rgb(255, 255, 255);\">启动硬件加速</h4><ol style=\"box-sizing: border-box; margin-bottom: 20px; margin-left: 20px; padding-left: 0px; list-style-position: initial; list-style-image: initial; word-break: break-word; color: rgb(64, 64, 64); font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\" class=\" list-paddingleft-2\"><li><p style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 20px; word-break: break-word;\">下载完映像之后，不要直接启动，开启群晖的SSH，打开控制面板，在终端机开启</p></li></ol><p><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/07/202107301627634792503499.png\" title=\"QQ截图20210730164621.png\" alt=\"QQ截图20210730164621.png\"/></p><p>2. <span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">通过ssh工具登录到群晖，输入</span><code style=\"box-sizing: border-box; font-size: 12px; font-family: Consolas, Monaco, &quot;Andale Mono&quot;, &quot;Ubuntu Mono&quot;, monospace; padding: 2px 4px; border: none; vertical-align: middle; white-space: pre-wrap; color: rgb(199, 37, 78); background-color: rgb(242, 242, 242);\"><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">sudo -i</span></code><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">切换到</span><code style=\"box-sizing: border-box; font-size: 12px; font-family: Consolas, Monaco, &quot;Andale Mono&quot;, &quot;Ubuntu Mono&quot;, monospace; padding: 2px 4px; border: none; vertical-align: middle; white-space: pre-wrap; color: rgb(199, 37, 78); background-color: rgb(242, 242, 242);\"><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">root</span></code><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">账户，会要求</span><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">输入密码</span></p><p><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\"><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/07/202107301627634937406314.png\" title=\"QQ截图20210730164652.png\" alt=\"QQ截图20210730164652.png\"/></span></p><p><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">3.&nbsp;</span><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">输入以下代码启动emby容器</span></p><pre class=\"line-numbers  language-bash\" style=\"box-sizing: border-box; font-size: 12px; font-family: Consolas, Monaco, &quot;Andale Mono&quot;, &quot;Ubuntu Mono&quot;, monospace; margin-top: 0px; margin-bottom: 20px; overflow: scroll auto; overflow-wrap: normal; word-break: break-all; overscroll-behavior-x: contain; border-radius: 4px; z-index: 0; padding: 1em 1em 1em 3.8em; line-height: 1.5; color: rgb(204, 204, 204); background-color: rgb(45, 45, 45); tab-size: 4; hyphens: none; position: relative; counter-reset: linenumber 0;\">docker&nbsp;run&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;--name=emby&nbsp;\\&nbsp;#&nbsp;容器名称\r\n&nbsp;&nbsp;&nbsp;&nbsp;--device=/dev/dri:/dev/dri&nbsp;\\&nbsp;#开启硬件解码\r\n&nbsp;&nbsp;&nbsp;&nbsp;--net&nbsp;host&nbsp;\\&nbsp;#&nbsp;配置网络\r\n&nbsp;&nbsp;&nbsp;&nbsp;emby/embyserver&nbsp;#&nbsp;要运行的映像名称</pre><p><br/></p><div><div>这里通过<code>--net host</code>是该容器使用<code>docker host</code>网络，即与docker主机网络相同。目的是解决emby无法刮削元数据的问题，因为emby使用<code>theMovieDb</code>进行刮削，详情可见<a href=\"https://www.jianshu.com/p/5ca8f1c04926\" target=\"_blank\">解决tinyMediaManager无法刮削的问题</a>。这样只要在修改群晖<code>hosts</code>文件，便可以解决emby无法刮削的问题。不过建议直接使用tMM进行刮削，tMM也可以通过docker安装了——<a href=\"https://www.jianshu.com/p/1f09ad93a9f0\" target=\"_blank\">群晖Docker安装tinyMediaManager并解决无法刮削的问题</a></div><br/><p>4.<span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">此时可以在群晖docker容器中看到正在运行的emby容器，将容器关闭并进行以下配置</span></p><p><br/></p></div><p><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\"></span><strong><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">添加卷</span></strong></p><p><strong><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/07/202107301627634983844936.png\" title=\"QQ截图20210730164806.png\" alt=\"QQ截图20210730164806.png\"/></strong></p><p><strong><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">修改</span><code style=\"box-sizing: border-box; font-size: 12px; font-family: Consolas, Monaco, &quot;Andale Mono&quot;, &quot;Ubuntu Mono&quot;, monospace; padding: 2px 4px; border: none; vertical-align: middle; white-space: pre-wrap; color: rgb(199, 37, 78); background-color: rgb(242, 242, 242);\">UID</code><span style=\"color: #404040; font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; background-color: #FFFFFF;\">和</span><code style=\"box-sizing: border-box; font-size: 12px; font-family: Consolas, Monaco, &quot;Andale Mono&quot;, &quot;Ubuntu Mono&quot;, monospace; padding: 2px 4px; border: none; vertical-align: middle; white-space: pre-wrap; color: rgb(199, 37, 78); background-color: rgb(242, 242, 242);\">GID</code></strong></p><p><code style=\"box-sizing: border-box; font-size: 12px; font-family: Consolas, Monaco, &quot;Andale Mono&quot;, &quot;Ubuntu Mono&quot;, monospace; padding: 2px 4px; border: none; vertical-align: middle; white-space: pre-wrap; color: rgb(199, 37, 78); background-color: rgb(242, 242, 242);\"><img class=\"ue-image\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/07/202107301627634991300642.png\" title=\"QQ截图20210730164826.png\" alt=\"QQ截图20210730164826.png\"/></code></p><ol start=\"5\" style=\"box-sizing: border-box; margin-bottom: 20px; margin-left: 20px; padding-left: 0px; list-style-position: initial; list-style-image: initial; word-break: break-word; color: rgb(64, 64, 64); font-family: -apple-system, BlinkMacSystemFont, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Segoe UI&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-size: 16px; white-space: normal; background-color: rgb(255, 255, 255);\" class=\" list-paddingleft-2\"><li><p>应用并开启emby容器，在浏览器中输入IP+8096就可以进入emby了</p></li></ol><p><br/></p>', '1627634615', '0', '239', '', '', '0', '1689647019');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('66', '2', '1', '{15}', '0', '0', '', '0', '0', 'video station或jellyfin emby 刮削器无法获取影片信息 [ tmdb/TMDB ]', '<p>通过修改群晖系统hosts解决DNS污染问题，链接到TMDB服务器，使video station或jellyfin emby 正常刮削电影/电视剧信息</p><p><br/></p><p><strong>方法1</strong></p><p><br/></p><p style=\"white-space: normal;\">适用于未开root的群辉</p><ol class=\" list-paddingleft-2\" style=\"width: 1409.8px; white-space: normal;\"></ol><!--autointro-->', '<p>通过修改群晖系统hosts解决DNS污染问题，链接到TMDB服务器，使video station或jellyfin emby 正常刮削电影/电视剧信息</p><p><br/></p><p><strong>方法1</strong></p><p><br/></p><p style=\"white-space: normal;\">适用于未开root的群辉</p><ol class=\" list-paddingleft-2\" style=\"width: 1409.8px; white-space: normal;\"><li><p>putty使用主账号连接nas</p></li><li><p>输入sudo -i，再输入一次主账号密码切换至root账号</p></li><li><p>输入vi /etc/hosts</p></li><li><p>按键盘i切换至插入模式，窗口左下角会显示-insert-</p></li><li><p>移动光标至合适位置，右键粘贴api地址</p></li><li><p>按一下esc键，退出编辑</p></li><li><p>按 :wq退出并保存</p></li><li><p>关闭putty，重启套件</p></li></ol><p><strong><br/></strong><strong style=\"white-space: normal;\">方法2</strong></p><p>适用于已经开了root账号的群辉</p><ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>参考本站<a href=\"{#ZC_BLOG_HOST#}?id=50\">群晖开启root账号</a>，开启群晖的root账号</p></li><li><p>winscp使用root账户登录</p></li><li><p>找到root/etc目录下的hosts文件</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/04/202204111831145773556.png\" alt=\"image.png\"/></p></li><li><p>双击并修改hosts，添加：<br/></p><p><em>13.224.161.90&nbsp;api.themoviedb.org</em></p><p><em>13.226.238.76 api.themoviedb.org</em></p><p><em>更多：</em><a href=\"{#ZC_BLOG_HOST#}?id=80\"><em>电影刮削修改hosts 可用DNS更新-+-日常笔记 (ljs.fun)</em></a></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/04/202204111835529189405.png\" alt=\"image.png\"/><br/></p></li><li><p>重启Jellyfin / emby套件，即可正常刮削。</p></li></ol><p><br/></p><p>&nbsp;&nbsp;&nbsp;&nbsp;video station 还需要手动添加TMDB的API, 申请方法：</p><p>1. 修改hosts后打开tmdb官网&nbsp;<a href=\"https://www.themoviedb.org/\">The Movie Database (TMDB) (themoviedb.org)</a>， 创建账号并登录。</p><p>2. 点右上角头像 点账户设置<br/></p><p>&nbsp;&nbsp;&nbsp;&nbsp;<img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211161714451225311.png\" alt=\"image.png\"/></p><p>3. 复制自己的密钥</p><p>&nbsp;&nbsp;&nbsp;&nbsp;<img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211161715338466730.png\" alt=\"image.png\"/></p><p>4. 到video station 中添加至设置里。</p><p>&nbsp;&nbsp;&nbsp;&nbsp;<img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211161719305339274.png\" alt=\"image.png\"/></p><p><br/></p><p><br/></p>', '1627896860', '0', '232', '', '', '0', '1689647030');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('307', '2', '1', '', '0', '0', '', '0', '0', 'excel 删除表格内的空行', '<p>在表格里，按快捷键CTRL+G，点&nbsp;<strong>定位条件</strong></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181245537160120.png\" alt=\"image.png\"/></p><p>选择 <strong>空值</strong> ，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181246133090154.png\" alt=\"image.png\"/></p><!--autointro-->', '<p>在表格里，按快捷键CTRL+G，点&nbsp;<strong>定位条件</strong></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181245537160120.png\" alt=\"image.png\"/></p><p>选择 <strong>空值</strong> ，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181246133090154.png\" alt=\"image.png\"/></p><p>在任意一个被选择的行上右击，选择<strong> 删除</strong><br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181246474957700.png\" alt=\"image.png\"/></p><p>选择 <strong>整行</strong></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181247053552221.png\" alt=\"image.png\"/></p><p>搞定！</p>', '1668746701', '0', '225', '', '', '1668746844', '1668746844');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('308', '2', '1', '', '0', '0', '', '0', '0', 'excel 在批注内设置图片', '<p>右击选中的单元格，<strong>插入批注</strong>，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181248158503039.png\" alt=\"image.png\"/></p><p>删除原有内容（可选）<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181248491271108.png\" alt=\"image.png\"/></p><!--autointro-->', '<p>右击选中的单元格，<strong>插入批注</strong>，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181248158503039.png\" alt=\"image.png\"/></p><p>删除原有内容（可选）<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181248491271108.png\" alt=\"image.png\"/></p><p>在任意一个锚点上右击，<strong>设置批注格式</strong>，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181249334658340.png\" alt=\"image.png\"/></p><p>选择 <strong>颜色与线条-填充效果</strong><br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181250219983472.png\" alt=\"image.png\"/></p><p>选择<strong>图片</strong><br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181250534302873.png\" alt=\"image.png\"/></p><p>勾上<strong>锁定纵横比</strong><br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181251255477724.png\" alt=\"image.png\"/></p><p>拖动 锚点，调整到图片可以完整显示<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211181251579188592.png\" alt=\"image.png\"/></p><p>搞定！</p>', '1668746847', '0', '217', '', '', '1668747147', '1668747164');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('314', '2', '1', '', '0', '0', '', '0', '0', '江泽民同志逝世，享年96岁', '<p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: center;\"></p><!--autointro-->', '<p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: center;\"><strong><span style=\"font-family: inherit; margin: 0px; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; text-indent: 2em;\">中国共产党中央委员会</span><br/></strong></p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: center;\"><strong>中华人民共和国全国人民代表大会常务委员会</strong></p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: center;\"><strong>中华人民共和国国务院</strong></p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: center;\"><strong>中国人民政治协商会议全国委员会</strong></p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: center;\"><strong>中国共产党和中华人民共和国中央军事委员会</strong></p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: center;\"><strong>告全党全军全国各族人民书</strong></p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">中国共产党中央委员会、中华人民共和国全国人民代表大会常务委员会、中华人民共和国国务院、中国人民政治协商会议全国委员会、中国共产党和中华人民共和国中央军事委员会，极其悲痛地向全党全军全国各族人民通告：我们敬爱的江泽民同志患白血病合并多脏器功能衰竭，抢救无效，于2022年11月30日12时13分在上海逝世，享年96岁。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">江泽民同志是我党我军我国各族人民公认的享有崇高威望的卓越领导人，伟大的马克思主义者，伟大的无产阶级革命家、政治家、军事家、外交家，久经考验的共产主义战士，中国特色社会主义伟大事业的杰出领导者，党的第三代中央领导集体的核心，“三个代表”重要思想的主要创立者。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">江泽民同志从青少年时代起就勤奋学习，追求真理，受到爱国主义思想和民主革命思想的启蒙。在大学学习期间，经过积极参加抗日爱国活动洗礼，江泽民同志形成了马克思主义世界观，完成了人生道路的选择，最终确立了为民族解放、人民幸福而奋斗的人生理想和信仰。一九四七年从上海交通大学毕业后，江泽民同志到工厂工作，在工人群众中并在青年会夜校职业青年中从事革命宣传工作，一九四九年组织工人群众开展护厂活动，迎接上海解放。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">中华人民共和国成立初期，江泽民同志先后担任上海益民食品一厂第一副厂长、上海制皂厂第一副厂长、第一机械工业部上海第二设计分局电器专业科科长等职。一九五四年，国家在长春兴建第一汽车制造厂，需要大批专业技术干部和管理干部，江泽民同志应调前往，一九五五年赴苏联莫斯科斯大林汽车制造厂实习。一九五六年回国后，江泽民同志任长春第一汽车制造厂动力处副处长、副总动力师、动力分厂厂长。一九六二年，江泽民同志调任第一机械工业部上海电器科学研究所副所长，负责该所科研领导工作。一九六六年，江泽民同志调任武汉热工机械研究所所长、代理党委书记，后任党委书记，组织原子能发电设备设计工作。“文化大革命”开始后，江泽民同志受到冲击。一九七〇年，江泽民同志调到第一机械工业部工作，一九七一年任中国第一机械工业部派驻罗马尼亚专家组总组长，一九七三年回国先后任第一机械工业部外事局副局长、局长。一九八〇年，江泽民同志担任国家进出口管理委员会、国家外国投资管理委员会副主任兼秘书长、党组成员，主管实施广东、福建两省实行特殊政策、灵活措施和试办经济特区等开创性工作。一九八二年，江泽民同志任电子工业部第一副部长、党组副书记，一九八三年任部长、党组书记，为我国电子工业发展作出了重要贡献。一九八二年九月，江泽民同志在党的第十二次全国代表大会上当选为中央委员。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">一九八五年，江泽民同志任上海市市长、中共上海市委副书记。一九八七年，江泽民同志在党的十三届一中全会上当选为中共中央政治局委员，并任中共上海市委书记。担任上海市长、市委书记期间，江泽民同志带领上海广大干部群众振奋精神、勇于探索，推动上海改革开放和社会主义现代化建设取得重大突破，浦东开发开放蓄势谋篇，推动党的建设、精神文明建设、社会建设取得重大进步。一九八九年春夏之交我国发生严重政治风波，江泽民同志拥护和执行党中央关于旗帜鲜明反对动乱、捍卫社会主义国家政权、维护人民根本利益的正确决策，紧紧依靠广大党员、干部、群众，有力维护上海稳定。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">一九八九年，在党的十三届四中全会上，江泽民同志当选为中共中央政治局常委、中央委员会总书记。同年，党的十三届五中全会决定江泽民同志为中共中央军事委员会主席。一九九〇年，在七届全国人大三次会议上当选为中华人民共和国中央军事委员会主席。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">江泽民同志是党的第三代中央领导集体的核心。二十世纪八十年代末九十年代初，国际国内发生严重政治风波，世界社会主义出现严重曲折，我国社会主义事业发展面临空前巨大的困难和压力。在这个决定党和国家前途命运的重大历史关头，江泽民同志带领党的中央领导集体，紧紧依靠全党全军全国各族人民，旗帜鲜明坚持四项基本原则，维护国家独立、尊严、安全、稳定，毫不动摇坚持经济建设这个中心，坚持改革开放，捍卫了中国特色社会主义伟大事业，打开了我国改革开放和社会主义现代化建设新局面。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">从党的十三届四中全会到党的十六大的十三年中，国际形势风云变幻，我国改革开放和社会主义现代化建设进程波澜壮阔。在国际国内十分复杂的形势下，江泽民同志带领党的中央领导集体，高举马克思列宁主义、毛泽东思想、邓小平理论伟大旗帜，坚持党的基本路线不动摇，团结全党全国各族人民，抓住机遇、深化改革、扩大开放、促进发展、保持稳定，确立了社会主义市场经济体制的改革目标和基本框架，确立了社会主义初级阶段公有制为主体、多种所有制经济共同发展的基本经济制度和按劳分配为主体、多种分配方式并存的分配制度，制定和实施了促进改革发展稳定的一系列方针政策和重大战略，锐意推进经济体制改革、政治体制改革、文化体制改革和其他各方面改革，开创全面改革开放新局面，实施依法治国基本方略，坚持“和平统一、一国两制”的方针，实现香港、澳门顺利回归，坚持独立自主的和平外交政策，打开外交工作崭新局面，推进党的建设新的伟大工程，推动社会主义物质文明、政治文明、精神文明建设取得举世瞩目的新进展，成功把中国特色社会主义推向二十一世纪。在以江泽民同志为核心的党的第三代中央领导集体领导下，我们从容应对一系列关系我国主权和安全的国际突发事件，战胜在政治、经济领域和自然界出现的困难和风险，保证了改革开放和社会主义现代化建设的航船始终沿着正确方向破浪前进。党的十三届四中全会以来十三年我们党和国家取得的巨大成就，同江泽民同志作为马克思主义政治家的雄才大略、关键作用、高超政治领导艺术是分不开的。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">江泽民同志担任中央军事委员会主席期间，深刻洞察和把握国内外形势的重大变化和世界新军事变革的发展趋势，对加强国防和军队现代化建设提出了一系列新论断新举措，丰富和发展了毛泽东军事思想和邓小平新时期军队建设思想，创立了江泽民国防和军队建设思想，领导国防和军队现代化建设取得了巨大成就。江泽民同志强调，要坚持国防建设与经济建设协调发展的方针，加强人民军队革命化、现代化、正规化建设；按照政治合格、军事过硬、作风优良、纪律严明、保障有力的总要求，紧紧围绕打得赢、不变质两个历史性课题，全面推进人民军队建设；毫不动摇坚持党对人民军队的绝对领导，始终把思想政治建设摆在我军各项建设的首位，永葆人民军队性质、本色、作风；贯彻积极防御的军事战略方针，推进中国特色军事变革，按照建设信息化军队、打赢信息化战争的目标，坚定不移走中国特色的精兵之路，实现我军现代化跨越式发展；实施科技强军战略，坚持从严治军、依法治军、勤俭建军，探索新的历史条件下治军的特点和规律，与时俱进推进我军各项建设；深化国防科技工业体制改革，增强自主创新能力，加快国防科技和武器装备发展，走出一条投入较少、效益较高的军队现代化建设路子；按照平战结合、军民结合、寓军于民的方针，提高国防动员能力，发展高技术条件下人民战争的战略战术，巩固军政军民团结。这一切，对于加强国防和军队现代化建设具有长远指导意义。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">江泽民同志坚持马克思主义的思想路线，尊重实践，尊重群众，准确把握时代特征，科学判断我们党所处的历史方位，围绕建设中国特色社会主义这个主题，在改革发展稳定、内政外交国防、治党治国治军等各方面都提出了一系列新思想新观点新论断，为坚持和发展党的基本理论、基本路线、基本纲领、基本经验作出了杰出贡献。特别是他集中全党智慧创立了“三个代表”重要思想，实现了党在指导思想上的又一次与时俱进，体现了一位真正马克思主义者的巨大政治勇气和理论勇气。“三个代表”重要思想突出强调我们党始终代表中国先进生产力的发展要求、代表中国先进文化的前进方向、代表中国最广大人民的根本利益，遵循了人类历史发展进步的普遍规律，顺应了时代发展潮流和我国社会发展进步要求，反映了全国各族人民利益和愿望，抓住了新形势下提高党的执政能力、巩固党的执政地位、完成党的执政使命的根本。“三个代表”重要思想最鲜明的特点和最突出的贡献，在于用一系列紧密联系、相互贯通的新思想新观点新论断，进一步回答了什么是社会主义、怎样建设社会主义的问题，创造性回答了建设什么样的党、怎样建设党的问题，是对马克思列宁主义、毛泽东思想、邓小平理论的继承和发展，深化了我们对新的时代条件下推进中国特色社会主义事业、加强党的建设的规律的认识。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">江泽民同志高度重视事关党和人民事业的重大战略问题。在筹备党的十六大期间，江泽民同志主动提出，为了党和国家事业长远发展，为了党和国家长治久安，他不再担任中央领导职务，并从中央委员会退下来，以利于促进党和国家高层领导新老交替。党中央同意了江泽民同志的请求。从当时国际形势复杂多变、国防和军队建设任务繁重考虑，党的十六届一中全会决定江泽民同志留任中共中央军事委员会主席。党的十六届一中全会后，江泽民同志全力支持以胡锦涛同志为总书记的新一届中央领导集体的工作，尽心尽力履行党中央交付他的职责。二〇〇四年，江泽民同志从党和国家事业长远发展的大局出发，又主动提出辞去他担任的党和国家中央军事委员会主席的职务，充分体现了他对党和国家事业发展的深谋远虑。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">从领导岗位上退下来以后，江泽民同志坚决拥护和支持党中央工作，关心中国特色社会主义伟大事业，坚定支持党风廉政建设和反腐败斗争。二〇〇六年，江泽民同志亲自主持编辑和逐篇审定《江泽民文选》第一卷、第二卷、第三卷。《江泽民文选》主要收入了江泽民同志从二十世纪八十年代末至二十一世纪初具有代表性和独创性的重要著作，为我们更深入地学习领会“三个代表”重要思想，继续推进中国特色社会主义伟大事业和党的建设新的伟大工程提供了重要教材。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">江泽民同志目光远大、审时度势，总是从中国和世界发展大势、从党和国家工作全局出发观察和思考问题，不断推进理论创新和其他各方面创新。江泽民同志信念坚定、处事果断，总是把党和人民放在心中最高的位置，始终不渝坚持共产党人的理想信念，在关键时刻具有作出果敢决策的非凡胆略和进行理论创新的巨大勇气。江泽民同志尊重实践、与时俱进，总是紧紧把握时代发展脉搏和契机，坚持从党和人民活生生的实践出发总结经验、寻找路子，脚踏实地而又开拓进取推进党和国家各项工作。江泽民同志尊重群众、关心群众，总是高度关注人民群众安危冷暖，依据最广大人民根本利益来检验和推动工作。江泽民同志的优秀品格和高尚风范将永远教育和激励我们前进。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">江泽民同志的逝世，对我党我军我国各族人民是不可估量的损失。党中央号召，全党全军全国各族人民化悲痛为力量，继承江泽民同志的遗志，以实际行动表达我们的悼念。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">我们一定要更加自觉地团结在以习近平同志为核心的党中央周围，坚持党的基本理论、基本路线、基本方略，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，持之以恒推进全面从严治党，深入推进新时代党的建设新的伟大工程，以党的自我革命引领社会革命，使我们党坚守初心使命，始终成为中国特色社会主义事业的坚强领导核心。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">我们一定要坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思想，坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合，坚持解放思想、实事求是、与时俱进、求真务实，勇于进行理论探索和创新，在新时代的伟大实践中不断开辟马克思主义中国化时代化新境界，让当代中国马克思主义放射出更加灿烂的真理光芒。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">我们一定要坚定不移坚持中国共产党领导、坚持中国特色社会主义，坚持把国家和民族发展放在自己力量的基点上、把中国发展进步的命运牢牢掌握在自己手中，团结一心为全面建成社会主义现代化强国、实现第二个百年奋斗目标而努力，以中国式现代化全面推进中华民族伟大复兴，推动构建人类命运共同体，创造人类文明新形态。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">我们一定要坚持全心全意为人民服务的根本宗旨，树牢群众观点，贯彻群众路线，尊重人民首创精神，坚持一切为了人民、一切依靠人民，从群众中来、到群众中去，始终保持同人民群众的血肉联系，始终同人民同呼吸、共命运、心连心。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">我们一定要努力学习“三个代表”重要思想，学习江泽民同志的革命精神和革命风范，学习他运用马克思主义立场、观点、方法研究新情况、解决新问题的科学态度和创造精神，为把我国建设成为富强民主文明和谐美丽的社会主义现代化强国而团结奋斗。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">中华民族的伟大复兴事业，凝结了包括江泽民同志在内的一代又一代共产党人的心血和奋斗。前进道路上，全党全军全国各族人民要在以习近平同志为核心的党中央坚强领导下，高举中国特色社会主义伟大旗帜，全面贯彻习近平新时代中国特色社会主义思想，弘扬伟大建党精神，坚定信心、同心同德，埋头苦干、奋勇前进，为全面建设社会主义现代化国家、全面推进中华民族伟大复兴而团结奋斗。</p><p style=\"font-family: &quot;Microsoft YaHei&quot;; font-size: 18px; margin-top: 1em; margin-bottom: 1em; padding: 0px; border: 0px; outline: 0px; box-sizing: border-box; color: rgb(51, 51, 51); white-space: normal; background-color: rgb(255, 255, 255); line-height: 2; text-indent: 2em; text-align: justify;\">江泽民同志永垂不朽！</p><p><br/></p>', '1669800968', '0', '204', '', '', '1669800980', '1669800980');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('309', '2', '1', '', '0', '0', '', '0', '0', '利用旧电脑安装nas系统 【黑裙（6.2x)】（附pat下载工具）', '<p style=\"line-height: 16px;\">此链接为安装6.x的资料，目前大多玩家已更新至7.x, 安装教程请移步至：<a href=\"{#ZC_BLOG_HOST#}?id=291\">自助引导式 DSM自举引导 [ arpl ] 【巴西佬】-有搞头-顺手记录一下，万一有搞头呢 (ljs.fun)</a></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"></p><!--autointro-->', '<p style=\"line-height: 16px;\">此链接为安装6.x的资料，目前大多玩家已更新至7.x, 安装教程请移步至：<a href=\"{#ZC_BLOG_HOST#}?id=291\">自助引导式 DSM自举引导 [ arpl ] 【巴西佬】-有搞头-顺手记录一下，万一有搞头呢 (ljs.fun)</a></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_pdf.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211211202367537811.pdf\" title=\"利用旧电脑搭建NAS(黑群晖) - 我心中的技术道 - CSDN博客.pdf\">利用旧电脑搭建NAS(黑群晖) - 我心中的技术道 - CSDN博客.pdf</a></p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_pdf.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211211202497919059.pdf\" title=\"2分钟教学群晖不关机实现修改SNMAC更改引导版本型号.pdf\">2分钟教学群晖不关机实现修改SNMAC更改引导版本型号.pdf</a></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">推荐引导：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211211202568864434.7z\" title=\"DS918+_6.23-25426-1.04b(V0.13.3驱动,半白,双网卡,改20SATA盘数).7z\">DS918+_6.23-25426-1.04b(V0.13.3驱动,半白,双网卡,改20SATA盘数).7z</a>&nbsp;#918的引导</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2023/01/202301131645014020248.rar\" title=\"DSM_DS918+_25426.rar\">DSM_DS918+_25426.rar</a>&nbsp;# 918的固件</p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211211206117331020.rar\" title=\"DSM_DS3617xs_23824.rar\">DSM_DS3617xs_23824.rar</a>&nbsp;# 3617的引导</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2023/01/202301131646132104788.rar\" title=\"DSM_DS3617xs_23824.rar\">DSM_DS3617xs_23824.rar</a>&nbsp;# 3617的固件</p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211211206525082978.rar\" title=\"ds3615xs1.03b支持6.2~6.22.rar\">ds3615xs1.03b支持6.2~6.22.rar</a>&nbsp;# 3615的引导</p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2023/07/202307131406535695932.rar\" title=\"下载pat链接.rar\">下载pat链接.rar</a># 用于下载旧版pat, 有些旧版pat官方已经隐藏下载链接，但此表算出的链接还是有效的。</p><p style=\"line-height: 16px;\">备用下载：<a href=\"https://ljs.fun:5245/%E7%B3%BB%E7%BB%9F/%E7%B3%BB%E7%BB%9F%E5%8C%85/%E9%BB%91%E7%B3%BB%E7%BB%9F/%E9%BB%91%E7%BE%A4%E6%99%96/pat\" _src=\"https://ljs.fun:5245/%E7%B3%BB%E7%BB%9F/%E7%B3%BB%E7%BB%9F%E5%8C%85/%E9%BB%91%E7%B3%BB%E7%BB%9F/%E9%BB%91%E7%BE%A4%E6%99%96/pat\">pat</a></p><p style=\"line-height: 16px;\">下载脚本：<img src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\" style=\"vertical-align: middle; margin-right: 2px;\"/><a href=\"{#ZC_BLOG_HOST#}zb_users/upload/2023/07/202307121617564566946.rar\" title=\"pat.rar\" style=\"font-size: 12px; color: rgb(0, 102, 204);\">pat.rar</a></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">推荐工具：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2023/01/202301131643397525012.rar\" title=\"OSFMount.rar\">OSFMount.rar</a>&nbsp;#加载引导文件，用于修改PID VID</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2023/01/202301131643395387447.rar\" title=\"win32_disk_imager.rar\">win32_disk_imager.rar</a>&nbsp;#刻录修改后的引导文件</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2023/01/202301131643392594582.rar\" title=\"芯片无忧.rar\">芯片无忧.rar</a>&nbsp;#查询优盘的PID VID</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2023/01/202301131643402032718.rar\" title=\"diskgenius.PartitionGuru.rar\">diskgenius.PartitionGuru.rar</a>&nbsp;#非必要软件</p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">推荐套件：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/11/202211261537441402361.zip\" title=\"破解版监控套件40路.zip\">破解版监控套件40路.zip</a>&nbsp;# DSM7.x 无法安装此套件，可选择安装7.x版本的DVA1622机型，标配8个摄像头证书，超过8个摄像头的用户建议安装6.x.</p><p style=\"line-height: 16px;\"><br/></p><p>注：</p><p>使用DS918+系统，需要把主板设置为UEFI启动，3615/3617需要设置为传统Legacy</p><p>黑系统请勿直接升级，升级必失联。</p><p>未洗白无法登录Quick Connect 服务。</p>', '1669003294', '0', '390', '', '', '1669003614', '1689228420');
