INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('75', '0', '1', '', '0', '0', '', '0', '0', 'drive x', '套件+APP.rar群晖drive x应用需要Drive Server 3.0 以上版本的套件支持，该套件支持安装在DSM6.2-25387版本以上，黑裙目前可以安装的最新版本是25426，是可以安装此套件的。通过套件中心安装或者用本文的离线安装包安装套件。app顶部的分类只能索引单账号home/drive下面的文件。不能索引团队文件夹，团队文件夹需要去团队文件夹查看&nbsp;&nbsp;不支持分类<!--autointro-->', '<p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/08/202108201502215584835.rar\" title=\"套件+APP.rar\">套件+APP.rar</a></p><p>群晖drive x应用需要Drive Server 3.0 以上版本的套件支持，<br/></p><p>该套件支持安装在DSM6.2-25387版本以上，黑裙目前可以安装的最新版本是25426，是可以安装此套件的。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/08/202108201454261451464.png\" alt=\"image.png\"/></p><p>通过套件中心安装或者用本文的离线安装包安装套件。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/08/202108201456236432156.png\" alt=\"image.png\"/></p><p><br/></p><p><br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/08/202108201503069983464.png\" alt=\"image.png\"/></p><p><br/></p><p><br/></p><p>app顶部的分类只能索引单账号home/drive下面的文件。</p><p>不能索引团队文件夹，团队文件夹需要去团队文件夹查看&nbsp;&nbsp;不支持分类</p>', '1629442295', '0', '222', '', '', '0', '1629442295');
