INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('117', '0', '1', '', '0', '0', '', '0', '0', '根据商品id查淘宝商品', 'https://item.taobao.com/item.htm?spm=a230r.1.14.121.2b152caeHsaNd0&amp;id=ID编码<!--autointro-->', '<p>https://item.taobao.com/item.htm?spm=a230r.1.14.121.2b152caeHsaNd0&amp;id=<strong>ID编码</strong></p>', '1636541380', '0', '179', '', '', '0', '1636541380');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('118', '0', '1', '', '0', '0', '', '0', '0', '隐藏某一个磁盘或分区', '在win系统中隐藏一个磁盘或分区，还保证能使用win+R，运行gpedit.msc按下图找到“隐藏我的电脑中这些指定的驱动器”设置为已启动，并选择要隐藏的分区或整个磁盘。未重启前在资源管理器左边的目录树中还可以看到这个磁盘，重启后完全消失，可以在地址栏输入D:&nbsp;访问隐藏的分区<!--autointro-->', '<p><br/></p><p>在win系统中隐藏一个磁盘或分区，还保证能使用</p><p>win+R，运行gpedit.msc</p><p>按下图找到“隐藏我的电脑中这些指定的驱动器”</p><p>设置为已启动，并选择要隐藏的分区或整个磁盘。</p><p>未重启前在资源管理器左边的目录树中还可以看到这个磁盘，重启后完全消失，可以在地址栏输入<strong>D:</strong>&nbsp;访问隐藏的分区</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/11/202111151717517735820.png\" alt=\"image.png\"/></p>', '1636967866', '0', '180', '', '', '0', '1636967866');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('119', '0', '1', '', '0', '0', '', '0', '0', 'excel 批量把超链接提取出来', '打开宏（ALT+F11）新建宏模块Function GetAdrs(Rng)Application.Volatile TrueWith Rng.Hyperlinks(1)GetAdrs = IIf(.Address = &quot;&quot;, .SubAddress, .Address)End WithEnd Function然后使用公式==GetAdrs(A1)下拉填充<!--autointro-->', '<p>打开宏（ALT+F11）</p><p>新建宏模块<br/></p><div class=\"_1T4GB1ESohOqTGNmwCAcuf \" style=\"max-width: 100%; overflow-x: visible; line-height: 24px; color: rgb(51, 51, 51); margin-top: 22px; font-family: arial; white-space: normal; background-color: rgb(255, 255, 255);\"><p style=\"margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-y: auto; max-width: 100%; line-height: 24px;\"><span class=\"bjh-p\" style=\"max-width: 100%;\">Function GetAdrs(Rng)</span></p></div><div class=\"_1T4GB1ESohOqTGNmwCAcuf \" style=\"max-width: 100%; overflow-x: visible; line-height: 24px; color: rgb(51, 51, 51); margin-top: 22px; font-family: arial; white-space: normal; background-color: rgb(255, 255, 255);\"><p style=\"margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-y: auto; max-width: 100%; line-height: 24px;\"><span class=\"bjh-p\" style=\"max-width: 100%;\">Application.Volatile True</span></p></div><div class=\"_1T4GB1ESohOqTGNmwCAcuf \" style=\"max-width: 100%; overflow-x: visible; line-height: 24px; color: rgb(51, 51, 51); margin-top: 22px; font-family: arial; white-space: normal; background-color: rgb(255, 255, 255);\"><p style=\"margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-y: auto; max-width: 100%; line-height: 24px;\"><span class=\"bjh-p\" style=\"max-width: 100%;\">With Rng.Hyperlinks(1)</span></p></div><div class=\"_1T4GB1ESohOqTGNmwCAcuf \" style=\"max-width: 100%; overflow-x: visible; line-height: 24px; color: rgb(51, 51, 51); margin-top: 22px; font-family: arial; white-space: normal; background-color: rgb(255, 255, 255);\"><p style=\"margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-y: auto; max-width: 100%; line-height: 24px;\"><span class=\"bjh-p\" style=\"max-width: 100%;\">GetAdrs = IIf(.Address = &quot;&quot;, .SubAddress, .Address)</span></p></div><div class=\"_1T4GB1ESohOqTGNmwCAcuf \" style=\"max-width: 100%; overflow-x: visible; line-height: 24px; color: rgb(51, 51, 51); margin-top: 22px; font-family: arial; white-space: normal; background-color: rgb(255, 255, 255);\"><p style=\"margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-y: auto; max-width: 100%; line-height: 24px;\"><span class=\"bjh-p\" style=\"max-width: 100%;\">End With</span></p></div><div class=\"_1T4GB1ESohOqTGNmwCAcuf \" style=\"max-width: 100%; overflow-x: visible; line-height: 24px; color: rgb(51, 51, 51); margin-top: 22px; font-family: arial; white-space: normal; background-color: rgb(255, 255, 255);\"><p style=\"margin-top: 0px; margin-bottom: 0px; padding: 0px; overflow-y: auto; max-width: 100%; line-height: 24px;\"><span class=\"bjh-p\" style=\"max-width: 100%;\">End Function</span></p></div><p><br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/11/202111191533139646691.gif\" alt=\"543e9756e583db7a48f4c332623f8f623376.gif\" title=\"543e9756e583db7a48f4c332623f8f623376.gif\"/></p><p>然后使用公式</p><p>=<span style=\"color: #333333; font-family: arial; background-color: #FFFFFF;\">=GetAdrs(<span style=\"font-family: arial; background-color: #FFFFFF; color: #4F81BD;\">A1</span>)</span></p><p><span style=\"color: #333333; font-family: arial; background-color: #FFFFFF;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/11/202111191536552612447.gif\" alt=\"769597b3a17b9a4aaf72c078d397ccd71217.gif\" title=\"769597b3a17b9a4aaf72c078d397ccd71217.gif\"/></span></p><p><br/></p><p>下拉填充</p>', '1637307037', '0', '205', '', '', '0', '1637307037');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('120', '0', '1', '', '0', '0', '', '0', '0', '快速获取网页页面所有图片地址', '在网页空白处右击，选择 使用迅雷下载全部链接勾选图片格式点击立即下载，下载完成后，在已完成列表里多选下载任务，复制下载链接粘贴到txt里即可。<!--autointro-->', '<p>在网页空白处右击，选择 使用迅雷下载全部链接<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/11/202111191556396212433.png\" alt=\"image.png\"/></p><p>勾选图片格式<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/11/202111191557076627048.png\" alt=\"image.png\"/></p><p>点击立即下载，下载完成后，在已完成列表里多选下载任务，复制下载链接</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/11/202111191558178127298.png\" alt=\"image.png\"/></p><p>粘贴到txt里即可。</p>', '1637308511', '0', '204', '', '', '0', '1637308511');
