INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('123', '0', '1', '', '0', '0', '', '0', '0', 'excel整列快速填充公式', '选中整列，在输入区输入第一行的公式，然后按ctrl+enter，直接填充整列公式<!--autointro-->', '<p>选中整列，在输入区输入第一行的公式，然后按ctrl+enter，直接填充整列公式</p>', '1637389659', '0', '231', '', '', '0', '1637389659');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('124', '2', '1', '', '0', '0', '', '0', '0', '去除 AMD 显卡的右键菜单', '<p style=\"box-sizing: border-box; outline: 0px; margin-top: 0px; margin-bottom: 16px; padding: 0px; color: rgb(77, 77, 77); overflow: auto hidden; overflow-wrap: break-word; font-family: -apple-system, &quot;SF UI Text&quot;, Arial, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif, SimHei, SimSun; white-space: normal; background-color: rgb(255, 255, 255); line-height: 26px !important;\"></p><!--autointro-->', '<p style=\"box-sizing: border-box; outline: 0px; margin-top: 0px; margin-bottom: 16px; padding: 0px; color: rgb(77, 77, 77); overflow: auto hidden; overflow-wrap: break-word; font-family: -apple-system, &quot;SF UI Text&quot;, Arial, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif, SimHei, SimSun; white-space: normal; background-color: rgb(255, 255, 255); line-height: 26px !important;\">1.同时按下 win+R&nbsp;组合键打开运行窗口，输入&nbsp;regedit.exe 然后点击“确定”，打开注册表，如图：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/11/202111201718312877334.png\" alt=\"image.png\"/></p><p>2.进入注册表编辑器，定位到HKEY_CLASSES_ROOT/Directory/Background/shellex/ContextMenuHandlers/ACE，删除 ACE 下的“数值数据”，即可删除右键 AMD 显卡菜单，如图：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/11/202111201719137919930.png\" alt=\"image.png\"/></p><p><br/></p><p>注：</p><p>作者的默认值是{5E2121EE-0300-11D4-8D3B-444553540000}</p>', '1637399875', '0', '251', '', '', '0', '1651717821');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('125', '0', '1', '', '0', '0', '', '0', '0', '飞机场samsock不能连接 自动退出 4294967295', '重置网络代理.batWin+X 管理员运行shell输入指令,回车,然后重启电脑netsh&nbsp;winsock&nbsp;reset<!--autointro-->', '<p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/02/202202101842258389276.bat\" title=\"重置网络代理.bat\">重置网络代理.bat</a></p><p style=\"line-height: 16px;\"><br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/11/202111221853298707750.png\" alt=\"image.png\"/><br/></p><p>Win+X 管理员运行shell<br/></p><p style=\"color: rgb(52, 73, 94); font-family: &quot;Source Sans Pro&quot;, &quot;Helvetica Neue&quot;, Arial, sans-serif; white-space: normal; background-color: rgb(254, 254, 254);\">输入指令,回车,然后重启电脑</p><div class=\"code-toolbar\" style=\"position: relative; color: rgb(52, 73, 94); font-family: &quot;Source Sans Pro&quot;, &quot;Helvetica Neue&quot;, Arial, sans-serif; white-space: normal; background-color: rgb(254, 254, 254);\"><pre class=\" language-markup\" style=\"overflow: auto; font-family: Consolas, Monaco, Menlo, Consolas, monospace; font-size: 13px; color: rgb(101, 123, 131); word-spacing: normal; word-break: normal; overflow-wrap: normal; line-height: 1.5; tab-size: 4; hyphens: none; padding: 7px; border-radius: 0.3em; background-color: rgb(248, 245, 236);\">netsh&nbsp;winsock&nbsp;reset</pre></div><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2021/11/202111221853536800416.png\" alt=\"image.png\"/></p>', '1637578282', '0', '257', '', '', '0', '1637578282');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('126', '0', '1', '', '0', '0', '', '0', '0', 'An(flash)导入音乐key帧', '把音乐拖到时间轴，新建一个图层，把要key的素材放在第一帧，选中这个图层点击播放，在需要key帧的位置按F6<!--autointro-->', '<p>把音乐拖到时间轴，新建一个图层，把要key的素材放在第一帧，选中这个图层点击播放，在需要key帧的位置按F6</p>', '1637807278', '0', '220', '', '', '0', '1637807278');
