INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('128', '0', '1', '', '0', '0', '', '0', '0', '黑群查看系统是否支持显卡硬解转码，查询核显驱动', '<p>SSH链接成功后，<strong>切到root账户</strong>。</p><p>输入<strong> ls /dev/dri </strong>之后若如下图显示，则说明支持显卡硬解。<br style=\"box-sizing: border-box; color: rgb(51, 51, 51); font-family: -apple-system, BlinkMacSystemFont, opensans, Optima, &quot;Microsoft Yahei&quot;, sans-serif; white-space: normal; background-color: rgb(241, 241, 241);\"/></p><!--autointro-->', '<p>SSH链接成功后，<strong>切到root账户</strong>。</p><p>输入<strong> ls /dev/dri </strong>之后若如下图显示，则说明支持显卡硬解。<br style=\"box-sizing: border-box; color: rgb(51, 51, 51); font-family: -apple-system, BlinkMacSystemFont, opensans, Optima, &quot;Microsoft Yahei&quot;, sans-serif; white-space: normal; background-color: rgb(241, 241, 241);\"/>输出 card0 renderD128 则支持，找不到目录 报错则不支持</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2022/03/202203041023599222719.png\" alt=\"image.png\"/></p>', '1637906778', '0', '202', '', '', '0', '1646360644');
