p;=&nbsp;&quot;DELETE&nbsp;FROM&nbsp;iptv_channels&nbsp;WHERE&nbsp;url&nbsp;=&nbsp;%s&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;cursor.execute(delete_query,&nbsp;(url,))\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;conn.commit()\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;print(f&quot;&#39;{url}&#39;&nbsp;已从数据库删除.&quot;)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;except&nbsp;Exception&nbsp;as&nbsp;e:\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;print(f&quot;删除失败：&nbsp;&#39;{url}&#39;:&nbsp;{e}&quot;)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;conn.rollback()\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;关闭数据库连接\r\n&nbsp;&nbsp;&nbsp;&nbsp;cursor.close()\r\n&nbsp;&nbsp;&nbsp;&nbsp;conn.close()\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;删除data.csv文件\r\n&nbsp;&nbsp;&nbsp;&nbsp;csv_file_path&nbsp;=&nbsp;&#39;data.csv&#39;\r\n&nbsp;&nbsp;&nbsp;&nbsp;try:\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;os.remove(csv_file_path)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;print(f&quot;临时文件：{csv_file_path}&nbsp;已清除。&quot;)\r\n&nbsp;&nbsp;&nbsp;&nbsp;except&nbsp;FileNotFoundError:\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;print(f&quot;{csv_file_path}&nbsp;文件不存在，无需删除。&quot;)\r\n&nbsp;&nbsp;&nbsp;&nbsp;except&nbsp;Exception&nbsp;as&nbsp;e:\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;print(f&quot;删除&nbsp;{csv_file_path}&nbsp;文件时出错：{e}&quot;)\r\n\r\nif&nbsp;__name__&nbsp;==&nbsp;&#39;__main__&#39;:\r\n&nbsp;&nbsp;&nbsp;&nbsp;outcsv();\r\n&nbsp;&nbsp;&nbsp;&nbsp;main();\r\n&nbsp;&nbsp;&nbsp;&nbsp;delchannel();</pre><p><br/></p>', '1705377853', '0', '275', '', '', '1705377988', '1705483931');
