INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('573', '2', '1', '', '0', '0', '', '0', '0', 'win10/11 登陆PC商店版WhatsApp', '<p>商店版下载安装地址：</p><p><a href=\"https://www.microsoft.com/store/productId/9NKSQGP7F2NH?ocid=pdpshare\" _src=\"https://www.microsoft.com/store/productId/9NKSQGP7F2NH?ocid=pdpshare\">https://www.microsoft.com/store/productId/9NKSQGP7F2NH?ocid=pdpshare</a> </p><!--autointro-->', '<p>商店版下载安装地址：</p><p><a href=\"https://www.microsoft.com/store/productId/9NKSQGP7F2NH?ocid=pdpshare\" _src=\"https://www.microsoft.com/store/productId/9NKSQGP7F2NH?ocid=pdpshare\">https://www.microsoft.com/store/productId/9NKSQGP7F2NH?ocid=pdpshare</a> </p><p><br/></p><p><strong>一般安装后，无法加载关联设备的二维码，或者使用手机号关联时短信发送失败，</strong></p><p><strong>此时需要修改Clash配置即可。</strong></p><p>先确定服务模式已安装。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/11/202411061142189834382.png\" alt=\"image.png\"/></p><p>在设置中找到uwp工具<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/11/202411061137281372003.png\" alt=\"image.png\"/></p><p>提示，直接点是<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/11/202411061137493476367.png\" alt=\"image.png\"/></p><p>全选，保存</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/11/202411061138157055414.png\" alt=\"image.png\"/></p><p>返回小猫，点tun模式旁边的齿轮<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/11/202411061138509747086.png\" alt=\"image.png\"/></p><p>点一下重置-保存<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/11/202411061139094364924.png\" alt=\"image.png\"/></p><p>开启tun模式，等一会即可正常加载二维码，如果关联失败，可尝试手机号码关联。<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/11/202411061139447962755.png\" alt=\"image.png\"/></p><p>测试登陆<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/11/202411061140076166075.png\" alt=\"image.png\"/></p>', '1730864064', '0', '203', '', '', '1730864411', '1730864555');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('582', '2', '1', '', '0', '0', '', '0', '0', '一键安装TVBOX聚合管理后台', '<p>脚本如下：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412181418538602820.sh\" title=\"update_xiaoya.sh\"></a></p><!--autointro-->', '<p>脚本如下：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412181418538602820.sh\" title=\"update_xiaoya.sh\">update_xiaoya.sh</a></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">修改BASE_DIR路径，存放程序缓存的文件，及自定义文件。</p><p style=\"line-height: 16px;\">此脚本在原作者基础上修改，增加了config和www目录，及更新PG,ZX的脚本的映射，方便自定义。</p><p style=\"line-height: 16px;\"><br/></p><p>代码内容如下：<br/></p><pre class=\"brush:bash;toolbar:false\">#!/bin/bash\r\n\r\nBASE_DIR=/volume3/docker/xiaoya-tvbox\r\nPORT1=4567\r\nPORT2=5344\r\nPORT3=5345\r\nTAG=&quot;latest&quot;\r\nUPDATE=false\r\nLOGS=false\r\nNET=&quot;&quot;\r\nMOUNT=&quot;&quot;\r\n\r\nusage(){\r\n&nbsp;&nbsp;echo&nbsp;&quot;Usage:&nbsp;$0&nbsp;[&nbsp;-d&nbsp;BASE_DIR&nbsp;]&nbsp;[&nbsp;-p&nbsp;PORT1&nbsp;]&nbsp;[&nbsp;-P&nbsp;PORT2&nbsp;]&nbsp;[&nbsp;-t&nbsp;TAG&nbsp;]&nbsp;[&nbsp;-v&nbsp;MOUNT&nbsp;]&nbsp;[&nbsp;-u&nbsp;]&nbsp;[&nbsp;-l&nbsp;]&quot;\r\n&nbsp;&nbsp;echo&nbsp;&quot;-d&nbsp;BASE_DIR&nbsp;&nbsp;&nbsp;&nbsp;数据目录，默认：/etc/xiaoya&quot;\r\n&nbsp;&nbsp;echo&nbsp;&quot;-p&nbsp;PORT1&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;管理界面端口，默认：4567&quot;\r\n&nbsp;&nbsp;echo&nbsp;&quot;-P&nbsp;PORT2&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;小雅AList端口，默认：5344&quot;\r\n&nbsp;&nbsp;echo&nbsp;&quot;-t&nbsp;TAG&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Docker镜像标签，默认：latest&quot;\r\n&nbsp;&nbsp;echo&nbsp;&quot;-u&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;检查镜像更新&quot;\r\n&nbsp;&nbsp;echo&nbsp;&quot;-l&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;输出docker日志&quot;\r\n&nbsp;&nbsp;echo&nbsp;&quot;-v&nbsp;Host:Docker&nbsp;路径挂载&quot;\r\n&nbsp;&nbsp;exit&nbsp;2\r\n}\r\n\r\nwhile&nbsp;getopts&nbsp;&quot;d:p:P:e:t:v:hul&quot;&nbsp;arg;&nbsp;do\r\n&nbsp;&nbsp;&nbsp;&nbsp;case&nbsp;&quot;${arg}&quot;&nbsp;in\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;d)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;BASE_DIR=${OPTARG}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;p)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PORT1=${OPTARG}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;P)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PORT2=${OPTARG}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;e)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PORT3=${OPTARG}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;t)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;TAG=${OPTARG}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;u)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;UPDATE=true\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;l)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;LOGS=true\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;v)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;MOUNT=&quot;${MOUNT}&nbsp;-v&nbsp;${OPTARG}&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;h)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;usage\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;*)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;esac\r\ndone\r\n\r\nmkdir&nbsp;-p&nbsp;&quot;$HOME/.config/atv&quot;\r\necho&nbsp;&quot;bridge&nbsp;${*}&quot;&nbsp;&gt;&nbsp;&quot;$HOME/.config/atv/cmd&quot;\r\n\r\nshift&nbsp;$((OPTIND-1))\r\n\r\nif&nbsp;[&nbsp;$#&nbsp;-gt&nbsp;0&nbsp;];&nbsp;then\r\n	BASE_DIR=$1\r\nfi\r\n\r\nif&nbsp;[&nbsp;$#&nbsp;-gt&nbsp;1&nbsp;];&nbsp;then\r\n	PORT1=$2\r\nfi\r\n\r\nif&nbsp;[&nbsp;$#&nbsp;-gt&nbsp;2&nbsp;];&nbsp;then\r\n	PORT2=$3\r\nfi\r\n\r\ncase&nbsp;&quot;$TAG&quot;&nbsp;in\r\n&nbsp;&nbsp;*host*)\r\n&nbsp;&nbsp;&nbsp;&nbsp;NET=&quot;--network&nbsp;host&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;-e&nbsp;&quot;\\e[36mhost网络模式\\e[0m&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;;;\r\nesac\r\n\r\necho&nbsp;-e&nbsp;&quot;\\e[36m使用配置目录：\\e[0m&nbsp;$BASE_DIR&quot;\r\n[&nbsp;&quot;$NET&quot;&nbsp;=&nbsp;&quot;&quot;&nbsp;]&nbsp;&amp;&amp;&nbsp;echo&nbsp;-e&nbsp;&quot;\\e[36m端口映射：\\e[0m&nbsp;$PORT1:4567&nbsp;&nbsp;$PORT2:80&quot;\r\n\r\necho&nbsp;-e&nbsp;&quot;\\e[33m默认端口变更为4567\\e[0m&quot;\r\n\r\nmkdir&nbsp;-p&nbsp;$BASE_DIR/CONF&nbsp;$BASE_DIR/WWW\r\n#&nbsp;官方更新方式\r\nPG_download=&#39;https://slink.ltd/https://raw.githubusercontent.com/power721/alist-tvbox/refs/heads/master/scripts/downloadPg.sh&#39;\r\nZX_download=&#39;https://slink.ltd/https://raw.githubusercontent.com/power721/alist-tvbox/refs/heads/master/scripts/downloadZx.sh&#39;\r\nif&nbsp;[&nbsp;!&nbsp;-f&nbsp;downloadPg.sh&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;curl&nbsp;-L&nbsp;-o&nbsp;downloadPg.sh&nbsp;&quot;$PG_download&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;curl&nbsp;-L&nbsp;-o&nbsp;downloadZx.sh&nbsp;&quot;$ZX_download&quot;\r\nfi\r\n\r\nif&nbsp;!&nbsp;grep&nbsp;&quot;access.mypikpak.com&quot;&nbsp;/etc/hosts&nbsp;&gt;/dev/null\r\nthen\r\n	echo&nbsp;-e&nbsp;&quot;127.0.0.1\\taccess.mypikpak.com&quot;&nbsp;&gt;&gt;&nbsp;/etc/hosts\r\nfi\r\n\r\ndocker&nbsp;container&nbsp;prune&nbsp;-f&nbsp;--filter&nbsp;&quot;label=MAINTAINER=Har01d&quot;\r\ndocker&nbsp;image&nbsp;prune&nbsp;-f&nbsp;--filter&nbsp;&quot;label=MAINTAINER=Har01d&quot;\r\ndocker&nbsp;volume&nbsp;prune&nbsp;-f&nbsp;--filter&nbsp;&quot;label=MAINTAINER=Har01d&quot;\r\n\r\nplatform=&quot;linux/amd64&quot;\r\nARCH=$(uname&nbsp;-m)\r\nif&nbsp;[&nbsp;&quot;$ARCH&quot;&nbsp;=&nbsp;&quot;armv7l&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;不支持的平台&quot;\r\n&nbsp;&nbsp;exit&nbsp;1\r\nelif&nbsp;[&nbsp;&quot;$ARCH&quot;&nbsp;=&nbsp;&quot;aarch64&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;platform=&quot;linux/arm64&quot;\r\nfi\r\n\r\nIMAGE_ID=$(docker&nbsp;images&nbsp;-q&nbsp;haroldli/xiaoya-tvbox:${TAG})\r\necho&nbsp;-e&nbsp;&quot;\\e[32m下载最新Docker镜像，平台：${platform},&nbsp;image&nbsp;tag:&nbsp;${TAG}\\e[0m&quot;\r\nfor&nbsp;i&nbsp;in&nbsp;1&nbsp;2&nbsp;3&nbsp;4&nbsp;5\r\ndo\r\n&nbsp;&nbsp;&nbsp;docker&nbsp;pull&nbsp;--platform&nbsp;${platform}&nbsp;haroldli/xiaoya-tvbox:${TAG}&nbsp;&amp;&amp;&nbsp;break\r\ndone\r\n\r\nNEW_IMAGE=$(docker&nbsp;images&nbsp;-q&nbsp;haroldli/xiaoya-tvbox:${TAG})\r\nif&nbsp;[&nbsp;&quot;$UPDATE&quot;&nbsp;=&nbsp;&quot;true&quot;&nbsp;]&nbsp;&amp;&amp;&nbsp;[&nbsp;&quot;$IMAGE_ID&quot;&nbsp;=&nbsp;&quot;$NEW_IMAGE&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;-e&nbsp;&quot;\\e[33m镜像没有更新\\e[0m&quot;\r\n&nbsp;&nbsp;exit\r\nfi\r\n\r\necho&nbsp;-e&nbsp;&quot;\\e[33m重启应用\\e[0m&quot;\r\ndocker&nbsp;rm&nbsp;-f&nbsp;xiaoya-tvbox&nbsp;2&gt;/dev/null\r\nif&nbsp;[&nbsp;&quot;$NET&quot;&nbsp;=&nbsp;&quot;&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;docker&nbsp;run&nbsp;-d&nbsp;-p&nbsp;$PORT1:4567&nbsp;-p&nbsp;$PORT2:80&nbsp;-e&nbsp;ALIST_PORT=$PORT2&nbsp;-v&nbsp;&quot;$BASE_DIR/CONF&quot;:/data&nbsp;-v&nbsp;&quot;$BASE_DIR/WWW&quot;:/www&nbsp;-v&nbsp;&quot;$BASE_DIR/downloadPg.sh&quot;:/downloadPg.sh&nbsp;-v&nbsp;&quot;$BASE_DIR/downloadZx.sh&quot;:/downloadZx.sh&nbsp;$MOUNT&nbsp;--restart=always&nbsp;--name=xiaoya-tvbox&nbsp;haroldli/xiaoya-tvbox:${TAG}\r\nelse\r\n&nbsp;&nbsp;docker&nbsp;run&nbsp;-d&nbsp;$NET&nbsp;-v&nbsp;&quot;$BASE_DIR/CONF&quot;:/data&nbsp;-v&nbsp;&quot;$BASE_DIR/WWW&quot;:/www&nbsp;-v&nbsp;&quot;$BASE_DIR/downloadPg.sh&quot;:/downloadPg.sh&nbsp;-v&nbsp;&quot;$BASE_DIR/downloadZx.sh&quot;:/downloadZx.sh&nbsp;$MOUNT&nbsp;--restart=always&nbsp;--name=xiaoya-tvbox&nbsp;haroldli/xiaoya-tvbox:${TAG}\r\nfi\r\n\r\necho&nbsp;-e&nbsp;&quot;\\n\\e[32m请使用以下命令查看日志输出：\\e[0m&quot;\r\necho&nbsp;-e&nbsp;&quot;&nbsp;&nbsp;&nbsp;&nbsp;docker&nbsp;logs&nbsp;-f&nbsp;xiaoya-tvbox\\n&quot;\r\n\r\nIP=$(ip&nbsp;a&nbsp;|&nbsp;grep&nbsp;-F&nbsp;&#39;192.168.&#39;&nbsp;|&nbsp;awk&nbsp;&#39;{print&nbsp;$2}&#39;&nbsp;|&nbsp;awk&nbsp;-F/&nbsp;&#39;{print&nbsp;$1}&#39;&nbsp;|&nbsp;head&nbsp;-1)\r\nif&nbsp;[&nbsp;-n&nbsp;&quot;$IP&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;&quot;\r\n&nbsp;&nbsp;echo&nbsp;-e&nbsp;&quot;\\e[32m请用以下地址访问：\\e[0m&quot;\r\n&nbsp;&nbsp;echo&nbsp;-e&nbsp;&quot;&nbsp;&nbsp;&nbsp;&nbsp;\\e[32m管理界面\\e[0m：&nbsp;http://$IP:$PORT1/&quot;\r\n&nbsp;&nbsp;echo&nbsp;-e&nbsp;&quot;&nbsp;&nbsp;&nbsp;&nbsp;\\e[32m小雅AList\\e[0m：&nbsp;http://$IP:$PORT2/&quot;\r\nelse\r\n&nbsp;&nbsp;IP=$(ip&nbsp;a&nbsp;|&nbsp;grep&nbsp;-F&nbsp;&#39;10.&#39;&nbsp;|&nbsp;awk&nbsp;&#39;{print&nbsp;$2}&#39;&nbsp;|&nbsp;awk&nbsp;-F/&nbsp;&#39;{print&nbsp;$1}&#39;&nbsp;|&nbsp;grep&nbsp;-E&nbsp;&#39;\\b10.&#39;&nbsp;|&nbsp;head&nbsp;-1)\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;-n&nbsp;&quot;$IP&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;&quot;\r\n	echo&nbsp;-e&nbsp;&quot;\\e[33m应用完整启动可能需要几分钟，请稍后...\\e[0m&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;-e&nbsp;&quot;\\e[32m请用以下地址访问：\\e[0m&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;-e&nbsp;&quot;&nbsp;&nbsp;&nbsp;&nbsp;\\e[32m管理界面\\e[0m：&nbsp;http://$IP:$PORT1/&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;-e&nbsp;&quot;&nbsp;&nbsp;&nbsp;&nbsp;\\e[32m小雅AList\\e[0m：&nbsp;http://$IP:$PORT2/&quot;\r\n&nbsp;&nbsp;fi\r\n&nbsp;&nbsp;echo&nbsp;-e&nbsp;&quot;\\e[32m云服务器请用公网IP访问\\e[0m&quot;\r\nfi\r\necho&nbsp;&quot;&quot;\r\n\r\nif&nbsp;[&nbsp;&quot;$LOGS&quot;&nbsp;=&nbsp;&quot;true&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;&quot;\r\n&nbsp;&nbsp;docker&nbsp;logs&nbsp;-f&nbsp;xiaoya-tvbox\r\nfi</pre><p><br/></p>', '1734502690', '0', '272', '', '', '1734502797', '1734502880');
