INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('575', '2', '1', '', '0', '0', '', '0', '0', '使用群晖计划任务更新DNSPOD的ddns记录', '<p>可以使用DNSPOD的api进行定时更新DDNS的IP记录，代码如下：</p><pre class=\"brush:bash;toolbar:false\">#!/bin/bash\r\n\r\n#&nbsp;DNSPod&nbsp;信息\r\nDP_Id=&quot;xxxxxx&quot;\r\nDP_Key=&quot;ae44b2216ea261e0efdxxxx94e0a216b&quot;\r\nDOMAIN=&quot;giraff.fun&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;主域名\r\n\r\n#&nbsp;记录\r\nSUB_DOMAIN=&quot;*&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;子域名\r\nRECORD_TYPE=&quot;A&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;记录类型\r\nRECORD_LINE=&quot;默认&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;线路类型\r\n\r\nAPI_TOKEN=&quot;${DP_Id},${DP_Key}&quot;&nbsp;&nbsp;#&nbsp;DNSPod&nbsp;API&nbsp;Token\r\n#&nbsp;自动获取本机的公网&nbsp;IPv4&nbsp;地址\r\nNEW_IP=$(curl&nbsp;-s4&nbsp;ifconfig.me)\r\n\r\n#&nbsp;确认&nbsp;NEW_IP&nbsp;已成功获取\r\nif&nbsp;[&nbsp;-z&nbsp;&quot;$NEW_IP&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;无法获取本机公网&nbsp;IPv4，请检查网络连接。&quot;\r\n&nbsp;&nbsp;exit&nbsp;1\r\nfi\r\n\r\necho&nbsp;&quot;本机公网&nbsp;IPv4&nbsp;为:&nbsp;$NEW_IP&quot;\r\n\r\n#&nbsp;获取解析记录列表\r\nresponse=$(curl&nbsp;-s&nbsp;-X&nbsp;POST&nbsp;https://dnsapi.cn/Record.List&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;login_token=${API_TOKEN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;format=json&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;domain=${DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;sub_domain=${SUB_DOMAIN}&quot;)\r\n\r\n#&nbsp;使用&nbsp;jq&nbsp;解析获取的&nbsp;Record&nbsp;ID\r\nRECORD_ID=$(echo&nbsp;&quot;$response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.records[0].id&#39;)\r\n\r\nif&nbsp;[&nbsp;-z&nbsp;&quot;$RECORD_ID&quot;&nbsp;]&nbsp;||&nbsp;[&nbsp;&quot;$RECORD_ID&quot;&nbsp;==&nbsp;&quot;null&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;记录不存在，创建新解析记录...&quot;\r\n\r\n&nbsp;&nbsp;#&nbsp;调用&nbsp;Record.Create&nbsp;API&nbsp;创建新解析记录\r\n&nbsp;&nbsp;create_response=$(curl&nbsp;-s&nbsp;-X&nbsp;POST&nbsp;https://dnsapi.cn/Record.Create&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;login_token=${API_TOKEN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;format=json&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;domain=${DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;sub_domain=${SUB_DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;record_type=${RECORD_TYPE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;record_line=${RECORD_LINE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;value=${NEW_IP}&quot;)\r\n\r\n&nbsp;&nbsp;#&nbsp;解析创建响应\r\n&nbsp;&nbsp;create_status_code=$(echo&nbsp;&quot;$create_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.code&#39;)\r\n&nbsp;&nbsp;create_status_message=$(echo&nbsp;&quot;$create_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.message&#39;)\r\n\r\n&nbsp;&nbsp;#&nbsp;判断是否创建成功\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;&quot;$create_status_code&quot;&nbsp;==&nbsp;&quot;1&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录创建成功:&nbsp;$create_status_message&quot;\r\n&nbsp;&nbsp;else\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录创建失败:&nbsp;$create_status_message&quot;\r\n&nbsp;&nbsp;fi\r\nelse\r\n&nbsp;&nbsp;echo&nbsp;&quot;记录已存在，更新解析记录...&quot;\r\n\r\n&nbsp;&nbsp;#&nbsp;发送&nbsp;POST&nbsp;请求更新&nbsp;DNS&nbsp;记录\r\n&nbsp;&nbsp;update_response=$(curl&nbsp;-s&nbsp;-X&nbsp;POST&nbsp;https://dnsapi.cn/Record.Modify&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;login_token=${API_TOKEN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;format=json&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;domain=${DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;record_id=${RECORD_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;sub_domain=${SUB_DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;record_type=${RECORD_TYPE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;record_line=${RECORD_LINE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;value=${NEW_IP}&quot;)\r\n\r\n&nbsp;&nbsp;#&nbsp;解析响应\r\n&nbsp;&nbsp;update_status_code=$(echo&nbsp;&quot;$update_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.code&#39;)\r\n&nbsp;&nbsp;update_status_message=$(echo&nbsp;&quot;$update_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.message&#39;)\r\n\r\n&nbsp;&nbsp;#&nbsp;判断是否更新成功\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;&quot;$update_status_code&quot;&nbsp;==&nbsp;&quot;1&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录更新成功:&nbsp;$update_status_message&quot;\r\n&nbsp;&nbsp;else\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录更新失败:&nbsp;$update_status_message&quot;\r\n&nbsp;&nbsp;fi\r\nfi</pre><!--autointro-->', '<p>可以使用DNSPOD的api进行定时更新DDNS的IP记录，代码如下：</p><pre class=\"brush:bash;toolbar:false\">#!/bin/bash\r\n\r\n#&nbsp;DNSPod&nbsp;信息\r\nDP_Id=&quot;xxxxxx&quot;\r\nDP_Key=&quot;ae44b2216ea261e0efdxxxx94e0a216b&quot;\r\nDOMAIN=&quot;giraff.fun&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;主域名\r\n\r\n#&nbsp;记录\r\nSUB_DOMAIN=&quot;*&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;子域名\r\nRECORD_TYPE=&quot;A&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;记录类型\r\nRECORD_LINE=&quot;默认&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;线路类型\r\n\r\nAPI_TOKEN=&quot;${DP_Id},${DP_Key}&quot;&nbsp;&nbsp;#&nbsp;DNSPod&nbsp;API&nbsp;Token\r\n#&nbsp;自动获取本机的公网&nbsp;IPv4&nbsp;地址\r\nNEW_IP=$(curl&nbsp;-s4&nbsp;ifconfig.me)\r\n\r\n#&nbsp;确认&nbsp;NEW_IP&nbsp;已成功获取\r\nif&nbsp;[&nbsp;-z&nbsp;&quot;$NEW_IP&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;无法获取本机公网&nbsp;IPv4，请检查网络连接。&quot;\r\n&nbsp;&nbsp;exit&nbsp;1\r\nfi\r\n\r\necho&nbsp;&quot;本机公网&nbsp;IPv4&nbsp;为:&nbsp;$NEW_IP&quot;\r\n\r\n#&nbsp;获取解析记录列表\r\nresponse=$(curl&nbsp;-s&nbsp;-X&nbsp;POST&nbsp;https://dnsapi.cn/Record.List&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;login_token=${API_TOKEN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;format=json&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;domain=${DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;sub_domain=${SUB_DOMAIN}&quot;)\r\n\r\n#&nbsp;使用&nbsp;jq&nbsp;解析获取的&nbsp;Record&nbsp;ID\r\nRECORD_ID=$(echo&nbsp;&quot;$response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.records[0].id&#39;)\r\n\r\nif&nbsp;[&nbsp;-z&nbsp;&quot;$RECORD_ID&quot;&nbsp;]&nbsp;||&nbsp;[&nbsp;&quot;$RECORD_ID&quot;&nbsp;==&nbsp;&quot;null&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;记录不存在，创建新解析记录...&quot;\r\n\r\n&nbsp;&nbsp;#&nbsp;调用&nbsp;Record.Create&nbsp;API&nbsp;创建新解析记录\r\n&nbsp;&nbsp;create_response=$(curl&nbsp;-s&nbsp;-X&nbsp;POST&nbsp;https://dnsapi.cn/Record.Create&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;login_token=${API_TOKEN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;format=json&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;domain=${DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;sub_domain=${SUB_DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;record_type=${RECORD_TYPE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;record_line=${RECORD_LINE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;value=${NEW_IP}&quot;)\r\n\r\n&nbsp;&nbsp;#&nbsp;解析创建响应\r\n&nbsp;&nbsp;create_status_code=$(echo&nbsp;&quot;$create_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.code&#39;)\r\n&nbsp;&nbsp;create_status_message=$(echo&nbsp;&quot;$create_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.message&#39;)\r\n\r\n&nbsp;&nbsp;#&nbsp;判断是否创建成功\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;&quot;$create_status_code&quot;&nbsp;==&nbsp;&quot;1&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录创建成功:&nbsp;$create_status_message&quot;\r\n&nbsp;&nbsp;else\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录创建失败:&nbsp;$create_status_message&quot;\r\n&nbsp;&nbsp;fi\r\nelse\r\n&nbsp;&nbsp;echo&nbsp;&quot;记录已存在，更新解析记录...&quot;\r\n\r\n&nbsp;&nbsp;#&nbsp;发送&nbsp;POST&nbsp;请求更新&nbsp;DNS&nbsp;记录\r\n&nbsp;&nbsp;update_response=$(curl&nbsp;-s&nbsp;-X&nbsp;POST&nbsp;https://dnsapi.cn/Record.Modify&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;login_token=${API_TOKEN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;format=json&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;domain=${DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;record_id=${RECORD_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;sub_domain=${SUB_DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;record_type=${RECORD_TYPE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;record_line=${RECORD_LINE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;value=${NEW_IP}&quot;)\r\n\r\n&nbsp;&nbsp;#&nbsp;解析响应\r\n&nbsp;&nbsp;update_status_code=$(echo&nbsp;&quot;$update_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.code&#39;)\r\n&nbsp;&nbsp;update_status_message=$(echo&nbsp;&quot;$update_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.message&#39;)\r\n\r\n&nbsp;&nbsp;#&nbsp;判断是否更新成功\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;&quot;$update_status_code&quot;&nbsp;==&nbsp;&quot;1&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录更新成功:&nbsp;$update_status_message&quot;\r\n&nbsp;&nbsp;else\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录更新失败:&nbsp;$update_status_message&quot;\r\n&nbsp;&nbsp;fi\r\nfi</pre><p><br/></p>', '1731563891', '0', '199', '', '', '1731563977', '1731563977');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('576', '2', '1', '', '0', '0', '', '0', '0', '使用群晖计划任务更新腾讯云的ddns记录', '<pre class=\"brush:bash;toolbar:false\">#!/bin/bash\r\n\r\n#&nbsp;自动获取本机的公网&nbsp;IPv4&nbsp;地址\r\nNEW_IP=$(curl&nbsp;-s4&nbsp;ifconfig.me)\r\n\r\n#&nbsp;腾讯云信息\r\nSECRET_ID=&quot;your_secret_id&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;腾讯云&nbsp;SecretId\r\nSECRET_KEY=&quot;your_secret_key&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;腾讯云&nbsp;SecretKey\r\nDOMAIN=&quot;giraff.fun&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;主域名\r\n\r\n#&nbsp;子域名和记录类型\r\nSUB_DOMAIN=&quot;*&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;子域名\r\nRECORD_TYPE=&quot;A&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;记录类型\r\nRECORD_LINE=&quot;default&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;线路类型\r\n\r\n#&nbsp;获取腾讯云的&nbsp;DomainId（通过&nbsp;DescribeDomains&nbsp;API&nbsp;查询）\r\nresponse=$(curl&nbsp;-s&nbsp;-X&nbsp;GET&nbsp;&quot;https://cns.api.qcloud.com/v2/index.php&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;Action=DescribeDomains&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;Region=ap-guangzhou&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;SecretId=${SECRET_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;SecretKey=${SECRET_KEY}&quot;)\r\n\r\n#&nbsp;解析&nbsp;DomainId\r\nDOMAIN_ID=$(echo&nbsp;&quot;$response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&quot;.Domains.Domain[]&nbsp;|&nbsp;select(.DomainName==\\&quot;${DOMAIN}\\&quot;)&nbsp;|&nbsp;.DomainId&quot;)\r\n\r\n#&nbsp;检查是否成功获取&nbsp;DomainId\r\nif&nbsp;[&nbsp;-z&nbsp;&quot;$DOMAIN_ID&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;未能找到域名&nbsp;${DOMAIN}&nbsp;的&nbsp;DomainId，请检查域名是否正确。&quot;\r\n&nbsp;&nbsp;exit&nbsp;1\r\nfi\r\n\r\necho&nbsp;&quot;获取的&nbsp;DomainId&nbsp;为:&nbsp;$DOMAIN_ID&quot;\r\n\r\n#&nbsp;确认&nbsp;NEW_IP&nbsp;已成功获取\r\nif&nbsp;[&nbsp;-z&nbsp;&quot;$NEW_IP&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;无法获取本机公网&nbsp;IPv4，请检查网络连接。&quot;\r\n&nbsp;&nbsp;exit&nbsp;1\r\nfi\r\n\r\necho&nbsp;&quot;本机公网&nbsp;IPv4&nbsp;为:&nbsp;$NEW_IP&quot;\r\n\r\n#&nbsp;获取解析记录列表\r\nresponse=$(curl&nbsp;-s&nbsp;-X&nbsp;GET&nbsp;&quot;https://cns.api.qcloud.com/v2/index.php&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;Action=DescribeRecordList&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;Region=ap-guangzhou&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;DomainId=${DOMAIN_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;SubDomain=${SUB_DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;RecordType=${RECORD_TYPE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;SecretId=${SECRET_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;-d&nbsp;&quot;SecretKey=${SECRET_KEY}&quot;)\r\n\r\n#&nbsp;使用&nbsp;jq&nbsp;解析获取的&nbsp;Record&nbsp;ID\r\nRECORD_ID=$(echo&nbsp;&quot;$response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.RecordList[0].RecordId&#39;)\r\n\r\nif&nbsp;[&nbsp;-z&nbsp;&quot;$RECORD_ID&quot;&nbsp;]&nbsp;||&nbsp;[&nbsp;&quot;$RECORD_ID&quot;&nbsp;==&nbsp;&quot;null&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;记录不存在，创建新解析记录...&quot;\r\n\r\n&nbsp;&nbsp;#&nbsp;调用&nbsp;CreateRecord&nbsp;API&nbsp;创建新解析记录\r\n&nbsp;&nbsp;create_response=$(curl&nbsp;-s&nbsp;-X&nbsp;GET&nbsp;&quot;https://cns.api.qcloud.com/v2/index.php&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;Action=CreateRecord&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;Region=ap-guangzhou&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;DomainId=${DOMAIN_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;SubDomain=${S