&nbsp;&nbsp;create_response=$(curl&nbsp;-s&nbsp;-X&nbsp;GET&nbsp;&quot;https://cns.api.qcloud.com/v2/index.php&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;Action=CreateRecord&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;Region=ap-guangzhou&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;DomainId=${DOMAIN_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;SubDomain=${SUB_DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;RecordType=${RECORD_TYPE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;RecordLine=${RECORD_LINE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;Value=${NEW_IP}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;SecretId=${SECRET_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;SecretKey=${SECRET_KEY}&quot;)\r\n\r\n&nbsp;&nbsp;#&nbsp;解析创建响应\r\n&nbsp;&nbsp;create_status_code=$(echo&nbsp;&quot;$create_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.code&#39;)\r\n&nbsp;&nbsp;create_status_message=$(echo&nbsp;&quot;$create_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.message&#39;)\r\n\r\n&nbsp;&nbsp;#&nbsp;判断是否创建成功\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;&quot;$create_status_code&quot;&nbsp;==&nbsp;&quot;1&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录创建成功:&nbsp;$create_status_message&quot;\r\n&nbsp;&nbsp;else\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录创建失败:&nbsp;$create_status_message&quot;\r\n&nbsp;&nbsp;fi\r\nelse\r\n&nbsp;&nbsp;echo&nbsp;&quot;记录已存在，更新解析记录...&quot;\r\n\r\n&nbsp;&nbsp;#&nbsp;发送&nbsp;POST&nbsp;请求更新&nbsp;DNS&nbsp;记录\r\n&nbsp;&nbsp;update_response=$(curl&nbsp;-s&nbsp;-X&nbsp;GET&nbsp;&quot;https://cns.api.qcloud.com/v2/index.php&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;Action=ModifyRecord&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;Region=ap-guangzhou&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;DomainId=${DOMAIN_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;RecordId=${RECORD_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;SubDomain=${SUB_DOMAIN}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;RecordType=${RECORD_TYPE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;RecordLine=${RECORD_LINE}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;Value=${NEW_IP}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;SecretId=${SECRET_ID}&quot;&nbsp;\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;-d&nbsp;&quot;SecretKey=${SECRET_KEY}&quot;)\r\n\r\n&nbsp;&nbsp;#&nbsp;解析响应\r\n&nbsp;&nbsp;update_status_code=$(echo&nbsp;&quot;$update_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.code&#39;)\r\n&nbsp;&nbsp;update_status_message=$(echo&nbsp;&quot;$update_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status.message&#39;)\r\n\r\n&nbsp;&nbsp;#&nbsp;判断是否更新成功\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;&quot;$update_status_code&quot;&nbsp;==&nbsp;&quot;1&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录更新成功:&nbsp;$update_status_message&quot;\r\n&nbsp;&nbsp;else\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录更新失败:&nbsp;$update_status_message&quot;\r\n&nbsp;&nbsp;fi\r\nfi</pre><p><br/></p>', '1731564300', '0', '190', '', '', '1731564321', '1731564321');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('577', '2', '1', '', '0', '0', '', '0', '0', '使用群晖计划任务更新阿里云的ddns记录', '<pre class=\"brush:bash;toolbar:false\">#!/bin/bash\r\n\r\n#&nbsp;自动获取本机的公网&nbsp;IPv4&nbsp;地址\r\nNEW_IP=$(curl&nbsp;-s4&nbsp;ifconfig.me)\r\n\r\n#&nbsp;阿里云信息\r\nDOMAIN=&quot;giraff.fun&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;域名\r\nACCESS_KEY_ID=&quot;your_access_key_id&quot;&nbsp;&nbsp;#&nbsp;阿里云&nbsp;AccessKey&nbsp;ID\r\nACCESS_KEY_SECRET=&quot;your_access_key_secret&quot;&nbsp;&nbsp;#&nbsp;阿里云&nbsp;AccessKey&nbsp;Secret\r\nSUB_DOMAIN=&quot;*&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;子域名\r\nRECORD_TYPE=&quot;A&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;记录类型\r\nRECORD_LINE=&quot;default&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;线路类型\r\n\r\n#&nbsp;阿里云&nbsp;API&nbsp;请求的基本参数\r\nENDPOINT=&quot;http://dns.aliyuncs.com&quot;\r\nVERSION=&quot;2015-01-09&quot;\r\nACTION=&quot;DescribeDomainRecords&quot;\r\n\r\n#&nbsp;获取请求当前时间\r\nTIMESTAMP=$(date&nbsp;-u&nbsp;+&quot;%Y-%m-%dT%H:%M:%SZ&quot;)\r\n\r\n#&nbsp;构建请求参数\r\nPARAMS=&quot;Action=$ACTION&amp;DomainName=$DOMAIN&amp;AccessKeyId=$ACCESS_KEY_ID&amp;Timestamp=$TIMESTAMP&amp;SignatureMethod=HMAC-SHA1&amp;SignatureVersion=1.0&amp;SignatureNonce=$(uuidgen)&amp;Format=JSON&quot;\r\n\r\n#&nbsp;签名计算\r\nSIGNATURE=$(echo&nbsp;-n&nbsp;&quot;GET&amp;%2F&amp;$(echo&nbsp;-n&nbsp;&quot;$PARAMS&quot;&nbsp;|&nbsp;sed&nbsp;&#39;s/&amp;/%26/g&#39;)&quot;&nbsp;|&nbsp;openssl&nbsp;dgst&nbsp;-sha1&nbsp;-hmac&nbsp;&quot;$ACCESS_KEY_SECRET&amp;&quot;&nbsp;-binary&nbsp;|&nbsp;base64)\r\n\r\n#&nbsp;发起请求，查询域名记录\r\nresponse=$(curl&nbsp;-s&nbsp;-G&nbsp;&quot;$ENDPOINT&quot;&nbsp;--data-urlencode&nbsp;&quot;$PARAMS&amp;Signature=$SIGNATURE&quot;)\r\n\r\n#&nbsp;提取记录的&nbsp;ID\r\nRECORD_ID=$(echo&nbsp;&quot;$response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.DomainRecords.Record[0].RecordId&#39;)\r\n\r\nif&nbsp;[&nbsp;-z&nbsp;&quot;$RECORD_ID&quot;&nbsp;]&nbsp;||&nbsp;[&nbsp;&quot;$RECORD_ID&quot;&nbsp;==&nbsp;&quot;null&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;记录不存在，创建新解析记录...&quot;\r\n\r\n&nbsp;&nbsp;#&nbsp;创建新的解析记录\r\n&nbsp;&nbsp;ACTION=&quot;AddDomainRecord&quot;\r\n&nbsp;&nbsp;create_response=$(curl&nbsp;-s&nbsp;-G&nbsp;&quot;$ENDPOINT&quot;&nbsp;--data-urlencode&nbsp;&quot;Action=$ACTION&amp;DomainName=$DOMAIN&amp;RR=$SUB_DOMAIN&amp;Type=$RECORD_TYPE&amp;Value=$NEW_IP&amp;AccessKeyId=$ACCESS_KEY_ID&amp;Timestamp=$TIMESTAMP&amp;SignatureMethod=HMAC-SHA1&amp;SignatureVersion=1.0&amp;SignatureNonce=$(uuidgen)&amp;Format=JSON&amp;Signature=$SIGNATURE&quot;)\r\n\r\n&nbsp;&nbsp;#&nbsp;解析创建响应\r\n&nbsp;&nbsp;create_status_code=$(echo&nbsp;&quot;$create_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.Code&#39;)\r\n&nbsp;&nbsp;create_status_message=$(echo&nbsp;&quot;$create_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.Message&#39;)\r\n\r\n&nbsp;&nbsp;#&nbsp;判断是否创建成功\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;&quot;$create_status_code&quot;&nbsp;==&nbsp;&quot;OK&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录创建成功:&nbsp;$create_status_message&quot;\r\n&nbsp;&nbsp;else\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录创建失败:&nbsp;$create_status_message&quot;\r\n&nbsp;&nbsp;fi\r\nelse\r\n&nbsp;&nbsp;echo&nbsp;&quot;记录已存在，更新解析记录...&quot;\r\n\r\n&nbsp;&nbsp;#&nbsp;更新现有的解析记录\r\n&nbsp;&nbsp;ACTION=&quot;UpdateDomainRecord&quot;\r\n&nbsp;&nbsp;update_response=$(curl&nbsp;-s&nbsp;-G&nbsp;&quot;$ENDPOINT&quot;&nbsp;--data-urlencode&nbsp;&quot;Action=$ACTION&amp;DomainName=$DOMAIN&amp;RecordId=$RECORD_ID&amp;RR=$SUB_DOMAIN&amp;Type=$RECORD_TYPE&amp;Value=$NEW_IP&amp;AccessKeyId=$ACCESS_KEY_ID&amp;Timestamp=$TIMESTAMP&amp;SignatureMethod=HMAC-SHA1&amp;SignatureVersion=1.0&amp;SignatureNonce=$(uuidgen)&amp;Format=JSON&amp;Signature=$SIGNATURE&quot;)\r\n\r\n&nbsp;&nbsp;#&nbsp;解析更新响应\r\n&nbsp;&nbsp;update_status_code=$(echo&nbsp;&quot;$update_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.Code&#39;)\r\n&nbsp;&nbsp;update_status_message=$(echo&nbsp;&quot;$update_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.Message&#39;)\r\n\r\n&nbsp;&nbsp;#&nbsp;判断是否更新成功\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;&quot;$update_status_code&quot;&nbsp;==&nbsp;&quot;OK&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录更新成功:&nbsp;$update_status_message&quot;\r\n&nbsp;&nbsp;else\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录更新失败:&nbsp;$update_status_message&quot;\r\n&nbsp;&nbsp;fi\r\nfi</pre><!--autointro-->', '<pre class=\"brush:bash;toolbar:false\">#!/bin/bash\r\n\r\n#&nbsp;自动获取本机的公网&nbsp;IPv4&nbsp;地址\r\nNEW_IP=$(curl&nbsp;-s4&nbsp;ifconfig.me)\r\n\r\n#&nbsp;阿里云信息\r\nDOMAIN=&quot;giraff.fun&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;域名\r\nACCESS_KEY_ID=&quot;your_access_key_id&quot;&nbsp;&nbsp;#&nbsp;阿里云&nbsp;AccessKey&nbsp;ID\r\nACCESS_KEY_SECRET=&quot;your_access_key_secret&quot;&nbsp;&nbsp;#&nbsp;阿里云&nbsp;AccessKey&nbsp;Secret\r\nSUB_DOMAIN=&quot;*&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;子域名\r\nRECORD_TYPE=&quot;A&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;记录类型\r\nRECORD_LINE=&quot;default&quot;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;线路类型\r\n\r\n#&nbsp;阿里云&nbsp;API&nbsp;请求的基本参数\r\nENDPOINT=&quot;http://dns.aliyuncs.com&quot;\r\nVERSION=&quot;2015-01-09&quot;\r\nACTION=&quot;DescribeDomainRecords&quot;\r\n\r\n#&nbsp;获取请求当前时间\r\nTIMESTAMP=$(date&nbsp;-u&nbsp;+&quot;%Y-%m-%dT%H:%M:%SZ&quot;)\r\n\r\n#&nbsp;构建请求参数\r\nPARAMS=&quot;Action=$ACTION&amp;DomainName=$DOMAIN&amp;AccessKeyId=$ACCESS_KEY_ID&amp;Timestamp=$TIMESTAMP&amp;SignatureMethod=HMAC-SHA1&amp;SignatureVersion=1.0&amp;SignatureNonce=$(uuidgen)&amp;Format=JSON&quot;\r\n\r\n#&nbsp;签名计算\r\nSIGNATURE=$(echo&nbsp;-n&nbsp;&quot;GET&amp;%2F&amp;$(echo&nbsp;-n&nbsp;&quot;$PARAMS&quot;&nbsp;|&nbsp;sed&nbsp;&#39;s/&amp;/%26/g&#39;)&quot;&nbsp;|&nbsp;openssl&nbsp;dgst&nbsp;-sha1&nbsp;-hmac&nbsp;&quot;$ACCESS_KEY_SECRET&amp;&quot;&nbsp;-binary&nbsp;|&nbsp;base64)\r\n\r\n#&nbsp;发起请求，查询域名记录\r\nresponse=$(curl&nbsp;-s&nbsp;-G&nbsp;&quot;$ENDPOINT&quot;&nbsp;--data-urlencode&nbsp;&quot;$PARAMS&amp;Signature=$SIGNATURE&quot;)\r\n\r\n#&nbsp;提取记录的&nbsp;ID\r\nRECORD_ID=$(echo&nbsp;&quot;$response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.DomainRecords.Record[0].RecordId&#39;)\r\n\r\nif&nbsp;[&nbsp;-z&nbsp;&quot;$RECORD_ID&quot;&nbsp;]&nbsp;||&nbsp;[&nbsp;&quot;$RECORD_ID&quot;&nbsp;==&nbsp;&quot;null&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;echo&nbsp;&quot;记录不存在，创建新解析记录...&quot;\r\n\r\n&nbsp;&nbsp;#&nbsp;创建新的解析记录\r\n&nbsp;&nbsp;ACTION=&quot;AddDomainRecord&quot;\r\n&nbsp;&nbsp;create_response=$(curl&nbsp;-s&nbsp;-G&nbsp;&quot;$ENDPOINT&quot;&nbsp;--data-urlencode&nbsp;&quot;Action=$ACTION&amp;DomainName=$DOMAIN&amp;RR=$SUB_DOMAIN&amp;Type=$RECORD_TYPE&amp;Value=$NEW_IP&amp;AccessKeyId=$ACCESS_KEY_ID&amp;Timestamp=$TIMESTAMP&amp;SignatureMethod=HMAC-SHA1&amp;SignatureVersion=1.0&amp;SignatureNonce=$(uuidgen)&amp;Format=JSON&amp;Signature=$SIGNATURE&quot;)\r\n\r\n&nbsp;&nbsp;#&nbsp;解析创建响应\r\n&nbsp;&nbsp;create_status_code=$(echo&nbsp;&quot;$create_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.Code&#39;)\r\n&nbsp;&nbsp;create_status_message=$(echo&nbsp;&quot;$create_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.Message&#39;)\r\n\r\n&nbsp;&nbsp;#&nbsp;判断是否创建成功\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;&quot;$create_status_code&quot;&nbsp;==&nbsp;&quot;OK&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录创建成功:&nbsp;$create_status_message&quot;\r\n&nbsp;&nbsp;else\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录创建失败:&nbsp;$create_status_message&quot;\r\n&nbsp;&nbsp;fi\r\nelse\r\n&nbsp;&nbsp;echo&nbsp;&quot;记录已存在，更新解析记录...&quot;\r\n\r\n&nbsp;&nbsp;#&nbsp;更新现有的解析记录\r\n&nbsp;&nbsp;ACTION=&quot;UpdateDomainRecord&quot;\r\n&nbsp;&nbsp;update_response=$(curl&nbsp;-s&nbsp;-G&nbsp;&quot;$ENDPOINT&quot;&nbsp;--data-urlencode&nbsp;&quot;Action=$ACTION&amp;DomainName=$DOMAIN&amp;RecordId=$RECORD_ID&amp;RR=$SUB_DOMAIN&amp;Type=$RECORD_TYPE&amp;Value=$NEW_IP&amp;AccessKeyId=$ACCESS_KEY_ID&amp;Timestamp=$TIMESTAMP&amp;SignatureMethod=HMAC-SHA1&amp;SignatureVersion=1.0&amp;SignatureNonce=$(uuidgen)&amp;Format=JSON&amp;Signature=$SIGNATURE&quot;)\r\n\r\n&nbsp;&nbsp;#&nbsp;解析更新响应\r\n&nbsp;&nbsp;update_status_code=$(echo&nbsp;&quot;$update_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.Code&#39;)\r\n&nbsp;&nbsp;update_status_message=$(echo&nbsp;&quot;$update_response&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.Message&#39;)\r\n\r\n&nbsp;&nbsp;#&nbsp;判断是否更新成功\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;&quot;$update_status_code&quot;&nbsp;==&nbsp;&quot;OK&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录更新成功:&nbsp;$update_status_message&quot;\r\n&nbsp;&nbsp;else\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;DNS&nbsp;记录更新失败:&nbsp;$update_status_message&quot;\r\n&nbsp;&nbsp;fi\r\nfi</pre><p><br/></p>', '1731564439', '0', '193', '', '', '1731564462', '1731564462');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('578', '2', '1', '', '0', '0', '', '0', '0', '一键修改emby的UI', '<p>项目地址：<a href=\"https://github.com/Nolovenodie/emby-crx\">Nolovenodie/emby-crx: Emby 增强/美化 插件 (适用于 Chrome 内核浏览器 / EmbyServer)</a></p><p>一键脚本：<img src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\" style=\"vertical-align: middle; margin-right: 2px;\"/></p><!--autointro-->', '<p>项目地址：<a href=\"https://github.com/Nolovenodie/emby-crx\">Nolovenodie/emby-crx: Emby 增强/美化 插件 (适用于 Chrome 内核浏览器 / EmbyServer)</a></p><p>一键脚本：<img src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\" style=\"vertical-align: middle; margin-right: 2px;\"/><a href=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/11/202411231042273834353.sh\" title=\"embyui.sh\" style=\"font-size: 12px; color: rgb(0, 102, 204);\">embyui.sh</a></p><p>安装后，重启emby生效</p><p><br/></p><p>脚本内容：<br/></p><pre class=\"brush:cpp;toolbar:false\">#!&nbsp;/bin/bash\r\n\r\necho&nbsp;&quot;查找emby安装目录...&quot;\r\n#&nbsp;查找&nbsp;emby&nbsp;UI&nbsp;的目录\r\nUI_local=$(find&nbsp;/&nbsp;-type&nbsp;d&nbsp;-name&nbsp;&quot;dashboard-ui&quot;&nbsp;-print&nbsp;-quit&nbsp;2&gt;/dev/null)\r\n\r\n#&nbsp;如果找不到目录，退出脚本\r\nif&nbsp;[&nbsp;-z&nbsp;&quot;$UI_local&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;emby安装目录未找到!&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;exit&nbsp;1\r\nfi\r\n\r\n#&nbsp;切换到找到的目录\r\ncd&nbsp;&quot;$UI_local&quot;&nbsp;||&nbsp;exit\r\n\r\n#&nbsp;github加速\r\nproxy=&quot;https://gh.llkk.cc/&quot;\r\n\r\n#&nbsp;创建&nbsp;emby-crx&nbsp;目录并下载所需文件\r\nrm&nbsp;-rf&nbsp;emby-crx\r\nmkdir&nbsp;-p&nbsp;emby-crx\r\nwget&nbsp;${proxy}https://raw.githubusercontent.com/Nolovenodie/emby-crx/master/static/css/style.css&nbsp;-P&nbsp;emby-crx/\r\nwget&nbsp;${proxy}https://raw.githubusercontent.com/Nolovenodie/emby-crx/master/static/js/common-utils.js&nbsp;-P&nbsp;emby-crx/\r\nwget&nbsp;${proxy}https://raw.githubusercontent.com/Nolovenodie/emby-crx/master/static/js/jquery-3.6.0.min.js&nbsp;-P&nbsp;emby-crx/\r\nwget&nbsp;${proxy}https://raw.githubusercontent.com/Nolovenodie/emby-crx/master/static/js/md5.min.js&nbsp;-P&nbsp;emby-crx/\r\nwget&nbsp;${proxy}https://raw.githubusercontent.com/Nolovenodie/emby-crx/master/content/main.js&nbsp;-P&nbsp;emby-crx/\r\n\r\n#&nbsp;检查&nbsp;index.html&nbsp;是否存在\r\nif&nbsp;[&nbsp;!&nbsp;-f&nbsp;index.html&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;index.html&nbsp;not&nbsp;found&nbsp;in&nbsp;$UI_local!&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;exit&nbsp;1\r\nfi\r\n\r\n#&nbsp;检查&nbsp;index.html&nbsp;是否包含&nbsp;emby-crx\r\nif&nbsp;grep&nbsp;-q&nbsp;&quot;emby-crx&quot;&nbsp;index.html;&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;index.html&nbsp;already&nbsp;contains&nbsp;emby-crx,&nbsp;skipping&nbsp;insertion.&quot;\r\nelse\r\n&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;定义要插入的代码\r\n&nbsp;&nbsp;&nbsp;&nbsp;code=&#39;&lt;link&nbsp;rel=&quot;stylesheet&quot;&nbsp;id=&quot;theme-css&quot;&nbsp;href=&quot;emby-crx/style.css&quot;&nbsp;type=&quot;text/css&quot;&nbsp;media=&quot;all&quot;&nbsp;/&gt;\\n&lt;script&nbsp;src=&quot;emby-crx/common-utils.js&quot;&gt;&lt;/script&gt;\\n&lt;script&nbsp;src=&quot;emby-crx/jquery-3.6.0.min.js&quot;&gt;&lt;/script&gt;\\n&lt;script&nbsp;src=&quot;emby-crx/md5.min.js&quot;&gt;&lt;/script&gt;\\n&lt;script&nbsp;src=&quot;emby-crx/main.js&quot;&gt;&lt;/script&gt;&#39;\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;在&nbsp;&lt;/head&gt;&nbsp;之前插入代码\r\n&nbsp;&nbsp;&nbsp;&nbsp;sed&nbsp;-i&nbsp;&quot;/&lt;\\/head&gt;/i&nbsp;$code&quot;&nbsp;index.html\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;Inserted&nbsp;emby-crx&nbsp;code&nbsp;into&nbsp;index.html.&quot;\r\nfi</pre><p><br/></p>', '1732329698', '0', '206', '', '', '1732329767', '1732329789');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('581', '2', '1', '', '0', '0', '', '0', '0', '将肥羊allinone添加到天光云影观看直播节目', '<p>天光云影app下载：<br/></p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501031159014905654.apk\" title=\"mytv-android-tv-3.3.8.apk\"></a></p><!--autointro-->', '<p>天光云影app下载：<br/></p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501031159014905654.apk\" title=\"mytv-android-tv-3.3.8.apk\">mytv-android-tv-3.3.8.apk</a>&nbsp;#已修改默认直播源为肥羊，默认<span style=\"text-wrap-mode: wrap;\">无直播频道，</span>需要手动上传肥羊allinone，或自行推送订阅源</p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">肥羊allinone（需要解压后使用）:</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501031201392120715.zip\" title=\"allinone_linux_arm64_20250101150436.zip\">allinone_linux_arm64_20250101150436.zip</a></p><p style=\"line-height: 16px;\">更新地址：<a href=\"https://pan.v1.mk/%E6%AF%8F%E6%9C%9F%E8%A7%86%E9%A2%91%E4%B8%AD%E7%94%A8%E5%88%B0%E7%9A%84%E6%96%87%E4%BB%B6%E5%88%86%E4%BA%AB/allinone%E4%BA%8C%E8%BF%9B%E5%88%B6%E6%96%87%E4%BB%B6\">影视/教程汇总</a></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">allinone文件解压后，放在手机download目录里。</p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">获取三参：</p><p style=\"line-height: 16px;\">ALLINONE指令生成器：<a href=\"https://imgtool.v1.mk/allinone.html\" _src=\"https://imgtool.v1.mk/allinone.html\">https://imgtool.v1.mk/allinone.html</a> </p><p style=\"line-height: 16px;\">在此网站生成专属密钥</p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501031203455807171.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">ALLINONE鉴权机器人：<a href=\"https://t.me/newallinone_bot\" _src=\"https://t.me/newallinone_bot\">https://t.me/newallinone_bot</a> </p><p style=\"line-height: 16px;\">在tg上关注此机器人，根据提示获取id和token</p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501031204135337855.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\">根据提示，把id和token填写到生成器网页，</p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501031205232592842.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\">生成部署命令后，复制直接运行命令</p><p style=\"line-height: 16px;\"><br/><span style=\"color: #C00000;\">./allinone_linux_amd64</span> -tv=true -aesKey=xxx -userid=xxx -token=xxxx</p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">修改一下命令第一段，</p><p style=\"line-height: 16px;\"><span style=\"color: #C00000;\"><strong style=\"text-wrap-mode: wrap;\">/storage/emulated/0/Download</strong></span><span style=\"color: #C00000;\"><strong style=\"text-wrap-mode: wrap;\">/allinone_linux_arm64</strong></span><strong style=\"text-wrap-mode: wrap;\">&nbsp;<span style=\"text-wrap-mode: wrap;\">-tv=true<span style=\"text-wrap-mode: wrap;\">&nbsp;-aesKey=xxx -userid=xxx -token=xxxx</span></span></strong></p><p style=\"line-height: 16px;\"><strong style=\"text-wrap-mode: wrap;\"><br/></strong></p><p style=\"line-height: 16px;\">安装天光云影后，长按屏幕-设置-权限，</p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412171535094867223.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\">把两个权限都点亮，</p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412171535487137441.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\">选择直播源，</p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412171745286966216.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\">自定义直播源，</p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412171746056402890.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\">添加其他直播源，</p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412171746277245215.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\">手机扫码，或用局域网电脑浏览器访问二维码下面的地址：</p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412171533214563201.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\">页面最底部，地址里填写前面修改好的命令，注意包含的自己的aesKey, userid,token !</p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><span style=\"text-wrap-mode: wrap; color: #C00000;\"><strong>/storage/emulated/0/Download</strong></span><span style=\"text-wrap-mode: wrap; color: #C00000;\"><strong>/allinone_linux_arm64</strong></span><strong style=\"text-wrap-mode: wrap;\">&nbsp;-tv=true&nbsp;-aesKey=xxx -userid=xxx -token=xxxx</strong></p><p style=\"line-height: 16px;\"><strong style=\"text-wrap-mode: wrap;\"><br/></strong></p><p style=\"line-height: 16px;\">点击推送</p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501031209521280437.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\">正常情况下回到主页即可观看直播。</p><p><br/></p><p>如节目分组太混乱，将下面内容复制到 <strong>配置页面/高级模式/直播源/自定义直播源/转换Js&nbsp;</strong>中，修改后请重新选中、清除缓存直播源</p><pre class=\"brush:java;toolbar:false\">function&nbsp;transformGroupNames(channelList,&nbsp;mapping)&nbsp;{\r\n&nbsp;&nbsp;return&nbsp;channelList.map(function&nbsp;(channel)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;newGroupName&nbsp;=&nbsp;mapping[channel.groupName]&nbsp;||&nbsp;channel.groupName;\r\n&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;Object.assign({},&nbsp;channel,&nbsp;{&nbsp;groupName:&nbsp;newGroupName&nbsp;});\r\n&nbsp;&nbsp;});\r\n}\r\n\r\nfunction&nbsp;sortChannelsByGroupName(channelList,&nbsp;sort)&nbsp;{\r\n&nbsp;&nbsp;return&nbsp;channelList\r\n&nbsp;&nbsp;&nbsp;&nbsp;.map(function&nbsp;(channel,&nbsp;index)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;{&nbsp;channel:&nbsp;channel,&nbsp;originalIndex:&nbsp;index&nbsp;};\r\n&nbsp;&nbsp;&nbsp;&nbsp;})\r\n&nbsp;&nbsp;&nbsp;&nbsp;.sort(function&nbsp;(a,&nbsp;b)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;indexA&nbsp;=&nbsp;sort.indexOf(a.channel.groupName);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;indexB&nbsp;=&nbsp;sort.indexOf(b.channel.groupName);\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;indexA&nbsp;=&nbsp;indexA&nbsp;===&nbsp;-1&nbsp;?&nbsp;sort.length&nbsp;:&nbsp;indexA;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;indexB&nbsp;=&nbsp;indexB&nbsp;===&nbsp;-1&nbsp;?&nbsp;sort.length&nbsp;:&nbsp;indexB;\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;indexA&nbsp;-&nbsp;indexB&nbsp;||&nbsp;a.originalIndex&nbsp;-&nbsp;b.originalIndex;\r\n&nbsp;&nbsp;&nbsp;&nbsp;})\r\n&nbsp;&nbsp;&nbsp;&nbsp;.map(function&nbsp;(item)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;item.channel;\r\n&nbsp;&nbsp;&nbsp;&nbsp;});\r\n}\r\n\r\nfunction&nbsp;transformChannelList(channelList,&nbsp;func)&nbsp;{\r\n&nbsp;&nbsp;return&nbsp;channelList.map(function&nbsp;(channel)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;transformedChannel&nbsp;=&nbsp;func(channel);\r\n&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;Object.assign({},&nbsp;channel,&nbsp;transformedChannel);\r\n&nbsp;&nbsp;});\r\n}\r\n\r\n/**\r\n&nbsp;*&nbsp;频道&nbsp;{\r\n&nbsp;*&nbsp;&nbsp;&nbsp;groupName:&nbsp;String,&nbsp;//&nbsp;分组名\r\n&nbsp;*&nbsp;&nbsp;&nbsp;name:&nbsp;String,&nbsp;//&nbsp;频道名\r\n&nbsp;*&nbsp;&nbsp;&nbsp;epgName:&nbsp;String,&nbsp;//&nbsp;节目单名\r\n&nbsp;*&nbsp;&nbsp;&nbsp;url:&nbsp;String,&nbsp;//&nbsp;播放链接\r\n&nbsp;*&nbsp;&nbsp;&nbsp;logo:&nbsp;String?,&nbsp;//&nbsp;频道图标\r\n&nbsp;*&nbsp;&nbsp;&nbsp;httpUserAgent:&nbsp;String?,&nbsp;//&nbsp;ua\r\n&nbsp;*&nbsp;}\r\n&nbsp;*&nbsp;@param&nbsp;channelList&nbsp;频道列表\r\n&nbsp;*&nbsp;@returns&nbsp;频道列表\r\n&nbsp;*/\r\nfunction&nbsp;main(channelList)&nbsp;{\r\n&nbsp;&nbsp;var&nbsp;groupNameMapping&nbsp;=&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;北京&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;安徽&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;甘肃&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;广东&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;贵州&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;海南&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;河北&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;河南&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;黑龙江&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;湖北&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;湖南&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;吉林&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;江苏&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;江西&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;辽宁&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;青海&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;山东&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;上海&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;四川&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;云南&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;浙江&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;重庆&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;香港&#39;:&nbsp;&#39;卫视&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;4K频道&#39;:&nbsp;&#39;4K&nbsp;8K&#39;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&#39;8K频道&#39;:&nbsp;&#39;4K&nbsp;8K&#39;,\r\n&nbsp;&nbsp;};\r\n&nbsp;&nbsp;var&nbsp;groupNameSort&nbsp;=&nbsp;[&#39;4K&nbsp;8K&#39;,&nbsp;&#39;央视&#39;,&nbsp;&#39;卫视&#39;,&nbsp;&#39;NEWTV&#39;,&nbsp;&#39;IHOT&#39;,&nbsp;&#39;其他&#39;];\r\n\r\n&nbsp;&nbsp;function&nbsp;transformChannel(channel)&nbsp;{\r\n&nbsp;&nbsp;}\r\n\r\n&nbsp;&nbsp;return&nbsp;sortChannelsByGroupName(transformGroupNames(transformChannelList(channelList,&nbsp;transformChannel),&nbsp;groupNameMapping),&nbsp;groupNameSort);\r\n}</pre><p><br/></p>', '1734420444', '0', '280', '', '', '1734420992', '1735877426');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('583', '2', '1', '', '0', '0', '', '0', '0', 'zblog增加备份数据库功能', '<p>替换文件：\\zb_system\\function\\c_system_admin_function.php</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191112283857825.rar\" title=\"c_system_admin_function.rar\"></a></p><!--autointro-->', '<p>替换文件：\\zb_system\\function\\c_system_admin_function.php</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191112283857825.rar\" title=\"c_system_admin_function.rar\">c_system_admin_function.rar</a></p><p>在同目录增加文件：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191112345148353.rar\" title=\"sql_backup.rar\">sql_backup.rar</a></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">* 文件解压后使用！</p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">在左侧菜单底部会多个入口，点击即可备份数据库到网站根目录\\SQL_backup中</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191112533466831.png\" alt=\"image.png\"/></p>', '1734517806', '0', '210', '', '', '1734517886', '1734577986');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('584', '2', '1', '', '0', '0', '', '0', '0', '群晖DSM7.x安装zblog', '<p><span style=\"background-color: #F79646; font-family: 微软雅黑, &quot;Microsoft YaHei&quot;; color: #FFFFFF;\">准备工作：</span><br/></p><p>系统：<strong>DSM7.1，或7.2</strong></p><p>套件：<strong>web station, MariaDB 10, php8.x</strong>, phpadmin(管理数据库的，非必须)</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191625436916512.png\" alt=\"image.png\"/></p><!--autointro-->', '<p><span style=\"background-color: #F79646; font-family: 微软雅黑, &quot;Microsoft YaHei&quot;; color: #FFFFFF;\">准备工作：</span><br/></p><p>系统：<strong>DSM7.1，或7.2</strong></p><p>套件：<strong>web station, MariaDB 10, php8.x</strong>, phpadmin(管理数据库的，非必须)</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191625436916512.png\" alt=\"image.png\"/></p><p>Zblog程序： <a href=\"https://www.zblogcn.com/zblogphp/\" target=\"_self\"><strong>下载地址</strong></a></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191609356855786.png\" alt=\"image.png\"/></p><p><br/></p><p>关于套件，建议安装套件<strong>wordpress</strong>, 会自动引导安装和设置所有需要的环境，当进行wordpress下载时取消下载，或者取消安装。或者安装后再把wordpress卸载掉。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191552089502973.png\" alt=\"image.png\"/></p><p>安装DB时，设置数据库密码，并牢记！</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191553166996411.png\" alt=\"image.png\"/></p><p>把zblog的程序文件解码到web目录中，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191600596573072.png\" alt=\"image.png\"/></p><p>打开web station套件，脚本语言设置-PHP, 选中PHP 8.0, 点编辑</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191614395784913.png\" alt=\"image.png\"/></p><p>扩展名，全选，保存<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191615349689280.png\" alt=\"image.png\"/></p><p><span style=\"color: #FFFFFF; text-wrap-mode: wrap; background-color: #F79646;\">安装工作：</span></p><p>网页服务-新增</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191559161634085.png\" alt=\"image.png\"/></p><p>选择本机脚本语言<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191559585875197.png\" alt=\"image.png\"/></p><p>设置网站信息<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191602161733904.png\" alt=\"image.png\"/></p><p>点新增</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191602519265535.png\" alt=\"image.png\"/></p><p><br/></p><p>确认</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191603062694277.png\" alt=\"image.png\"/></p><p>网络门户-新增<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191603244753635.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191603356014013.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191604368237306.png\" alt=\"image.png\"/></p><p>去file station中，在zblog目录上右击属性，修改权限，给http增加写入权限。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191605523854352.png\" alt=\"image.png\"/></p><p><br/></p><p>此时即可通过ip:端口访问zblog安装程序，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191610271004297.png\" alt=\"image.png\"/></p><p>正常情况下应该全部绿色<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191610475112963.png\" alt=\"image.png\"/></p><p>填写空白的即可，默认的就保持默认</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191612206728699.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191612414126165.png\" alt=\"image.png\"/></p><p>再次访问ip:端口，即可进入网站前台</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412191613195052734.png\" alt=\"image.png\"/></p>', '1734594382', '0', '199', '', '', '1734595585', '1734596746');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('592', '2', '1', '', '0', '0', '', '0', '0', '使用MT管理器实现安卓app共存', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>使用MT浏览apk的安装包</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501151128343241366.png\" alt=\"image.png\"/></p></li><li><p>点击功能，选择APK共存</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501151128533004657.png\" alt=\"image.png\"/></p></li></ol><!--autointro-->', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>使用MT浏览apk的安装包</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501151128343241366.png\" alt=\"image.png\"/></p></li><li><p>点击功能，选择APK共存</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501151128533004657.png\" alt=\"image.png\"/></p></li><li><p>修改一下包名称</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501151129189860135.png\" alt=\"image.png\"/></p></li><li><p>点确定，自动签名完成后会在原apk同目录生成一个后缀clone的文件，即共存版</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501151130201630872.png\" alt=\"image.png\"/></p></li><li><p>安装克隆版即可同时拥有两个app<br/></p></li></ol>', '1736911652', '0', '233', '', '', '1736911846', '1736911846');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('585', '2', '1', '', '0', '0', '', '0', '0', '使用ssh快速安装/重装 alist-tvbox 容器', '<p>下载脚本：</p><p>集成小雅版：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501221956449995930.rar\" title=\"tvbox_with_xiaoya.rar\"></a></p><!--autointro-->', '<p>下载脚本：</p><p>集成小雅版：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501221956449995930.rar\" title=\"tvbox_with_xiaoya.rar\">tvbox_with_xiaoya.rar</a></p><p><br/></p><p>纯净版：<br/></p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501221956173565133.rar\" title=\"tvbox_no_xiaoya.rar\">tvbox_no_xiaoya.rar</a></p><p><br/></p><p><br/></p><p>解压到准备安装容器的目录里，</p><p>ssh执行<strong>bash tvbox*.sh</strong>即可。</p><p>如需要修改默认端口，编辑文件修改Port1即可。</p><p><span style=\"text-wrap-mode: wrap;\"><br/></span></p><p><span style=\"text-wrap-mode: wrap;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501221957324017332.png\" alt=\"image.png\"/></span></p><p><span style=\"text-wrap-mode: wrap;\"><br/></span></p><p>其实这两个是两个不同的容器，各装各的就行，但是默认端口冲突，只能装一个。</p><p>小雅加载目录失败的话，在高级设置里修改一下认证服务器，选择小飞机那个，然后重启一下容器。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412271158509563644.png\" alt=\"image.png\"/></p><p><br/></p><p>关于更新PG，ZX</p><p>程序默认从这个容器的开发者服务器下载pg包更新，但偶尔会遇到他的服务器宕机，可使用以下脚本配合群晖计划任务定时自动更新。</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501222000261820867.rar\" title=\"downloadPg.rar\">downloadPg.rar</a></p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501222031539492464.rar\" title=\"downloadZx.rar\">downloadZx.rar</a></p><br/><p>脚本解压后，放在安装根目录，即data外面</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501222001534112610.png\" alt=\"image.png\"/></p>', '1735271682', '0', '300', '', '', '1735271934', '1737549118');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('586', '2', '1', '', '0', '0', '', '0', '0', '快速安装小雅alist容器', '<p>下载脚本：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412271201436263489.rar\" title=\"xiaoya-alist.rar\"></a></p><!--autointro-->', '<p>下载脚本：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412271201436263489.rar\" title=\"xiaoya-alist.rar\">xiaoya-alist.rar</a></p><p><br/></p><p>解压到准备安装小雅的目录中，</p><p>ssh执行：</p><pre class=\"brush:delphi;toolbar:false\">bash&nbsp;*.sh</pre><p><br/></p><p>漫长启动成功后，ip:5678 访问小雅。</p><p><br/></p><p>如报容器下载失败，修改112行后面的4为<span style=\"text-wrap-mode: wrap;\">【1-15】</span>其他数值试试，选择镜像源的。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412271203171931477.png\" alt=\"image.png\"/></p>', '1735272011', '0', '186', '', '', '1735272246', '1735272246');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('587', '2', '1', '', '0', '0', '', '0', '0', '在github上fork一个项目，在action里有工作流文件，却无法run', '<p>如果在github上fork一个项目，在action里有工作流文件，却没有Run Workflow按钮，</p><p>提示This workflo has not runs yet.</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412271820464468815.png\" alt=\"image.png\"/></p><p>只需要修改工作流yml文件, 在on下面增加一行：</p><p>workflow_dispatch:</p><!--autointro-->', '<p>如果在github上fork一个项目，在action里有工作流文件，却没有Run Workflow按钮，</p><p>提示This workflo has not runs yet.</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412271820464468815.png\" alt=\"image.png\"/></p><p>只需要修改工作流yml文件, 在on下面增加一行：</p><p>workflow_dispatch:</p><p>* 注意对齐！</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412271824018677379.png\" alt=\"image.png\"/></p><p>保存后，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412271821494491832.png\" alt=\"image.png\"/></p><p><span style=\"text-wrap-mode: wrap;\">重新选择此工作流，即可看到Run workflow按钮。</span></p><p><span style=\"text-wrap-mode: wrap;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412271823295716856.png\" alt=\"image.png\"/></span></p>', '1735294630', '0', '191', '', '', '1735295058', '1735295058');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('588', '2', '1', '', '0', '0', '', '0', '0', '天光云影APP修改记录', '<p><strong>默认打开“打开直接进入直播”</strong></p><p>关键词：APP_STARTUP_SCREEN</p><p>默认值：<span style=\"text-wrap-mode: wrap;\">Dashboard</span></p><p>改为：<span style=\"text-wrap-mode: wrap;\">Live</span></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412300944155257826.png\" alt=\"image.png\"/></p><!--autointro-->', '<p><strong>默认打开“打开直接进入直播”</strong></p><p>关键词：APP_STARTUP_SCREEN</p><p>默认值：<span style=\"text-wrap-mode: wrap;\">Dashboard</span></p><p>改为：<span style=\"text-wrap-mode: wrap;\">Live</span></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412300944155257826.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412300942275305646.png\" alt=\"image.png\"/></p><p><br/></p><p><strong>默认设置直播源不缓存：</strong></p><p>关键词：IPTV_SOURCE_CACHE_TIME</p><p>默认：0x5265c00</p><p>改为：0x0</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412300944525168006.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412300945098992700.png\" alt=\"image.png\"/></p><p><strong>默认经典选台模式：</strong></p><p>关键词：UI_USE_CLASSIC_PANEL_SCREEN</p><p>默认值：v1</p><p>改为：v3</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412300948136591979.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412300948376738657.png\" alt=\"image.png\"/></p><p><strong>强制更新提示：</strong></p><p>关键词：UPDATE_FORCE_REMIND</p><p>默认值：v1</p><p>修改为：v3</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412301453573891435.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412301453325330012.png\" alt=\"image.png\"/></p><p><br/></p><p><strong>把直播源显示改为固定值：</strong></p><p>关键词：个分组</p><p>默认值：<span style=\"text-wrap-mode: nowrap;\">invoke-static/range {v36 .. v60}, LU2/M0;-&gt;b(Ljava/lang/String;LZ/l;JJLK0/w;LK0/C;LK0/p;JLQ0/g;LQ0/f;JIZIILX3/c;LG0/D;LN/p;III)V</span></p><p><span style=\"text-wrap-mode: nowrap;\">修改：再此前面加一行const-string v36, &quot;刷新查看订阅详情&quot;</span></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412300950149188701.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412300951158562527.png\" alt=\"image.png\"/></p><p>修改更新app地址：</p><p>关键词：tag_name</p><p>原值：github.com</p><p>&nbsp;&nbsp;&nbsp;&nbsp;gitee.com</p><p>&nbsp;&nbsp;&nbsp;&nbsp;raw.githubusercontent.com</p><p>修改为：http</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412301142369349561.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412301146482443443.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412301146579111208.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412301147075423618.png\" alt=\"image.png\"/></p><p>关键词：mytv-android-update</p><p>原值：<a href=\"https://ghp.ci/https://raw.githubusercontent.com/yaoxieyoulei/mytv-android-update/main/tv-stable.json\" _src=\"https://ghp.ci/https://raw.githubusercontent.com/yaoxieyoulei/mytv-android-update/main/tv-stable.json\">https://ghp.ci/https://raw.githubusercontent.com/yaoxieyoulei/mytv-android-update/main/tv-stable.json</a>&nbsp;等</p><p>改为：自定义的json地址</p><p>json内容如下：</p><pre class=\"brush:java;toolbar:false\">{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;tag_name&quot;:&nbsp;&quot;v3.3.7&quot;,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;assets&quot;:&nbsp;[\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&quot;browser_download_url&quot;:&nbsp;&quot;https://github.com/yogiczy/mytv-android-update/releases/download/tv3.3.7/mytv-android-tv-3.3.7-all-sdk21-original.apk&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;],\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;body&quot;:&nbsp;&quot;修复切换播放器内核后按键操作失效\\r\\n解码失败后将自动切换软解\\r\\n传统选台界面列表循环（分组列表、频道列表）\\r\\n优化aio启动，仅当aio路径不为空时启动\\r\\n新增设置项（设置/播放器/跳过多帧渲染）\\r\\n\\r\\n换台时花屏等画面问题，打开&nbsp;设置/播放器/停止上一媒体项\\r\\n换台短暂黑屏，切换播放器渲染方式，或关闭停止上一媒体项&quot;\r\n}</pre><p><br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2024/12/202412301148048056331.png\" alt=\"image.png\"/></p><p><br/></p>', '1735522657', '0', '216', '', '', '1735523494', '1735541644');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('589', '2', '1', '', '0', '0', '', '0', '0', '复制一个仓库的分支到自己仓库中', '<p>登陆GitHub，点右上角头像，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501021125518465526.png\" alt=\"image.png\"/></p><p>新建一个仓库<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501021126093308858.png\" alt=\"image.png\"/></p><!--autointro-->', '<p>登陆GitHub，点右上角头像，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501021125518465526.png\" alt=\"image.png\"/></p><p>新建一个仓库<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501021126093308858.png\" alt=\"image.png\"/></p><p>在windows上新建一个文件夹，在文件夹处打开git</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501021128057770758.png\" alt=\"image.png\"/></p><p>先把新建仓库拉到本地：</p><pre class=\"brush:bash;toolbar:false\">git&nbsp;clone&nbsp;https://github.com/Brian099/new</pre><p>切换到git目录</p><pre class=\"brush:bash;toolbar:false\">cd&nbsp;new</pre><p>添加要克隆的仓库作为远程仓库,【例如 <a href=\"https://github.com/brian099/mytv-android.git\" _src=\"https://github.com/brian099/mytv-android.git\">https://github.com/brian099/mytv-android.git</a>&nbsp; 这个项目中 deature-ui 这个分支】</p><pre class=\"brush:bash;toolbar:false\">git&nbsp;remote&nbsp;add&nbsp;mytv&nbsp;https://github.com/Brian099/mytv-android.git</pre><p>&nbsp;获取 mytv-android 中的 feature-ui 分支</p><pre class=\"brush:bash;toolbar:false\">git&nbsp;fetch&nbsp;mytv</pre><p>然后，切换到 feature-ui 分支：</p><pre class=\"brush:bash;toolbar:false\">git&nbsp;checkout&nbsp;-b&nbsp;feature-ui&nbsp;mytv/feature-ui</pre><p>将 feature-ui 分支推送到 yunying 仓库</p><pre class=\"brush:bash;toolbar:false\">git&nbsp;push&nbsp;-u&nbsp;origin&nbsp;feature-ui</pre><h4><br/></h4><h4>设置 <code>feature-ui</code> 为默认分支（可选）</h4><p>如果你希望将 <code>feature-ui</code> 设置为 <code>yunying</code> 仓库的默认分支，可以在 GitHub 网站上进行设置：</p><ol class=\" list-paddingleft-2\"><li><p>进入 <a rel=\"noopener\" target=\"_new\" href=\"https://github.com/Brian099/yunying\">yunying 仓库</a>。</p></li><li><p>点击 <strong>Settings</strong>。</p></li><li><p>选择分支</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501021143196133969.png\" alt=\"image.png\"/><br/></p><p><br/></p></li><li><p>在 <strong>Default branch</strong> 下拉框中，将默认分支设置为 <code>feature-ui</code>。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501021144109482503.png\" alt=\"image.png\"/></p></li><li><p>回到code,</p></li><li><p>点击</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501021144314783218.png\" alt=\"image.png\"/></p></li><li><p>删除原来的main</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501021145026354071.png\" alt=\"image.png\"/></p></li><li><p>重命名分支为mian</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501021145257397849.png\" alt=\"image.png\"/><br/></p></li></ol><p><br/></p>', '1735788310', '0', '226', '', '', '1735789080', '1735790038');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('590', '2', '1', '', '0', '0', '', '0', '0', '获取访问php文件时的客户端信息及获取附带参数', '<p>文件：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501031613557346553.rar\" title=\"getdata.rar\"></a></p><!--autointro-->', '<p>文件：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501031613557346553.rar\" title=\"getdata.rar\">getdata.rar</a></p><p>解压文件后，放在php可运行环境中，当访问此文件时，会记录访问信息，如下：<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501031615487669527.png\" alt=\"image.png\"/></p><p>代码内容如下：</p><pre class=\"brush:php;toolbar:false\">&lt;?php\r\n//&nbsp;设置响应头，确保输出友好显示\r\nheader(&#39;Content-Type:&nbsp;text/plain;&nbsp;charset=utf-8&#39;);\r\n\r\n//&nbsp;定义日志文件路径\r\n$logFile&nbsp;=&nbsp;&#39;request_log.txt&#39;;\r\n\r\n//&nbsp;获取请求的详细信息\r\n$requestInfo&nbsp;=&nbsp;&quot;===&nbsp;Client&nbsp;Information&nbsp;===\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;IP&nbsp;Address:&nbsp;&quot;&nbsp;.&nbsp;$_SERVER[&#39;REMOTE_ADDR&#39;]&nbsp;.&nbsp;&quot;\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;Port:&nbsp;&quot;&nbsp;.&nbsp;$_SERVER[&#39;REMOTE_PORT&#39;]&nbsp;.&nbsp;&quot;\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;User&nbsp;Agent:&nbsp;&quot;&nbsp;.&nbsp;($_SERVER[&#39;HTTP_USER_AGENT&#39;]&nbsp;??&nbsp;&#39;N/A&#39;)&nbsp;.&nbsp;&quot;\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;\\n===&nbsp;Request&nbsp;Information&nbsp;===\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;Request&nbsp;Method:&nbsp;&quot;&nbsp;.&nbsp;$_SERVER[&#39;REQUEST_METHOD&#39;]&nbsp;.&nbsp;&quot;\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;Request&nbsp;URI:&nbsp;&quot;&nbsp;.&nbsp;$_SERVER[&#39;REQUEST_URI&#39;]&nbsp;.&nbsp;&quot;\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;Query&nbsp;String:&nbsp;&quot;&nbsp;.&nbsp;($_SERVER[&#39;QUERY_STRING&#39;]&nbsp;??&nbsp;&#39;N/A&#39;)&nbsp;.&nbsp;&quot;\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;\\n===&nbsp;Headers&nbsp;===\\n&quot;;\r\n\r\nforeach&nbsp;(getallheaders()&nbsp;as&nbsp;$name&nbsp;=&gt;&nbsp;$value)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;$requestInfo&nbsp;.=&nbsp;&quot;$name:&nbsp;$value\\n&quot;;\r\n}\r\n\r\n$requestInfo&nbsp;.=&nbsp;&quot;\\n===&nbsp;Server&nbsp;Information&nbsp;===\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;Server&nbsp;Name:&nbsp;&quot;&nbsp;.&nbsp;$_SERVER[&#39;SERVER_NAME&#39;]&nbsp;.&nbsp;&quot;\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;Server&nbsp;Software:&nbsp;&quot;&nbsp;.&nbsp;$_SERVER[&#39;SERVER_SOFTWARE&#39;]&nbsp;.&nbsp;&quot;\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;Server&nbsp;Protocol:&nbsp;&quot;&nbsp;.&nbsp;$_SERVER[&#39;SERVER_PROTOCOL&#39;]&nbsp;.&nbsp;&quot;\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;Server&nbsp;Port:&nbsp;&quot;&nbsp;.&nbsp;$_SERVER[&#39;SERVER_PORT&#39;]&nbsp;.&nbsp;&quot;\\n&quot;;\r\n$requestInfo&nbsp;.=&nbsp;&quot;Document&nbsp;Root:&nbsp;&quot;&nbsp;.&nbsp;$_SERVER[&#39;DOCUMENT_ROOT&#39;]&nbsp;.&nbsp;&quot;\\n&quot;;\r\n\r\n$requestInfo&nbsp;.=&nbsp;&quot;\\n===&nbsp;GET&nbsp;Parameters&nbsp;===\\n&quot;;\r\nif&nbsp;(!empty($_GET))&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;foreach&nbsp;($_GET&nbsp;as&nbsp;$key&nbsp;=&gt;&nbsp;$value)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;$requestInfo&nbsp;.=&nbsp;&quot;$key:&nbsp;$value\\n&quot;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n}&nbsp;else&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;$requestInfo&nbsp;.=&nbsp;&quot;No&nbsp;GET&nbsp;parameters.\\n&quot;;\r\n}\r\n\r\n$requestInfo&nbsp;.=&nbsp;&quot;\\n===&nbsp;POST&nbsp;Parameters&nbsp;===\\n&quot;;\r\nif&nbsp;(!empty($_POST))&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;foreach&nbsp;($_POST&nbsp;as&nbsp;$key&nbsp;=&gt;&nbsp;$value)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;$requestInfo&nbsp;.=&nbsp;&quot;$key:&nbsp;$value\\n&quot;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n}&nbsp;else&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;$requestInfo&nbsp;.=&nbsp;&quot;No&nbsp;POST&nbsp;parameters.\\n&quot;;\r\n}\r\n\r\n$requestInfo&nbsp;.=&nbsp;&quot;\\n===&nbsp;Uploaded&nbsp;Files&nbsp;===\\n&quot;;\r\nif&nbsp;(!empty($_FILES))&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;foreach&nbsp;($_FILES&nbsp;as&nbsp;$file&nbsp;=&gt;&nbsp;$details)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;$requestInfo&nbsp;.=&nbsp;&quot;File:&nbsp;$file\\n&quot;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;foreach&nbsp;($details&nbsp;as&nbsp;$key&nbsp;=&gt;&nbsp;$value)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;$requestInfo&nbsp;.=&nbsp;&quot;&nbsp;&nbsp;$key:&nbsp;$value\\n&quot;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n}&nbsp;else&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;$requestInfo&nbsp;.=&nbsp;&quot;No&nbsp;files&nbsp;uploaded.\\n&quot;;\r\n}\r\n\r\n//&nbsp;将请求信息追加到日志文件\r\nfile_put_contents($logFile,&nbsp;$requestInfo&nbsp;.&nbsp;&quot;\\n&quot;,&nbsp;FILE_APPEND);\r\n\r\n//&nbsp;输出请求信息到浏览器\r\necho&nbsp;$requestInfo;\r\n?&gt;</pre><p><br/></p>', '1735891959', '0', '33454', '', '', '1735892169', '1735892169');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('591', '2', '1', '', '0', '0', '', '0', '0', '安装git服务器Gitea，配合UGit跟踪管理文件变动【docker】', '<p>Gitea docker：<a href=\"https://hub.docker.com/r/gitea/gitea\">gitea/gitea - Docker Image | Docker Hub</a></p><p>官方文档：<a href=\"https://docs.gitea.com/zh-cn/installation/install-with-docker-rootless\">使用 Docker 安装 (rootless) | Gitea Documentation</a></p><!--autointro-->', '<p>Gitea docker：<a href=\"https://hub.docker.com/r/gitea/gitea\">gitea/gitea - Docker Image | Docker Hub</a></p><p>官方文档：<a href=\"https://docs.gitea.com/zh-cn/installation/install-with-docker-rootless\">使用 Docker 安装 (rootless) | Gitea Documentation</a></p><p>UGit:<a href=\"https://ugit.qq.com/zh/\">UGit - 让每个人都可以轻松使用Git</a></p><p>UGit使用手册：<a href=\"https://docs.qq.com/doc/DTEpoYWVwV1dhV0Rz\">腾讯UGit-用户手册</a></p><p><br/></p><p>docker安装实录：</p><ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>拉取镜像</p><p><span style=\"color: #4F81BD;\">docker pull gitea/gitea</span></p><p><span style=\"text-wrap-mode: wrap;\">如国内环境，建议使用mypull辅助拉取，参考：<a href=\"{#ZC_BLOG_HOST#}?id=566\">群晖docker pull辅助工具 - 有搞头笔记</a></span><br/></p></li><li><p>群晖上创建一个目录用于存放git客户端上传的文件等，并修改属性为everyone都有独写权限</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501081206506883928.png\" alt=\"image.png\"/></p></li><li><p>执行docker安装：</p><p>* 默认映射管理端口到9000了<br/></p><p>* 注意修改路径为前面创建的路径</p><p><span style=\"color: #4F81BD;\">docker run -it --name=gitea -p 9020:22 -p 9000:3000 -v <strong>/volume2/gitea</strong>:/data gitea/gitea:latest</span><br/></p><p><br/></p></li><li><p>使用ip:9000 访问前台执行安装</p><p>建议拉到页面底部，直接点下一步</p></li><li><p>再次访问ip:9000, 注册第一个账号，第一个账号将成为管理员账号，请牢记</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501081211145896680.png\" alt=\"image.png\"/><br/></p></li><li><p>退出账号，创建个人账号。</p></li><li><p>创建一个仓库</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501081211425528663.png\" alt=\"image.png\"/></p></li><li><p>打开仓库，复制仓库地址</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501081212128367044.png\" alt=\"image.png\"/></p></li><li><p>使用UGit拉取仓库</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501081213429165546.png\" alt=\"image.png\"/></p></li><li><p>根据提示输入该仓库所属的账户，密码</p></li><li><p>后续在UGit更新文件，或本地更新文件后，在UGit进行提交，方便文档和工作管理，记录。<br/></p></li></ol>', '1736308891', '0', '245', '', '', '1736309696', '1736309719');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('593', '2', '1', '', '0', '0', '', '0', '0', '使用肥羊allinone容器获取直播源', '<p>容器地址：</p><p><a href=\"https://hub.docker.com/r/youshandefeiyang/allinone\">youshandefeiyang/allinone - Docker Image | Docker Hub</a></p><p><br/></p><p>官方使用说明：</p><p><a href=\"https://pan.v1.mk/%E6%AF%8F%E6%9C%9F%E8%A7%86%E9%A2%91%E4%B8%AD%E7%94%A8%E5%88%B0%E7%9A%84%E6%96%87%E4%BB%B6%E5%88%86%E4%BA%AB/allinone%E4%BA%8C%E8%BF%9B%E5%88%B6%E6%96%87%E4%BB%B6/%E4%BD%BF%E7%94%A8%E8%AF%B4%E6%98%8E.md\"></a></p><!--autointro-->', '<p>容器地址：</p><p><a href=\"https://hub.docker.com/r/youshandefeiyang/allinone\">youshandefeiyang/allinone - Docker Image | Docker Hub</a></p><p><br/></p><p>官方使用说明：</p><p><a href=\"https://pan.v1.mk/%E6%AF%8F%E6%9C%9F%E8%A7%86%E9%A2%91%E4%B8%AD%E7%94%A8%E5%88%B0%E7%9A%84%E6%96%87%E4%BB%B6%E5%88%86%E4%BA%AB/allinone%E4%BA%8C%E8%BF%9B%E5%88%B6%E6%96%87%E4%BB%B6/%E4%BD%BF%E7%94%A8%E8%AF%B4%E6%98%8E.md\">使用说明.md | 影视/教程汇总</a></p><p><br/></p><p>可以获取央视，卫视，虎牙，歪歪，等直播内容，在DIYP类APP上播放。</p><p><br/></p><p>需要配合网址 【<a href=\"https://imgtool.v1.mk/allinone.html\">ALLINONE部署指令生成器</a>&nbsp;】生成专属aes，并在tg机器人 【<a href=\"https://t.me/newallinone_bot\">Telegram: Contact @newallinone_bot</a>】 上获取专属id和token, 回填到生成器网页中，获取安装指令，类似：</p><pre class=\"brush:bash;toolbar:false\">docker&nbsp;run&nbsp;-d&nbsp;--restart&nbsp;always&nbsp;--privileged=true&nbsp;-p&nbsp;35455:35455&nbsp;--name&nbsp;allinone&nbsp;youshandefeiyang/allinone&nbsp;-tv=true&nbsp;-aesKey=4d3u22xtm9k1hje8wet67tvfngew4kyu&nbsp;-userid=xxxxxxxxxxx&nbsp;-token=xxxxxxxxxxxxxxxxxxxxxxxxxxxxxx</pre><p><br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501171347435068983.png\" alt=\"image.png\"/></p><p>注：直接运行和PM2守护方式都是使用裸二进制文件，已启用，目前必须使用docker创建。</p><p><br/></p><p>命令中<span style=\"text-wrap-mode: wrap;\">&nbsp;-tv=true 值可选false，意思是TV转发开启/关闭，</span></p><p><span style=\"text-wrap-mode: wrap;\">如true，服务器将提供上传给客户端观看直播，有央视卫视等，对应的是tv.m3u,</span></p><p>如false，将无法获取tv.m3u，也就没有直播服务，可保证只消耗服务器很少的上传。</p><p><br/></p><p>由于国内环境问题，直接运行docker run命令可能因为拉取不到镜像而安装失败，可自定添加代理，或借助mypull工具拉取并安装镜像：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501171352446081416.rar\" title=\"mypull.rar\">mypull.rar</a></p><p><br/></p><p>解压后上传到服务器，</p><p>cd 到mypull文件位置，执行：</p><pre class=\"brush:bash;toolbar:false\">./mypull&nbsp;youshandefeiyang/allinone&nbsp;\r\ndocker&nbsp;run&nbsp;-d&nbsp;--restart&nbsp;always&nbsp;--privileged=true&nbsp;-p&nbsp;35455:35455&nbsp;--name&nbsp;allinone&nbsp;youshandefeiyang/allinone&nbsp;-tv=true&nbsp;-aesKey=4d3u22xtm9k1hje8wet67tvfngew4kyu&nbsp;-userid=xxxxxxxxxxx&nbsp;-token=xxxxxxxxxxxxxxxxxxxxxxxxxxxxxx</pre><p><br/></p>', '1737092545', '0', '338', '', '', '1737093241', '1739419767');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('594', '2', '1', '', '0', '0', '', '0', '0', '超级复制粘贴工具 ', '<p>本文搬自：<a href=\"https://zhuanlan.zhihu.com/p/368345551\">打工人必备神器：一款仅5MB的小工具，让复制粘贴快100倍！ - 知乎</a></p><p data-pid=\"v8er60Yo\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"></p><!--autointro-->', '<p>本文搬自：<a href=\"https://zhuanlan.zhihu.com/p/368345551\">打工人必备神器：一款仅5MB的小工具，让复制粘贴快100倍！ - 知乎</a></p><p data-pid=\"v8er60Yo\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">本文将通过三部分内容，来向你安利这款神器：</p><ol style=\"list-style-type: none;\" class=\" list-paddingleft-2\"><li><p>Ditto简介</p></li><li><p>Ditto使用流程</p></li><li><p>Ditto使用技巧</p></li></ol><h2 style=\"font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 1.2em; line-height: 1.5; font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin: calc(2.33333em) 0px calc(1.16667em); clear: left; color: rgb(25, 27, 31); text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">1. Ditto简介</h2><p data-pid=\"ckyXBe5Z\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><span style=\"font-weight: 600;\">Ditto是Windows操作系统中的<a class=\"RichContent-EntityWord css-b7erz1\" data-za-not-track-link=\"true\" data-paste-text=\"true\" href=\"https://zhida.zhihu.com/search?content_id=169984063&content_type=Article&match_order=1&q=%E5%89%AA%E8%B4%B4%E6%9D%BF%E7%AE%A1%E7%90%86%E7%A5%9E%E5%99%A8&zhida_source=entity\" target=\"_blank\" style=\"text-decoration-line: none; color: rgb(9, 64, 142); cursor: pointer;\">剪贴板管理神器<svg width=\"10px\" height=\"10px\" viewbox=\"0 0 16 16\" class=\"ZDI ZDI--FourPointedStar16 css-1dvsrp\" fill=\"currentColor\"><path d=\"m5.068 9.267-3.08-.77a.512.512 0 0 1 0-.994l3.08-.77a2.289 2.289 0 0 0 1.665-1.665l.77-3.08a.512.512 0 0 1 .994 0l.77 3.08c.205.82.845 1.46 1.665 1.665l3.08.77a.512.512 0 0 1 0 .994l-3.08.77a2.29 2.29 0 0 0-1.665 1.665l-.77 3.08a.512.512 0 0 1-.994 0l-.77-3.08a2.289 2.289 0 0 0-1.665-1.665Z\"></path></svg></a></span>，其安装文件仅有5MB，且使用过程中，<span style=\"font-weight: 600;\">资源占用极小。</span></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135179772497.jpg\" data-caption=\"\" data-size=\"normal\" data-rawwidth=\"824\" data-rawheight=\"785\" data-original-token=\"v2-e2199c635f62ad8068bceea73355a5fc\" width=\"824\" data-original=\"https://picx.zhimg.com/v2-5d5abd24f2819420c013a4dbe26a3f43_r.jpg\" style=\"display: block; max-width: 100%; height: auto; cursor: zoom-in; width: 690px;\" data-catchresult=\"img_catchSuccess\"/></figure><p><br/></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p data-pid=\"NrcrFEGM\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">更重要的是，这样的一款神器，<span style=\"font-weight: 600;\">它居然是免费的！</span></p><p data-pid=\"_KpXswRD\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">Ditto最核心的功能在于：<span style=\"font-weight: 600;\">将原本只能保存一次记录的剪贴板，扩展到了数百条甚至上千条记录，并且，提供了诸多非常实用的功能。</span></p><p data-pid=\"d4oEhaE2\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">有了Ditto，你可以像这样，快速重复使用你的剪贴板——</p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><div class=\"GifPlayer css-1isopsn\" data-size=\"normal\" data-za-detail-view-path-module=\"GifItem\" style=\"cursor: pointer; max-width: 100%; overflow: hidden; position: relative; text-align: center; width: fit-content;\"><img width=\"1079\" role=\"presentation\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135176229692.jpg\" data-thumbnail=\"https://pica.zhimg.com/v2-0a2e55df8ba7e079d326f749c031ad7c_b.jpg\" data-size=\"normal\" alt=\"动图封面\" style=\"max-width: 100%; vertical-align: top; display: block;\" data-catchresult=\"img_catchSuccess\"/><div class=\"GifPlayer-icon css-d39tw7\" style=\"left: 345px; opacity: 1; pointer-events: none; position: absolute; top: 271.391px; transform: scale(1) translate(-50%, -50%); transform-origin: left top; transition: transform 0.3s ease-out, opacity;\"><svg width=\"50\" height=\"50\" viewbox=\"0 0 60 60\" xmlns=\"http://www.w3.org/2000/svg\"><g stroke=\"none\" stroke-width=\"1\" fill=\"none\" fill-rule=\"evenodd\"><ellipse fill=\"#000\" opacity=\"0.45\" cx=\"30\" cy=\"30\" rx=\"30\" ry=\"30\"></ellipse><ellipse stroke=\"#FFF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" opacity=\"0.5\" cx=\"30\" cy=\"30\" rx=\"26\" ry=\"26\"></ellipse></g><svg x=\"16\" y=\"18.5\"><g fill=\"#fff\"><path x=\"100\" y=\"100\" d=\"M12.8422852,12.9814453 L12.8422852,11.3994141 L7.63916016,11.3994141 L7.63916016,13.0517578 L10.9086914,13.0517578 L10.9086914,13.3242188 C10.8911133,15.2050781 9.46728516,16.4707031 7.39306641,16.4707031 C5.01123047,16.4707031 3.51708984,14.625 3.51708984,11.6367188 C3.51708984,8.70117188 5.00244141,6.84667969 7.34912109,6.84667969 C9.08056641,6.84667969 10.284668,7.68164062 10.7768555,9.2109375 L12.7543945,9.2109375 C12.3237305,6.64453125 10.2319336,5.00976562 7.34912109,5.00976562 C3.79833984,5.00976562 1.50439453,7.61132812 1.50439453,11.6542969 C1.50439453,15.75 3.77197266,18.3076172 7.36669922,18.3076172 C10.6889648,18.3076172 12.8422852,16.2246094 12.8422852,12.9814453 Z M17.5180664,18 L17.5180664,5.31738281 L15.5493164,5.31738281 L15.5493164,18 L17.5180664,18 Z M22.659668,18 L22.659668,12.7441406 L28.1088867,12.7441406 L28.1088867,11.0039062 L22.659668,11.0039062 L22.659668,7.11035156 L28.6098633,7.11035156 L28.6098633,5.31738281 L20.690918,5.31738281 L20.690918,18 L22.659668,18 Z\"></path></g></svg></svg></div></div></figure><p><br/></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><h2 style=\"font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 1.2em; line-height: 1.5; font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin: calc(2.33333em) 0px calc(1.16667em); clear: left; color: rgb(25, 27, 31); text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">2. Ditto使用流程<br/></h2><p data-pid=\"oI4hyFDi\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">作为一名新人，应该如何使用Ditto呢？你可以参照这份流程清单。</p><h3 style=\"font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 1.1em; line-height: 1.5; font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin: calc(1.90909em) 0px calc(1.27273em); clear: left; color: rgb(25, 27, 31); text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">Step 1. 安装Ditto</h3><p data-pid=\"QZBROgt1\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">因为Ditto官网在国外的关系，所以下载速度较慢，我把安装文件打包放到了某网盘，<span style=\"font-weight: 600;\">可以这样获取（懂的都懂）：</span></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135189151162.jpg\" data-caption=\"\" data-size=\"normal\" data-rawwidth=\"1080\" data-rawheight=\"1278\" data-original-token=\"v2-e074f21c9bbfbb69ac33abfcab773dff\" width=\"1080\" data-original=\"https://pic3.zhimg.com/v2-0f76df186eddaebbe745c86f02ecf998_r.jpg\" style=\"display: block; max-width: 100%; height: auto; cursor: zoom-in; width: 690px;\" data-catchresult=\"img_catchSuccess\"/></figure><p><br/></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p data-pid=\"YRuu-f3Q\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">安装文件有普通的安装版本，和解压即可使用的便携版本。</p><p data-pid=\"fFuWpLrd\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><span style=\"font-weight: 600;\">安装时，请注意选择32位或64位版本。</span></p><h3 style=\"font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 1.1em; line-height: 1.5; font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin: calc(1.90909em) 0px calc(1.27273em); clear: left; color: rgb(25, 27, 31); text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">Step 2. 简单的设置</h3><p data-pid=\"i31Iqv3h\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">安装好Ditto之后，我们需要对它进行一些简单的设置。</p><p data-pid=\"sU5Jy0OK\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">启动Ditto，你可以在任务栏右下角中找到它，对，就是那个长得像引号（”）的图标，右键点击选择“选项”，打开Ditto的设置菜单。</p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135182195929.jpg\" data-caption=\"\" data-size=\"normal\" data-rawwidth=\"415\" data-rawheight=\"654\" data-original-token=\"v2-8520b5e95099d29c878a7ee97c10e967\" width=\"415\" style=\"display: block; max-width: 100%; height: auto; width: 690px;\" data-catchresult=\"img_catchSuccess\"/></figure><p><br/></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p data-pid=\"1elCjihc\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">下图中，标记了建议设置的选项：</p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135183882184.jpg\" data-caption=\"\" data-size=\"normal\" data-rawwidth=\"896\" data-rawheight=\"949\" data-original-token=\"v2-695f6f054d2e011d01dbfa76c856c612\" width=\"896\" data-original=\"https://picx.zhimg.com/v2-e30872003a4b5ce555a2f93e710dd9a5_r.jpg\" style=\"display: block; max-width: 100%; height: auto; cursor: zoom-in; width: 690px;\" data-catchresult=\"img_catchSuccess\"/></figure><p><br/></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p data-pid=\"3zXwtaJg\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">解释一下这些选项：</p><ol style=\"list-style-type: none;\" class=\" list-paddingleft-2\"><li><p>系统启动时运行。建议开启，这样只要开机，Ditto就会运行。</p></li><li><p>保存复制项目的最大数量。一看就能明白它的意思，我设置的是保存最近1000条复制记录。</p></li><li><p>语言。可以在这里将Ditto的显示语言切换为中文。</p></li><li><p>显示字体。可以在这里设置Ditto中展示文本的字体。</p></li></ol><p data-pid=\"QTsqh55L\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">接下来，切换到“键盘快捷键”选项卡，设置一下打开Ditto剪贴板的快捷键——</p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135183771010.jpg\" data-caption=\"\" data-size=\"normal\" data-rawwidth=\"896\" data-rawheight=\"949\" data-original-token=\"v2-44a6058df01a903512705c6917b77a2f\" width=\"896\" data-original=\"https://pic3.zhimg.com/v2-0e1355ea83b9e6cb7151609da9badcde_r.jpg\" style=\"display: block; max-width: 100%; height: auto; cursor: zoom-in; width: 690px;\" data-catchresult=\"img_catchSuccess\"/></figure><p><br/></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p data-pid=\"PVAMhMnn\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">直接点击一下文本框，然后按下想要设置的快捷键就行，我的快捷键是Ctrl+Shift+C。</p><p data-pid=\"BFA_LOZ2\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">这里，你也可以用上Windows徽标键，勾选上后面的复选框即可。</p><p data-pid=\"xYBv8oiO\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">OK，简单的设置完成！</p><h3 style=\"font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 1.1em; line-height: 1.5; font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin: calc(1.90909em) 0px calc(1.27273em); clear: left; color: rgb(25, 27, 31); text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">Step 3. 使用Ditto</h3><p data-pid=\"kSFyqVtx\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">设置好Ditto之后，只要它在运行状态，就能够保存你复制过的所有项目。这些项目，<span style=\"font-weight: 600;\">包含了文本、文件、图片等内容。</span></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135185811097.jpg\" data-caption=\"\" data-size=\"normal\" data-rawwidth=\"566\" data-rawheight=\"747\" data-original-token=\"v2-d914136794ee684d3dfa5602d0211e84\" width=\"566\" data-original=\"https://pic2.zhimg.com/v2-e5c44f5f3f1c88ceb8c5290df41247f3_r.jpg\" style=\"display: block; max-width: 100%; height: auto; cursor: zoom-in; width: 690px;\" data-catchresult=\"img_catchSuccess\"/></figure><p><br/></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p data-pid=\"8fncnGQd\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">那么，如何快速使用它们呢？</p><p data-pid=\"HXuvfQLs\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">按下你刚才设置的快捷键，比如我的快捷键Ctrl+Shift+C，之后便会出现Ditto的“<span style=\"font-weight: 600;\"><a class=\"RichContent-EntityWord css-b7erz1\" data-za-not-track-link=\"true\" data-paste-text=\"true\" href=\"https://zhida.zhihu.com/search?content_id=169984063&content_type=Article&match_order=1&q=%E5%BF%AB%E9%80%9F%E7%B2%98%E8%B4%B4&zhida_source=entity\" target=\"_blank\" style=\"text-decoration-line: none; color: rgb(9, 64, 142); cursor: pointer;\">快速粘贴<svg width=\"10px\" height=\"10px\" viewbox=\"0 0 16 16\" class=\"ZDI ZDI--FourPointedStar16 css-1dvsrp\" fill=\"currentColor\"><path d=\"m5.068 9.267-3.08-.77a.512.512 0 0 1 0-.994l3.08-.77a2.289 2.289 0 0 0 1.665-1.665l.77-3.08a.512.512 0 0 1 .994 0l.77 3.08c.205.82.845 1.46 1.665 1.665l3.08.77a.512.512 0 0 1 0 .994l-3.08.77a2.29 2.29 0 0 0-1.665 1.665l-.77 3.08a.512.512 0 0 1-.994 0l-.77-3.08a2.289 2.289 0 0 0-1.665-1.665Z\"></path></svg></a></span>”界面——</p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135197214855.jpg\" data-caption=\"\" data-size=\"normal\" data-rawwidth=\"566\" data-rawheight=\"747\" data-original-token=\"v2-3a34eee8b3aecd14a5c0bc522cc0f76e\" width=\"566\" data-original=\"https://pic1.zhimg.com/v2-5296bb6b353b20990fc3672c3502bcb6_r.jpg\" style=\"display: block; max-width: 100%; height: auto; cursor: zoom-in; width: 690px;\" data-catchresult=\"img_catchSuccess\"/></figure><p><br/></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p data-pid=\"1X3pRj_s\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">这里展示了保存的所有复制记录，你可以通过双击需要的条目，来输出需要的内容。</p><p data-pid=\"3yr7amsu\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">另外，细心的你会发现，<span style=\"font-weight: 600;\">最近保存的10个条目，前方都有一个数字编号。</span></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135197518450.jpg\" data-caption=\"\" data-size=\"normal\" data-rawwidth=\"566\" data-rawheight=\"747\" data-original-token=\"v2-1605b526d3fffafb5715f3f474a2bab2\" width=\"566\" data-original=\"https://pic1.zhimg.com/v2-ea23c1d4d8108263fa90a7f8bd04235a_r.jpg\" style=\"display: block; max-width: 100%; height: auto; cursor: zoom-in; width: 690px;\" data-catchresult=\"img_catchSuccess\"/></figure><p><br/></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p data-pid=\"qZrhnODY\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">这意味着它们是你最近重要使用概率最高的内容，所以，你可以通过快捷键“<span style=\"font-weight: 600;\">Ctrl+对应序号</span>”来快速输出。</p><p data-pid=\"MsAQ3EZb\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">使用Ditto的过程中，你还会遇到这样的情况：</p><blockquote data-pid=\"-FWm9OQx\" style=\"border-left: 3px solid rgb(196, 199, 206); color: rgb(83, 88, 97); margin: 1.4em 0px; padding-left: 1em; font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">我曾经复制过一段话，能够记得其中的部分内容，但如果一条一条的翻，很浪费时间。</blockquote><p data-pid=\"xj2QbPKH\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">没关系，直接打开Ditto面板，然后输入关键词，Ditto便会自动查找，之后，选择使用。</p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><div class=\"GifPlayer css-1isopsn\" data-size=\"normal\" data-za-detail-view-path-module=\"GifItem\" style=\"cursor: pointer; max-width: 100%; overflow: hidden; position: relative; text-align: center; width: fit-content;\"><img width=\"1080\" role=\"presentation\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135196703692.jpg\" data-thumbnail=\"https://pica.zhimg.com/v2-66c210a3eca10095a2c22e0692ddc2c4_b.jpg\" data-size=\"normal\" alt=\"动图封面\" style=\"max-width: 100%; vertical-align: top; display: block;\" data-catchresult=\"img_catchSuccess\"/><div class=\"GifPlayer-icon css-d39tw7\" style=\"left: 345px; opacity: 1; pointer-events: none; position: absolute; top: 271.391px; transform: scale(1) translate(-50%, -50%); transform-origin: left top; transition: transform 0.3s ease-out, opacity;\"><svg width=\"50\" height=\"50\" viewbox=\"0 0 60 60\" xmlns=\"http://www.w3.org/2000/svg\"><g stroke=\"none\" stroke-width=\"1\" fill=\"none\" fill-rule=\"evenodd\"><ellipse fill=\"#000\" opacity=\"0.45\" cx=\"30\" cy=\"30\" rx=\"30\" ry=\"30\"></ellipse><ellipse stroke=\"#FFF\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" opacity=\"0.5\" cx=\"30\" cy=\"30\" rx=\"26\" ry=\"26\"></ellipse></g><svg x=\"16\" y=\"18.5\"><g fill=\"#fff\"><path x=\"100\" y=\"100\" d=\"M12.8422852,12.9814453 L12.8422852,11.3994141 L7.63916016,11.3994141 L7.63916016,13.0517578 L10.9086914,13.0517578 L10.9086914,13.3242188 C10.8911133,15.2050781 9.46728516,16.4707031 7.39306641,16.4707031 C5.01123047,16.4707031 3.51708984,14.625 3.51708984,11.6367188 C3.51708984,8.70117188 5.00244141,6.84667969 7.34912109,6.84667969 C9.08056641,6.84667969 10.284668,7.68164062 10.7768555,9.2109375 L12.7543945,9.2109375 C12.3237305,6.64453125 10.2319336,5.00976562 7.34912109,5.00976562 C3.79833984,5.00976562 1.50439453,7.61132812 1.50439453,11.6542969 C1.50439453,15.75 3.77197266,18.3076172 7.36669922,18.3076172 C10.6889648,18.3076172 12.8422852,16.2246094 12.8422852,12.9814453 Z M17.5180664,18 L17.5180664,5.31738281 L15.5493164,5.31738281 L15.5493164,18 L17.5180664,18 Z M22.659668,18 L22.659668,12.7441406 L28.1088867,12.7441406 L28.1088867,11.0039062 L22.659668,11.0039062 L22.659668,7.11035156 L28.6098633,7.11035156 L28.6098633,5.31738281 L20.690918,5.31738281 L20.690918,18 L22.659668,18 Z\"></path></g></svg></svg></div></div></figure><p><br/></p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p data-pid=\"PqK3xooG\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">以上的流程，基本上就是使用Ditto最多的场景了。恭喜你，迈出了高效使用剪贴板的第一步。</p><p data-pid=\"bldUIFcA\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">想继续进阶？往下看~</p><h2 style=\"font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 1.2em; line-height: 1.5; font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin: calc(2.33333em) 0px calc(1.16667em); clear: left; color: rgb(25, 27, 31); text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">3. Ditto使用技巧</h2><p data-pid=\"1W8PYXIq\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">接下来，为你分享一些Ditto中非常实用的“骚操作”。</p><h3 style=\"font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 1.1em; line-height: 1.5; font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin: calc(1.90909em) 0px calc(1.27273em); clear: left; color: rgb(25, 27, 31); text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">1. 清除格式，输出纯文本</h3><p data-pid=\"rm9FIM8t\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">如果你是复制Word或者网页中的一段文本，很可能，它是带有格式的，比如加粗、文本颜色等等。</p><p data-pid=\"pMBrPGdT\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">这时，如果你只想粘贴纯文本呢？</p><p data-pid=\"4gp4X_0V\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">你可以选择Ditto中对应的条目，然后按下<span style=\"font-weight: 600;\">Shift+Enter</span>键，即可以纯文本方式输出。</p><h3 style=\"font-variant-numeric: inherit; font-variant-east-asian: inherit; font-variant-alternates: inherit; font-variant-position: inherit; font-variant-emoji: inherit; font-stretch: inherit; font-size: 1.1em; line-height: 1.5; font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; margin: calc(1.90909em) 0px calc(1.27273em); clear: left; color: rgb(25, 27, 31); text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">2. 将复制内容快速保存为文件</h3><p data-pid=\"6D6cerFm\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">无论是文本、图片还是文件，你都可以<span style=\"font-weight: 600;\">通过选择、拖动的方式，将其快速保存为文件。</span></p><p data-pid=\"tLgzauOk\" style=\"margin-top: 1.4em; margin-bottom: 1.4em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\">其中，通过按住Ctrl（不连续的多个文件）或Shift（连续的多个文件）键，来<span style=\"font-weight: 600;\">选择多个条目</span>，类似于资源管理器中选择文件。</p><p class=\"ztext-empty-paragraph\" style=\"margin-top: -0.8em; margin-bottom: -0.8em; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><br/></p><p><br/></p><figure data-size=\"normal\" style=\"margin: 1.4em 0px; color: rgb(25, 27, 31); font-family: -apple-system, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Microsoft YaHei&quot;, &quot;Source Han Sans SC&quot;, &quot;Noto Sans CJK SC&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif; font-size: medium; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><div class=\"GifPlayer isPlaying css-g1g7n9\" data-size=\"normal\" data-za-detail-view-path-module=\"GifItem\" style=\"cursor: pointer; max-width: 100%; overflow: hidden; position: relative; text-align: center; width: fit-content;\"><img width=\"1079\" role=\"presentation\" src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/01/202501201135198448567.webp\" data-thumbnail=\"https://picx.zhimg.com/v2-2b9a2111533fd0c9eec9991bd114f23b_b.jpg\" data-size=\"normal\" alt=\"动图\" style=\"max-width: 100%; vertical-align: top; display: block;\" data-catchresult=\"img_catchSuccess\"/><div class=\"GifPlayer-icon css-d39tw7\" style=\