nbsp;=&nbsp;countChanges();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;创建结果区域的HTML\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;resultHTML&nbsp;=&nbsp;`\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;div&gt;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;div&gt;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;i&nbsp;class=&quot;fas&nbsp;fa-file-alt&quot;&gt;&lt;/i&gt;&nbsp;修改结果预览\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;/div&gt;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;button&nbsp;id=&quot;resultDownloadBtn&quot;&gt;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;i&nbsp;class=&quot;fas&nbsp;fa-download&quot;&gt;&lt;/i&gt;&nbsp;下载M3U文件\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;/button&gt;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;/div&gt;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;div&gt;修改已完成，共更新了&nbsp;&lt;strong&gt;${changesCount}&lt;/strong&gt;&nbsp;个分组标题&lt;/div&gt;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;pre&gt;${modifiedContent}&lt;/pre&gt;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;`;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;resultDiv.innerHTML&nbsp;=&nbsp;resultHTML;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;resultDiv.style.display&nbsp;=&nbsp;&#39;block&#39;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;m3uContent.value&nbsp;=&nbsp;modifiedContent;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;为结果区域中的下载按钮添加事件监听\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;document.getElementById(&#39;resultDownloadBtn&#39;).addEventListener(&#39;click&#39;,&nbsp;function()&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;defaultName&nbsp;=&nbsp;fileInput.files[0]&nbsp;?&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;fileInput.files[0].name.replace(/\\.[^/.]+$/,&nbsp;&quot;&quot;)&nbsp;+&nbsp;&#39;_modified.m3u&#39;&nbsp;:&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&#39;修改后的播放列表.m3u&#39;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;downloadFile(defaultName,&nbsp;modifiedContent);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;滚动到结果\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;resultDiv.scrollIntoView({&nbsp;behavior:&nbsp;&#39;smooth&#39;&nbsp;});\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;resetBtn.addEventListener(&#39;click&#39;,&nbsp;function&nbsp;()&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(confirm(&#39;确定要重置所有修改吗？所有编辑将被丢弃。&#39;))&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;displayGroupEditor(groupTitles);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;resultDiv.style.display&nbsp;=&nbsp;&#39;none&#39;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;function&nbsp;extractGroupTitles(content)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;lines&nbsp;=&nbsp;content.split(&#39;\\n&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;groups&nbsp;=&nbsp;new&nbsp;Set();\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;for&nbsp;(let&nbsp;line&nbsp;of&nbsp;lines)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;line&nbsp;=&nbsp;line.trim();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(line.startsWith(&#39;#EXTINF:-1&#39;))&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;match&nbsp;=&nbsp;line.match(/group-title=&quot;([^&quot;]+)&quot;/);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(match&nbsp;&amp;&amp;&nbsp;match[1])&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;groups.add(match[1]);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;Array.from(groups).sort();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;function&nbsp;displayGroupEditor(groups)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;groupsList.innerHTML&nbsp;=&nbsp;&#39;&#39;;\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;groups.forEach(group&nbsp;=&gt;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;groupItem&nbsp;=&nbsp;document.createElement(&#39;div&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;groupItem.className&nbsp;=&nbsp;&#39;group-item&#39;;\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;input&nbsp;=&nbsp;document.createElement(&#39;input&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;input.type&nbsp;=&nbsp;&#39;text&#39;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;input.value&nbsp;=&nbsp;group;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;input.dataset.original&nbsp;=&nbsp;group;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;input.placeholder&nbsp;=&nbsp;&#39;输入新的分组名称&#39;;\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;originalSpan&nbsp;=&nbsp;document.createElement(&#39;div&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;originalSpan.className&nbsp;=&nbsp;&#39;original-value&#39;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;originalSpan.textContent&nbsp;=&nbsp;`原始值:&nbsp;${group}`;\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;groupItem.appendChild(input);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;groupItem.appendChild(originalSpan);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;groupsList.appendChild(groupItem);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;function&nbsp;applyGroupTitleChanges(content,&nbsp;groups)&nbsp;{\r\nlet&nbsp;modified&nbsp;=&nbsp;content;\r\n\r\nconst&nbsp;inputs&nbsp;=&nbsp;groupsList.querySelectorAll(&#39;input&#39;);\r\n\r\ninputs.forEach(input&nbsp;=&gt;&nbsp;{\r\nconst&nbsp;orig&nbsp;=&nbsp;input.dataset.original;\r\nconst&nbsp;curr&nbsp;=&nbsp;input.value.trim();\r\nif&nbsp;(orig&nbsp;!==&nbsp;curr&nbsp;&amp;&amp;&nbsp;curr&nbsp;!==&nbsp;&#39;&#39;)&nbsp;{\r\nconst&nbsp;re&nbsp;=&nbsp;new&nbsp;RegExp(`group-title=&quot;${orig}&quot;`,&nbsp;&#39;g&#39;);\r\nmodified&nbsp;=&nbsp;modified.replace(re,&nbsp;`group-title=&quot;${curr}&quot;`);\r\n}\r\n});\r\n\r\n//&nbsp;清理所有以&nbsp;#EXTM3U&nbsp;开头的行，只保留第一个\r\nconst&nbsp;lines&nbsp;=&nbsp;modified.split(&#39;\\n&#39;);\r\nlet&nbsp;extm3uFound&nbsp;=&nbsp;false;\r\nconst&nbsp;cleanedLines&nbsp;=&nbsp;[];\r\n\r\nfor&nbsp;(let&nbsp;line&nbsp;of&nbsp;lines)&nbsp;{\r\nconst&nbsp;trimmedLine&nbsp;=&nbsp;line.replace(/^\\uFEFF/,&nbsp;&#39;&#39;).trim();\r\nif&nbsp;(/^#EXTM3U/i.test(trimmedLine))&nbsp;{\r\nif&nbsp;(!extm3uFound)&nbsp;{\r\ncleanedLines.push(trimmedLine);&nbsp;//&nbsp;保留第一个\r\nextm3uFound&nbsp;=&nbsp;true;\r\n}\r\n//&nbsp;跳过其他\r\n}&nbsp;else&nbsp;{\r\ncleanedLines.push(line);\r\n}\r\n}\r\n\r\nreturn&nbsp;cleanedLines.join(&#39;\\n&#39;);\r\n}\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;function&nbsp;countChanges()&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;let&nbsp;count&nbsp;=&nbsp;0;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;groupsList.querySelectorAll(&#39;input&#39;).forEach(input&nbsp;=&gt;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(input.value.trim()&nbsp;!==&nbsp;input.dataset.original&nbsp;&amp;&amp;&nbsp;input.value.trim()&nbsp;!==&nbsp;&#39;&#39;)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;count++;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;count;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;function&nbsp;downloadFile(filename,&nbsp;content)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;element&nbsp;=&nbsp;document.createElement(&#39;a&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;element.setAttribute(&#39;href&#39;,&nbsp;&#39;data:text/plain;charset=utf-8,&#39;&nbsp;+&nbsp;encodeURIComponent(content));\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;element.setAttribute(&#39;download&#39;,&nbsp;filename);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;element.style.display&nbsp;=&nbsp;&#39;none&#39;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;document.body.appendChild(element);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;element.click();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;document.body.removeChild(element);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\r\n&nbsp;&nbsp;&nbsp;&nbsp;&lt;/script&gt;\r\n&lt;/body&gt;\r\n&lt;/html&gt;</pre><p><br/></p>', '1753259965', '0', '287', '', '', '1753260271', '1753260271');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('639', '2', '1', '', '0', '0', '', '0', '0', 'mytv管理后台系统', '<p>传说已久的mytv后台管理终于被分享出来了，原帖地址：<a href=\"https://laokhome.cn/mytv-iptv\" _src=\"https://laokhome.cn/mytv-iptv\">https://laokhome.cn/mytv-iptv</a> </p><p>群晖套件版已上架，在套件中心添加矿神源：<a href=\"https://spk7.imnks.com/\" _src=\"https://spk7.imnks.com/\">https://spk7.imnks.com/</a></p><!--autointro-->', '<p>传说已久的mytv后台管理终于被分享出来了，原帖地址：<a href=\"https://laokhome.cn/mytv-iptv\" _src=\"https://laokhome.cn/mytv-iptv\">https://laokhome.cn/mytv-iptv</a> </p><p>群晖套件版已上架，在套件中心添加矿神源：<a href=\"https://spk7.imnks.com/\" _src=\"https://spk7.imnks.com/\">https://spk7.imnks.com/</a>&nbsp;即可搜索安装。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/08/202508081030574923718.png\" alt=\"image.png\"/></p><p>本站长于第一时间进行了安装体验，系统完成度比较高，功能齐全，使用方便，值得推荐！</p><p>在此感谢此管理系统的开发者，mytv的开发者，CCTV, CCAV, 亲戚朋友们！</p><p><br/></p><p>系统包括了一个简单的首页，用于介绍系统和app功能等，</p><p>后台功能包括订阅源管理，套餐管理，用户管理，以及app全自动修改/打包程序，app推送升级服务，以及一些app常用的信息设置。</p><p>系统通过创建一个安全密钥，实现多层加密，用户信息和源的安全性，有效避免攻击导致资源泄露，被其他人无限播放，耗费服务器流量。</p><p style=\"line-height: 16px;\"><span style=\"text-wrap-mode: wrap;\"><br/></span></p><p style=\"line-height: 16px;\"><span style=\"text-wrap-mode: wrap;\">在此处可以获取备份的安装文件：</span></p><p class=\"ue-upload\" style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_system/image/filetype/zip.png\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/12/202512181766030815311276.zip\" title=\"mytvadmin-release-mytvadmin-20251213.zip\">mytvadmin-release-mytvadmin-20251213.zip</a></p><p style=\"line-height: 16px;\"><span style=\"text-wrap-mode: wrap;\"></span><br/></p><p style=\"line-height: 16px;\"><br/></p><p>安装需要的环境：</p><p>php7.3+, mysql数据库，java环境</p><p><br/></p><p>以下我贴出在群晖上安装实验的截图：</p><p><br/></p><p>安装前确保群晖上已安装php，mariaDB</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251027136831462.png\" alt=\"image.png\"/><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251027249994490.png\" alt=\"image.png\"/></p><p><br/></p><p>下载安装文件，解压到服务器上：<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251023028735880.png\" alt=\"image.png\"/></p><p>在webstation中创建一个网页服务：<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251024195863983.png\" alt=\"image.png\"/></p><p>再去file station中给这个目录提一下权限为可读可写：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251025193341898.png\" alt=\"image.png\"/></p><p>创建一个网络门户，我这里使用的端口：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251026142226774.png\" alt=\"image.png\"/></p><p>此时使用浏览器访问创建的网页即可开始安装：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/08/202508130938124067736.png\" alt=\"image.png\"/></p><p>点击同意按钮后，进入服务器信息配置：</p><p>正常情况下，屏幕左上角会可进行安装，说明安装环境是符合程序要求的。<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/08/202508130938339644268.png\" alt=\"image.png\"/></p><p>输入数据库的信息，配置默认的管理员账号和密码，即可点击开始安装。</p><p>如果遇到提示<br/></p><h3 style=\"font-family: &quot;Alibaba PuHuiTi 3.0&quot;; text-wrap-mode: wrap; color: red;\">❌ 初始化失败：SQLSTATE[HY000] [1045] Access denied for user &#39;root&#39;@&#39;localhost&#39; (using password: YES)</h3><p>说明数据库密码输入错误，检查密码后，重新输入进行安装。</p><p><br/></p><p>安装成功后，页面会跳转到首页：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251033317039471.png\" alt=\"image.png\"/></p><p>在域名后面增加/admin 即可进入后台，使用刚才设置的管理员账号/密码进行登陆。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251034127440174.png\" alt=\"image.png\"/></p><p>登陆成功后：</p><p>首页显示一些系统数据，和最近一周的数据统计。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251035172243999.png\" alt=\"image.png\"/></p><p>此时需要先打包app，把下载的app模板文件拷贝到/appCreation 目录中，回到后台点击<strong>生成</strong><strong>APP</strong><strong>：</strong></p><p><strong><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251037085658774.png\" alt=\"image.png\"/></strong></p><p><strong><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251037385078570.png\" alt=\"image.png\"/></strong></p><p>生成过程较长，要耐心等待，直到正在打包中的按钮恢复可点击状态即专属app生成完成。</p><p>然后就可以在系统中点击资源管理，添加自己的源：</p><p>可以通过四种添加源的方式添加。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251045216560225.png\" alt=\"image.png\"/></p><p>在授权模板中，对源进行分组，创建授权模板，</p><p><span style=\"color: #C00000;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251046106172924.png\" alt=\"image.png\"/></span></p><p><span style=\"color: #000000;\">然后即可以安装app到手机或者电视上使用，</span></p><p><span style=\"color: #000000;\">第一次使用时候会在后台请求授权，</span></p><p><span style=\"color: #000000;\">登陆后台进入用户授权页面对设备选择一个授权模板，给授权，也可以在这里给设备备注一个名称，如果有必要，还可以取消授权。</span></p><p>如果取消授权，该客户端会保持未授权状态，如果选择禁用，则此用户被加入黑名单，不再出现在待授权里。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507281842583117453.png\" alt=\"image.png\"/></p><p>如果有app升级，可以在app升级页面推送升级的app信息，这时候客户端就可以收到升级推送，自行安装升级后的app.</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251047149429776.png\" alt=\"image.png\"/></p><p style=\"text-wrap-mode: wrap;\">在账户管理里，可以需改管理员账户信息，或者新增一个管理账户，</p><p style=\"text-wrap-mode: wrap;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/08/202508291836094692151.png\" alt=\"image.png\"/></p><p>在系统设置中，可以管理epg，logo的来源，即更换系统密钥<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/08/202508291835425275026.png\" alt=\"image.png\"/></p><p>也可以在这里找到重置系统的入口，点击后跳转到重置系统页面，输入数据库密码，通过验证后即删除系统创建的所有信息，包括数据量，缓存文件等，恢复到未安装状态，需要谨慎操作。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507251009324738344.png\" alt=\"image.png\"/></p>', '1753409370', '0', '1265', '', '', '1753409397', '1766030823');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('640', '2', '1', '', '0', '0', '', '0', '0', '一个TXT和M3U格式互转的工具', '<p>快速实现TXT转M3U，或M3U转TXT格式直播源，支持DIYP分组格式</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507291005446319803.rar\" title=\"t2m.rar\"></a></p><!--autointro-->', '<p>快速实现TXT转M3U，或M3U转TXT格式直播源，支持DIYP分组格式</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507291005446319803.rar\" title=\"t2m.rar\">t2m.rar</a></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\">在线测试：<a href=\"{#ZC_BLOG_HOST#}tv/t2m.html\">IPTV-M3U转换工具</a></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/07/202507291005075116615.png\" alt=\"image.png\"/></p><p>代码如下：</p><pre class=\"brush:bash;toolbar:false\">&lt;!DOCTYPE&nbsp;html&gt;\r\n&lt;html&gt;\r\n&lt;head&gt;\r\n&nbsp;&nbsp;&lt;meta&nbsp;charset=&quot;UTF-8&quot;&gt;\r\n&nbsp;&nbsp;&lt;meta&nbsp;name=&quot;viewport&quot;&nbsp;content=&quot;width=device-width,&nbsp;initial-scale=1.0&quot;&gt;\r\n&nbsp;&nbsp;&lt;title&gt;IPTV-M3U转换工具&lt;/title&gt;\r\n&nbsp;&nbsp;&lt;style&gt;\r\n&nbsp;&nbsp;&nbsp;&nbsp;:root&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;--primary-color:&nbsp;#3498db;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;--secondary-color:&nbsp;#2ecc71;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;--danger-color:&nbsp;#e74c3c;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;--dark-color:&nbsp;#2c3e50;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;--light-color:&nbsp;#ecf0f1;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;--border-radius:&nbsp;6px;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;--box-shadow:&nbsp;0&nbsp;4px&nbsp;6px&nbsp;rgba(0,&nbsp;0,&nbsp;0,&nbsp;0.1);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;--transition:&nbsp;all&nbsp;0.3s&nbsp;ease;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;*&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;box-sizing:&nbsp;border-box;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;margin:&nbsp;0;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;padding:&nbsp;0;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;body&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;font-family:&nbsp;&#39;Segoe&nbsp;UI&#39;,&nbsp;Tahoma,&nbsp;Geneva,&nbsp;Verdana,&nbsp;sans-serif;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;background-color:&nbsp;#f5f7fa;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;color:&nbsp;#333;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;line-height:&nbsp;1.6;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;min-height:&nbsp;100vh;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;display:&nbsp;flex;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;flex-direction:&nbsp;column;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.header&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;background:&nbsp;linear-gradient(135deg,&nbsp;var(--primary-color),&nbsp;var(--secondary-color));\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;color:&nbsp;white;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;padding:&nbsp;1.5rem&nbsp;0;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;text-align:&nbsp;center;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;box-shadow:&nbsp;var(--box-shadow);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;margin-bottom:&nbsp;2rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.header&nbsp;h1&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;font-size:&nbsp;2rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;font-weight:&nbsp;600;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;margin-bottom:&nbsp;0.5rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.container&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;max-width:&nbsp;1200px;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;margin:&nbsp;0&nbsp;auto;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;padding:&nbsp;0&nbsp;1.5rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;flex:&nbsp;1;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;width:&nbsp;100%;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.card&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;background:&nbsp;white;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;border-radius:&nbsp;var(--border-radius);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;box-shadow:&nbsp;var(--box-shadow);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;padding:&nbsp;1.5rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;margin-bottom:&nbsp;2rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.card-title&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;font-size:&nbsp;1.25rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;margin-bottom:&nbsp;1rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;color:&nbsp;var(--dark-color);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;font-weight:&nbsp;600;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;border-bottom:&nbsp;1px&nbsp;solid&nbsp;#eee;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;padding-bottom:&nbsp;0.5rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.button-group&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;display:&nbsp;flex;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;gap:&nbsp;0.75rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;flex-wrap:&nbsp;wrap;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;margin-bottom:&nbsp;1.5rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.button&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;padding:&nbsp;0.75rem&nbsp;1.25rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;border:&nbsp;none;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;border-radius:&nbsp;var(--border-radius);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;font-size:&nbsp;0.95rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;font-weight:&nbsp;500;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;cursor:&nbsp;pointer;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;transition:&nbsp;var(--transition);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;display:&nbsp;inline-flex;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;align-items:&nbsp;center;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;justify-content:&nbsp;center;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;gap:&nbsp;0.5rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.button-primary&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;background-color:&nbsp;var(--primary-color);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;color:&nbsp;white;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.button-secondary&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;background-color:&nbsp;var(--secondary-color);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;color:&nbsp;white;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.button-danger&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;background-color:&nbsp;var(--danger-color);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;color:&nbsp;white;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.button-outline&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;background-color:&nbsp;transparent;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;border:&nbsp;1px&nbsp;solid&nbsp;var(--primary-color);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;color:&nbsp;var(--primary-color);\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.button:hover&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;transform:&nbsp;translateY(-2px);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;box-shadow:&nbsp;0&nbsp;6px&nbsp;12px&nbsp;rgba(0,&nbsp;0,&nbsp;0,&nbsp;0.1);\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.file-input&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;margin-bottom:&nbsp;1.5rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.file-input&nbsp;label&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;display:&nbsp;block;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;margin-bottom:&nbsp;0.5rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;font-weight:&nbsp;500;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;color:&nbsp;var(--dark-color);\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.file-input&nbsp;input[type=&quot;file&quot;]&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;width:&nbsp;100%;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;padding:&nbsp;0.75rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;border:&nbsp;1px&nbsp;solid&nbsp;#ddd;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;border-radius:&nbsp;var(--border-radius);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;background-color:&nbsp;white;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.preview-container&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;display:&nbsp;flex;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;flex-wrap:&nbsp;wrap;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;gap:&nbsp;1.5rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;margin-top:&nbsp;1.5rem;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.preview-column&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;flex:&nbsp;1;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;min-width:&nbsp;300px;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;.preview-header&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;display:&nbsp;flex;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;justify-content:&nbsp;space-between;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;align-i