;=&nbsp;result[1];\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;groupTitle.replace(/^\\s*|\\s*$/g,&nbsp;&#39;&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;function&nbsp;clearBefore()&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;m3uPreview&nbsp;=&nbsp;document.getElementById(&quot;previewBefore&quot;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;m3uPreview.value&nbsp;=&nbsp;&#39;&#39;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;fileInput&nbsp;=&nbsp;document.getElementById(&quot;fileInput&quot;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;fileInput.value&nbsp;=&nbsp;&#39;&#39;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;function&nbsp;clearAfter()&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;txtPreview&nbsp;=&nbsp;document.getElementById(&quot;previewAfter&quot;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;txtPreview.value&nbsp;=&nbsp;&#39;&#39;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;convertedData&nbsp;=&nbsp;&#39;&#39;;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;function&nbsp;copyContent()&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;m3uOutput&nbsp;=&nbsp;document.getElementById(&#39;previewAfter&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;m3uOutput.select();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if(m3uOutput.value&nbsp;==&nbsp;&#39;&#39;)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;alert(&#39;没有内容可复制！&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;document.execCommand(&#39;copy&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;alert(&#39;内容已复制到剪贴板！&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;拖拽功能\r\n&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;box&nbsp;=&nbsp;document.getElementById(&#39;container&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;document.ondrop&nbsp;=&nbsp;function(e){\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;e.preventDefault();\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;document.ondragover&nbsp;=&nbsp;function(e){\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;e.preventDefault();\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;box.ondrop&nbsp;=&nbsp;function(e){\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;dataFile&nbsp;=&nbsp;e.dataTransfer.files[0];\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;fr&nbsp;=&nbsp;new&nbsp;FileReader();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;fr.readAsText(dataFile);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;fr.onload&nbsp;=&nbsp;function(){\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;data&nbsp;=&nbsp;fr.result;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;var&nbsp;ta&nbsp;=&nbsp;document.getElementById(&#39;previewBefore&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ta.value&nbsp;=&nbsp;data;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;Ctrl+S&nbsp;快捷键保存\r\n&nbsp;&nbsp;&nbsp;&nbsp;window.addEventListener(&quot;keydown&quot;,&nbsp;function(e)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if((e.key==&#39;s&#39;||e.key==&#39;S&#39;)&amp;&amp;(navigator.platform.match(&quot;Mac&quot;)&nbsp;?&nbsp;e.metaKey&nbsp;:&nbsp;e.ctrlKey)){\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;e.preventDefault();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;exportConvertedFile();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;},&nbsp;false);\r\n&nbsp;&nbsp;&lt;/script&gt;\r\n&lt;/body&gt;\r\n&lt;/html&gt;</pre><p><br/></p>', '1753754608', '0', '273', '', '', '1753754828', '1753754828');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('644', '2', '1', '', '0', '0', '', '0', '0', '一个简单的网页点击次数计数器php', '<p>使用php写的一个简单的按钮点击次数计数器，提供计数和读数查询接口：</p><p>计数：<strong>?key={计数字段}&amp;action=hit</strong></p><p>读数：<strong><span style=\"text-wrap-mode: wrap;\">?key={计数字段}&amp;action=get</span></strong></p><p><span style=\"text-wrap-mode: wrap;\"><br/></span></p><p>下载php:&nbsp;</p><!--autointro-->', '<p>使用php写的一个简单的按钮点击次数计数器，提供计数和读数查询接口：</p><p>计数：<strong>?key={计数字段}&amp;action=hit</strong></p><p>读数：<strong><span style=\"text-wrap-mode: wrap;\">?key={计数字段}&amp;action=get</span></strong></p><p><span style=\"text-wrap-mode: wrap;\"><br/></span></p><p>下载php:&nbsp;</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/08/202508141007015667718.rar\" title=\"count.rar\">count.rar</a></p><p><br/></p><p>后端会以json格式记录对应字段的点击次数：</p><pre class=\"brush:bash;toolbar:false\">{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;xxx&quot;:&nbsp;8,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;SPKServer&quot;:&nbsp;2,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;MyTVAdmin&quot;:&nbsp;6,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;ffmpeg7&quot;:&nbsp;1,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;gitea&quot;:&nbsp;1,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;TVBox&quot;:&nbsp;3,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;transmission&quot;:&nbsp;1,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;zblog&quot;:&nbsp;2\r\n}</pre><p><br/></p><p>代码：</p><pre class=\"brush:bash;toolbar:false\">&lt;?php\r\n//&nbsp;允许跨域\r\nheader(&quot;Access-Control-Allow-Origin:&nbsp;*&quot;);\r\nheader(&quot;Access-Control-Allow-Methods:&nbsp;GET,&nbsp;POST,&nbsp;OPTIONS&quot;);\r\nheader(&quot;Access-Control-Allow-Headers:&nbsp;Content-Type&quot;);\r\nheader(&quot;Content-Type:&nbsp;application/json;&nbsp;charset=utf-8&quot;);\r\n\r\n//&nbsp;处理&nbsp;OPTIONS&nbsp;预检请求\r\nif&nbsp;($_SERVER[&#39;REQUEST_METHOD&#39;]&nbsp;===&nbsp;&#39;OPTIONS&#39;)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;http_response_code(204);\r\n&nbsp;&nbsp;&nbsp;&nbsp;exit;\r\n}\r\n\r\n$key&nbsp;=&nbsp;isset($_GET[&#39;key&#39;])&nbsp;?&nbsp;preg_replace(&#39;/[^a-zA-Z0-9_-]/&#39;,&nbsp;&#39;&#39;,&nbsp;$_GET[&#39;key&#39;])&nbsp;:&nbsp;&#39;default&#39;;\r\n$action&nbsp;=&nbsp;isset($_GET[&#39;action&#39;])&nbsp;?&nbsp;$_GET[&#39;action&#39;]&nbsp;:&nbsp;&#39;get&#39;;\r\n\r\n$file&nbsp;=&nbsp;__DIR__&nbsp;.&nbsp;&quot;/counts.json&quot;;\r\n\r\n//&nbsp;初始化文件\r\nif&nbsp;(!file_exists($file))&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;file_put_contents($file,&nbsp;json_encode(new&nbsp;stdClass()));\r\n}\r\n\r\n$data&nbsp;=&nbsp;json_decode(file_get_contents($file),&nbsp;true);\r\nif&nbsp;(!is_array($data))&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;$data&nbsp;=&nbsp;[];\r\n}\r\n\r\nif&nbsp;($action&nbsp;===&nbsp;&quot;hit&quot;)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(!isset($data[$key]))&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;$data[$key]&nbsp;=&nbsp;0;\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;$data[$key]++;\r\n&nbsp;&nbsp;&nbsp;&nbsp;file_put_contents($file,&nbsp;json_encode($data,&nbsp;JSON_PRETTY_PRINT&nbsp;|&nbsp;JSON_UNESCAPED_UNICODE));\r\n}\r\n\r\n$count&nbsp;=&nbsp;isset($data[$key])&nbsp;?&nbsp;$data[$key]&nbsp;:&nbsp;0;\r\n\r\necho&nbsp;json_encode([\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;key&quot;&nbsp;=&gt;&nbsp;$key,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&quot;value&quot;&nbsp;=&gt;&nbsp;$count\r\n],&nbsp;JSON_UNESCAPED_UNICODE&nbsp;|&nbsp;JSON_UNESCAPED_SLASHES);</pre><p><br/></p><p>此代码中有一个允许跨域的设置，其他程序中如果需要用到不同域名之间的调用，可以参考此设置：</p><pre class=\"brush:bash;toolbar:false\">//&nbsp;允许跨域\r\nheader(&quot;Access-Control-Allow-Origin:&nbsp;*&quot;);\r\nheader(&quot;Access-Control-Allow-Methods:&nbsp;GET,&nbsp;POST,&nbsp;OPTIONS&quot;);\r\nheader(&quot;Access-Control-Allow-Headers:&nbsp;Content-Type&quot;);</pre><p><br/></p>', '1755137055', '0', '196', '', '', '1755137348', '1755137359');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('645', '2', '1', '', '0', '0', '', '0', '0', '把仓库文件推送到自己的github上', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>在GitHub上创建一个仓库</p></li><li><p>把要推送的文件放在一个文件夹中</p></li><li><p>使用下面脚本推送，最后一行main视情况看你仓库是main分支还是master分支，或是其他分支<br/></p></li><pre class=\"brush:bash;toolbar:false\">rm&nbsp;-rf&nbsp;.git&nbsp;&nbsp;&nbsp;#&nbsp;删除本地&nbsp;.git&nbsp;文件夹（谨慎操作！）\r\ngit&nbsp;init&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;重新初始化\r\ngit&nbsp;add&nbsp;.\r\ngit&nbsp;commit&nbsp;-m&nbsp;&quot;Initial&nbsp;commit&quot;\r\ngit&nbsp;remote&nbsp;add&nbsp;origin&nbsp;https://github.com/Brian099/mytv-Internal.git\r\ngit&nbsp;push&nbsp;-u&nbsp;origin&nbsp;main</pre></ol><!--autointro-->', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>在GitHub上创建一个仓库</p></li><li><p>把要推送的文件放在一个文件夹中</p></li><li><p>使用下面脚本推送，最后一行main视情况看你仓库是main分支还是master分支，或是其他分支<br/></p></li><pre class=\"brush:bash;toolbar:false\">rm&nbsp;-rf&nbsp;.git&nbsp;&nbsp;&nbsp;#&nbsp;删除本地&nbsp;.git&nbsp;文件夹（谨慎操作！）\r\ngit&nbsp;init&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;重新初始化\r\ngit&nbsp;add&nbsp;.\r\ngit&nbsp;commit&nbsp;-m&nbsp;&quot;Initial&nbsp;commit&quot;\r\ngit&nbsp;remote&nbsp;add&nbsp;origin&nbsp;https://github.com/Brian099/mytv-Internal.git\r\ngit&nbsp;push&nbsp;-u&nbsp;origin&nbsp;main</pre></ol>', '1755589181', '0', '203', '', '', '1755589360', '1755589360');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('646', '2', '1', '', '0', '0', '', '0', '0', 'Edge禁止http自动跳转https', '<p>不知道从哪个版本开始，浏览器会自动记录域名的访问方式，如果你用https访问过某个域名，以后他会自动使用https访问来自这个域名的网站。</p><p>如果有些端口是http的，有些是https的，就很麻烦，可以在设置中禁止跳转功能：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509050955257620250.png\" alt=\"image.png\"/></p><p>关闭此选项后，清除以下浏览器历史记录，即可禁止自动跳转。</p><!--autointro-->', '<p>不知道从哪个版本开始，浏览器会自动记录域名的访问方式，如果你用https访问过某个域名，以后他会自动使用https访问来自这个域名的网站。</p><p>如果有些端口是http的，有些是https的，就很麻烦，可以在设置中禁止跳转功能：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509050955257620250.png\" alt=\"image.png\"/></p><p>关闭此选项后，清除以下浏览器历史记录，即可禁止自动跳转。</p>', '1757037205', '0', '169', '', '', '1757037357', '1757037357');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('647', '2', '1', '', '0', '0', '', '0', '0', '使用docker搭建webdav服务器chfs，支持网页访问', '<p>[转载]&nbsp;<a href=\"https://mp.weixin.qq.com/s/Q4b8-fQ1nXQvhdFNb0bNRw\">搭建轻量文件共享服务器，Docker 部署 chfs 指南</a></p><p><br/></p><p>这个软件是个不错的软件，支持多个平台，我一直在用windows的，现在docker版来到了，先留个记录。</p><p><br/>chfs（CuteHttpFileServer）：</p><p>一个免费的、HTTP 协议的文件共享服务器，使用浏览器可以快速访问。</p><!--autointro-->', '<p>[转载]&nbsp;<a href=\"https://mp.weixin.qq.com/s/Q4b8-fQ1nXQvhdFNb0bNRw\">搭建轻量文件共享服务器，Docker 部署 chfs 指南</a></p><p><br/></p><p>这个软件是个不错的软件，支持多个平台，我一直在用windows的，现在docker版来到了，先留个记录。</p><p><br/>chfs（CuteHttpFileServer）：</p><p>一个免费的、HTTP 协议的文件共享服务器，使用浏览器可以快速访问。</p><p><br/></p><p>特色：</p><p>• 单个文件，核心功能无需其他文件</p><p>• 跨平台运行，支持主流平台：Windows，Linux 和 Mac</p><p>• 界面简洁，简单易用</p><p>• 支持扫码下载和手机端访问，手机与电脑之间共享文件非常方便</p><p>• 支持账户权限控制和地址过滤</p><p>• 支持快速分享文字片段</p><p>• 支持 webdav 协议</p><p><br/></p><p style=\"-webkit-tap-highlight-color: transparent; margin: 2em 8px 0.75em 0px; padding: 0px 0px 0px 8px; outline: 0px; font-size: 15.4px; max-width: 100%; box-sizing: border-box; font-family: -apple-system-font, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei UI&quot;, &quot;Microsoft YaHei&quot;, Arial, sans-serif; text-wrap-mode: wrap; border-width: 0px 0px 0px 3px; border-style: solid; border-color: rgb(229, 229, 229) rgb(229, 229, 229) rgb(229, 229, 229) rgb(15, 76, 129); line-height: 1.2; color: rgb(63, 63, 63); overflow-wrap: break-word !important;\">安装</p><p>Docker Compose</p><pre class=\"brush:as3;toolbar:false\">services:\r\n&nbsp;chfs:\r\n&nbsp;&nbsp;image:&nbsp;docblue/chfs:v4.0beta.min\r\n&nbsp;&nbsp;container_name:&nbsp;chfs\r\n&nbsp;&nbsp;ports:\r\n&nbsp;&nbsp;&nbsp;-&nbsp;6080:80\r\n&nbsp;&nbsp;volumes:\r\n&nbsp;&nbsp;&nbsp;-&nbsp;/vol1/1000/docker/chfs/data:/data\r\n&nbsp;&nbsp;&nbsp;-&nbsp;/vol1/1000/docker/chfs/config:/config\r\n&nbsp;&nbsp;restart:&nbsp;always</pre><p>下载 chfs.ini 配置文件，放到 config 配置文件目录</p><p><br/></p><a href=\"http://iscute.cn/asset/chfs.ini\" _src=\"http://iscute.cn/asset/chfs.ini\">http://iscute.cn/asset/chfs.ini</a><div><br/> <p>参数说明（更多参数建议去看文档）</p><p>:::<br/><strong>/data（路径）：共享文件目录（可以按实际情况映射路径）</strong></p><p><strong>/config（路径）：配置文件目录</strong></p><p><br/></p><p style=\"-webkit-tap-highlight-color: transparent; margin: 2em 8px 0.75em 0px; padding: 0px 0px 0px 8px; outline: 0px; font-size: 15.4px; max-width: 100%; box-sizing: border-box; font-family: -apple-system-font, BlinkMacSystemFont, &quot;Helvetica Neue&quot;, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei UI&quot;, &quot;Microsoft YaHei&quot;, Arial, sans-serif; text-wrap-mode: wrap; border-width: 0px 0px 0px 3px; border-style: solid; border-color: rgb(229, 229, 229) rgb(229, 229, 229) rgb(229, 229, 229) rgb(15, 76, 129); line-height: 1.2; color: rgb(63, 63, 63); overflow-wrap: break-word !important;\">使用</p><p>浏览器中输入&nbsp;http://NAS的IP:6080&nbsp;就能看到界面</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111606451409059.png\" alt=\"image.png\"/></p><p>界面还是比较简单直观的，没有这么多花里胡哨</p><p>看到当前目录很多不应该显示文件和目录，只需要显示 data 目录就行了</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111609053609185.png\" alt=\"image.png\"/></p><p>编辑 chfs.ini 配置文件，修改为 path=/data</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111609193750457.png\" alt=\"image.png\"/></p><p>TIP：每次修改完成，最好都重启一下容器</p><p>修改过后，现在访问根目录就是 data 路径了</p><p><br/></p><p>顶部功能栏，上传文件，上传目录，新建文本，新建目录和搜索都是没问题的</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111609492898609.png\" alt=\"image.png\"/></p><p><br/></p><p>来到映射的 data 目录，也能看到网页上传文件</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111610272112960.png\" alt=\"image.png\"/></p><p><br/></p><p>对文件或者目录，支持直接下载，扫码下载，重命名和删除等操作</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111610424276002.png\" alt=\"image.png\"/></p><p><br/></p><p>TIP：删除操作可能会提示操作失败,&nbsp;编辑 chfs.ini 配置文件，修改为 file.remove=3</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111611135420845.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111611002610424.png\" alt=\"image.png\"/></p><p><br/></p><p>滑动到最下面，可以修改游客账号权限和创建管理员账号</p><pre class=\"brush:as3;toolbar:false\">[admin]\r\npassword=123\r\nrule.default=d</pre><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111611329025083.png\" alt=\"image.png\"/></p><p><br/></p><p>设置账号以后，就可以点击登录了</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111611464503360.png\" alt=\"image.png\"/></p><p>支持 webdav，输入&nbsp;http://NAS的IP:6080/webdav&nbsp;就能直接挂载本地</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509111611582876517.png\" alt=\"image.png\"/></p></div>', '1757577743', '0', '195', '', '', '1757578422', '1757578422');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('642', '2', '1', '', '0', '0', '', '0', '0', '在控制台中用wget下载文件时，怎么使用旁路由加速', '<p>如果你的旁路已经正确科学上网，并开启了socks, 局域网的其他设备就可以通过这个代理加速下载github的文件，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/08/202508041113223710892.png\" alt=\"image.png\"/></p><p>使用时在脚本中先设置环境变量：</p><p><strong># 使用http</strong></p><p>export http_proxy=http://192.168.1.2:1805</p><!--autointro-->', '<p>如果你的旁路已经正确科学上网，并开启了socks, 局域网的其他设备就可以通过这个代理加速下载github的文件，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/08/202508041113223710892.png\" alt=\"image.png\"/></p><p>使用时在脚本中先设置环境变量：</p><p><strong># 使用http</strong></p><p>export http_proxy=http://192.168.1.2:1805</p><p>export https_proxy=http://192.168.1.2:1805</p><p>再进行下载：</p><p>wget <a href=\"https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z\" _src=\"https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z\">https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z</a> </p><p>下载时不需要添加前缀。</p><p><br/></p><p>如果只对当前下载生效：</p><p>wget -e http_proxy=http://192.168.1.2:1085 -e https_proxy=http://192.168.1.2:1085 <a href=\"https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z\" _src=\"https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z\">https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z</a> </p><p><br/></p><p><strong># 使用socks</strong></p><p>export ALL_PROXY=socks5h://127.0.0.1:1080</p><p style=\"text-wrap-mode: wrap;\">再进行下载：</p><p style=\"text-wrap-mode: wrap;\">wget&nbsp;<a href=\"https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z\" _src=\"https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z\">https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z</a></p><p style=\"text-wrap-mode: wrap;\">下载时不需要添加前缀。</p><p><br/></p><p>如果只对当前下载生效：</p><p>ALL_PROXY=socks5h://127.0.0.1:1080 wget&nbsp;<a href=\"https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z\" _src=\"https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z\" style=\"text-wrap-mode: wrap;\">https://github.com/hjdhnx/drpy-node/releases/download/v1.2.5/drpy-node-20250804-green.7z</a></p>', '1754277103', '0', '242', '', '', '1754277551', '1754977365');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('643', '2', '1', '', '0', '0', '', '0', '0', '最新上线的群晖应用中心第三方套件市场', '<p>laok:</p><p>直接在套件中心添加套件源：<a href=\"http://nas.laokhome.cn:8808\" _src=\"http://nas.laokhome.cn:8808\">http://nas.laokhome.cn:8808</a> </p><p>离线安装包下载地址：<a href=\"http://nas.laokhome.cn:8808/download/\" _src=\"http://nas.laokhome.cn:8808/download/\">http://nas.laokhome.cn:8808/download/</a></p><!--autointro-->', '<p>laok:</p><p>直接在套件中心添加套件源：<a href=\"http://nas.laokhome.cn:8808\" _src=\"http://nas.laokhome.cn:8808\">http://nas.laokhome.cn:8808</a> </p><p>离线安装包下载地址：<a href=\"http://nas.laokhome.cn:8808/download/\" _src=\"http://nas.laokhome.cn:8808/download/\">http://nas.laokhome.cn:8808/download/</a> </p><p><br/></p><p>Giraff</p><p>直接在套件中心添加套件源：<a href=\"https://28918185.xyz:25086\" _src=\"https://28918185.xyz:25086\">https://28918185.xyz:25086</a></p><p>离线安装包下载地址：<a href=\"https://28918185.xyz:25086/d/\" _src=\"https://28918185.xyz:25086/d/\">https://28918185.xyz:25086/d/</a> </p><p><br/></p><br/>', '1754535149', '0', '245', '', '', '1754535364', '1754535364');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('648', '2', '1', '', '0', '0', '', '0', '0', '怎么快速把excel中指定的字符替换为换行符，达到单行转多行的目的', '<p>在excel中用快捷键Ctrl+H调出替换窗口，</p><p>替换内容输入要替换的文字，替换为中输入方法：</p><p><strong>Windows系统：按住 Alt 键，然后在数字小键盘上依次输入 0 1 0，松开 Alt 键。（确保NumLock灯是亮的）</strong></p><p><strong>Mac系统：按住 Control + Command 键，然后按 Return (回车) 键。</strong></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509131152296183003.png\" alt=\"image.png\"/></p><!--autointro-->', '<p>在excel中用快捷键Ctrl+H调出替换窗口，</p><p>替换内容输入要替换的文字，替换为中输入方法：</p><p><strong>Windows系统：按住 Alt 键，然后在数字小键盘上依次输入 0 1 0，松开 Alt 键。（确保NumLock灯是亮的）</strong></p><p><strong>Mac系统：按住 Control + Command 键，然后按 Return (回车) 键。</strong></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509131152296183003.png\" alt=\"image.png\"/></p><p>然后全部替换即可。</p>', '1757735474', '0', '154', '', '', '1757735613', '1757735613');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('649', '2', '1', '', '0', '0', '', '0', '0', '推荐一个安卓app图标生成的软件', '<p>项目地址：<a href=\"https://github.com/stars-one/IconDrawableGenerator\">stars-one/IconDrawableGenerator: 一款Android开发者的工具软件,可以快速生成android开发需要使用的xml矢量图标文件</a></p><p>此软件提供一个图标库，选择图标后，直接点击复制按钮，然后在文件夹中粘贴，即可获得xml格式的图标文件。</p><p>也可以下载png格式。</p><p>还只是SVG转png。</p><!--autointro-->', '<p>项目地址：<a href=\"https://github.com/stars-one/IconDrawableGenerator\">stars-one/IconDrawableGenerator: 一款Android开发者的工具软件,可以快速生成android开发需要使用的xml矢量图标文件</a></p><p>此软件提供一个图标库，选择图标后，直接点击复制按钮，然后在文件夹中粘贴，即可获得xml格式的图标文件。</p><p>也可以下载png格式。</p><p>还只是SVG转png。</p><p>软件备用下载：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509151407082436993.rar\" title=\"IconDrawableGenerator.rar\">IconDrawableGenerator.rar</a></p><p>此包更新于2024-6-4, 包含以下内容：<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509151408041945785.png\" alt=\"image.png\"/></p><p><br/></p><p>注意：</p><p>软件复制的是文件，直接去文件夹里粘贴，而不是粘贴在文本工具！</p><p>不要将软件安装的C盘。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509151404055060085.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509151408175708831.png\" alt=\"image.png\"/></p><p><br/></p>', '1757916162', '0', '183', '', '', '1757916499', '1757916499');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('650', '3', '1', '', '0', '0', '', '0', '0', 'TVbox后台管理系统', '<p><strong>这是个简单的模板 有兴趣的自己二开&nbsp; 扩充源编辑 管理功能</strong><br/></p><p><br/>已实现 app在线打包，自动请求授权，管理端管理多仓，按日期授权，app重启切换授权，app端禁用源编辑，地址显示，一定程度上防源泄露，app内的后台地址使用base64储存&nbsp;</p><p>包含V8a 和 v7的安装包，tv和手机版各两个app</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/></p><!--autointro-->', '<p><strong>这是个简单的模板 有兴趣的自己二开&nbsp; 扩充源编辑 管理功能</strong><br/></p><p><br/>已实现 app在线打包，自动请求授权，管理端管理多仓，按日期授权，app重启切换授权，app端禁用源编辑，地址显示，一定程度上防源泄露，app内的后台地址使用base64储存&nbsp;</p><p>包含V8a 和 v7的安装包，tv和手机版各两个app</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510241412018211403.zip\" title=\"tvbox_admin.zip\">tvbox_admin.zip</a></p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510241413158216647.png\" alt=\"image.png\"/><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510241413313851973.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510241413484520968.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510241414003667520.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510241414209309754.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510241414305493514.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510241414439566810.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509261000551423695.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509221108555934690.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\"><br/></p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509170949526964705.png\" alt=\"image.png\"/></p><p style=\"line-height: 16px;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/09/202509170950233130967.png\" alt=\"image.png\"/></p>', '1757933916', '0', '383', '', '', '1757934001', '1761731597');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('656', '2', '1', '', '0', '0', '', '0', '0', '暂时增加rr对DSM7.3的支持', '<p>进入rr后按esc退出到输入界面，执行：</p><p><span style=\"text-wrap-mode: nowrap;\"></span></p><pre class=\"brush:bash;toolbar:false\">#&nbsp;增加7.3支持\r\nif&nbsp;!&nbsp;grep&nbsp;-q&nbsp;&#39;&quot;7\\.3&quot;:&#39;&nbsp;platforms.yml;&nbsp;then\r\n&nbsp;&nbsp;sed&nbsp;-i&nbsp;&#39;/&quot;7\\.2&quot;:/,/^&nbsp;*[^&nbsp;]/&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;/kver:&nbsp;&quot;4\\.4\\.302&quot;/a\\\r\n&nbsp;&nbsp;&quot;7.3&quot;:\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;kver:&nbsp;&quot;4.4.302&quot;\r\n&nbsp;&nbsp;}&#39;&nbsp;platforms.yml\r\n&nbsp;&nbsp;lnum=$(grep&nbsp;-n&nbsp;&#39;kver:&nbsp;&quot;5\\.10\\.55&quot;&#39;&nbsp;platforms.yml&nbsp;|&nbsp;tail&nbsp;-n1&nbsp;|&nbsp;cut&nbsp;-d:&nbsp;-f1)\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;-n&nbsp;&quot;$lnum&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;((lnum++))\r\n&nbsp;&nbsp;&nbsp;&nbsp;sed&nbsp;-i&nbsp;&quot;${lnum}i\\\\\r\n&nbsp;&nbsp;\\&quot;7.3\\&quot;:\\\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;kpre:&nbsp;\\&quot;7.2\\&quot;\\\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;kver:&nbsp;\\&quot;5.10.55\\&quot;\r\n&quot;&nbsp;platforms.yml\r\nmenu.sh\r\n&nbsp;&nbsp;fi\r\nelse\r\nmenu.sh\r\nfi</pre><!--autointro-->', '<p>进入rr后按esc退出到输入界面，执行：</p><p><span style=\"text-wrap-mode: nowrap;\"></span></p><pre class=\"brush:bash;toolbar:false\">#&nbsp;增加7.3支持\r\nif&nbsp;!&nbsp;grep&nbsp;-q&nbsp;&#39;&quot;7\\.3&quot;:&#39;&nbsp;platforms.yml;&nbsp;then\r\n&nbsp;&nbsp;sed&nbsp;-i&nbsp;&#39;/&quot;7\\.2&quot;:/,/^&nbsp;*[^&nbsp;]/&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;/kver:&nbsp;&quot;4\\.4\\.302&quot;/a\\\r\n&nbsp;&nbsp;&quot;7.3&quot;:\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;kver:&nbsp;&quot;4.4.302&quot;\r\n&nbsp;&nbsp;}&#39;&nbsp;platforms.yml\r\n&nbsp;&nbsp;lnum=$(grep&nbsp;-n&nbsp;&#39;kver:&nbsp;&quot;5\\.10\\.55&quot;&#39;&nbsp;platforms.yml&nbsp;|&nbsp;tail&nbsp;-n1&nbsp;|&nbsp;cut&nbsp;-d:&nbsp;-f1)\r\n&nbsp;&nbsp;if&nbsp;[&nbsp;-n&nbsp;&quot;$lnum&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;((lnum++))\r\n&nbsp;&nbsp;&nbsp;&nbsp;sed&nbsp;-i&nbsp;&quot;${lnum}i\\\\\r\n&nbsp;&nbsp;\\&quot;7.3\\&quot;:\\\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;kpre:&nbsp;\\&quot;7.2\\&quot;\\\\\r\n&nbsp;&nbsp;&nbsp;&nbsp;kver:&nbsp;\\&quot;5.10.55\\&quot;\r\n&quot;&nbsp;platforms.yml\r\nmenu.sh\r\n&nbsp;&nbsp;fi\r\nelse\r\nmenu.sh\r\nfi</pre><p><span style=\"text-wrap-mode: nowrap;\"></span><br/></p><p>然后在<strong>setting menu</strong>中找到<strong>保存对rr的修改</strong></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510241519563724688.png\" alt=\"image.png\"/></p><p><br/></p>', '1761290312', '0', '128', '', '', '1761290415', '1761290415');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('651', '2', '1', '', '0', '0', '', '0', '0', '一键降低群晖套件的版本限制', '<p>此脚本用于把指定的套件版本号降低至合理范围，以允许安装被官方故意屏蔽的版本号。</p><p>DSM7.3和DSM7.2.1兼容性应该是一样的，此脚本指定的版本依据DSM7.2.1为参考。</p><p>可安装被官方屏蔽的<strong>photo旧版，video station, 旧版AME, PH7.3, PHP7.4, PHP8.0, node.js V14， Node.js V16, </strong>如有更多套件需要改，自行在脚本中添加。</p><p style=\"line-height: 16px;\"></p><!--autointro-->', '<p>此脚本用于把指定的套件版本号降低至合理范围，以允许安装被官方故意屏蔽的版本号。</p><p>DSM7.3和DSM7.2.1兼容性应该是一样的，此脚本指定的版本依据DSM7.2.1为参考。</p><p>可安装被官方屏蔽的<strong>photo旧版，video station, 旧版AME, PH7.3, PHP7.4, PHP8.0, node.js V14， Node.js V16, </strong>如有更多套件需要改，自行在脚本中添加。</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510131010589349249.sh\" title=\"downgrade_package_limited.sh\">downgrade_package_limited.sh</a></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510131011023198106.png\" alt=\"image.png\"/></p><p>降低后，需要去下载离线包手动安装，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510131020368766893.png\" alt=\"image.png\"/></p><p>所有套件历史版本在此处下载:</p><p><a href=\"https://archive.synology.com/download/Package\">Synology Archive Download Site - Index of /download/Package</a></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510131012036645940.png\" alt=\"image.png\"/></p>', '1760321392', '0', '126', '', '', '1760321669', '1760322039');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('652', '2', '1', '', '0', '0', '', '0', '0', '使用winscp查看群晖docker容器的真实文件目录', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>先在群晖后台查看容器的id路径在：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510131134357447405.png\" alt=\"image.png\"/><br/></p></li><li><p>在目录&nbsp;/var/packages/ContainerManager/var/docker/image/btrfs/layerdb/mounts 中找到此ID为名的目录</p></li></ol><!--autointro-->', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>先在群晖后台查看容器的id路径在：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510131134357447405.png\" alt=\"image.png\"/><br/></p></li><li><p>在目录&nbsp;/var/packages/ContainerManager/var/docker/image/btrfs/layerdb/mounts 中找到此ID为名的目录</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510131135123875136.png\" alt=\"image.png\"/><br/></p></li><li><p>进入目录，打开文件init-id 查看内容。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510131136159296537.png\" alt=\"image.png\"/></p></li><li><p>在到目录&nbsp;<span style=\"text-wrap-mode: wrap;\">/var/packages/ContainerManager/var/docker/btrfs/subvolumes 中查到init-id 对应的目录</span></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510131137308830364.png\" alt=\"image.png\"/></p></li></ol><p>使用ssh直接查询 init-id</p><pre class=\"brush:bash;toolbar:false\">ID=&quot;7df4403cdd647b620b3ea7e038c6e071f950009853d6545357f2e0276a8d96a8&quot;\r\ncat&nbsp;/var/packages/ContainerManager/var/docker/image/btrfs/layerdb/mounts/$ID/init-id</pre><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510131139231598237.png\" alt=\"image.png\"/><br/></p>', '1760325357', '0', '112', '', '', '1760325480', '1760326801');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('653', '2', '1', '', '0', '0', '', '0', '0', '将群晖已安装的套件从一个储存空间移动到另一个储存空间', '<p>脚本：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231343115445479.sh\" title=\"mvSPK.sh\"></a></p><!--autointro-->', '<p>脚本：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_txt.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231343115445479.sh\" title=\"mvSPK.sh\">mvSPK.sh</a></p><br/><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510221841424752245.png\" alt=\"9ff0af70a92b568f668d539dd388754b.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510221841505072251.png\" alt=\"a7f5a363f9234bfd6f49b7a3f1166cd7.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510221841549523675.png\" alt=\"135606f89d51f27d83c390deeb9fd37e.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510221841598033005.png\" alt=\"da6b618984b2f845971c20711283dd71.png\"/></p><p>适用于DSM7的大部分套件，如移动后提示需要修复，手动修复一下</p><p>脚本代码如下：</p><pre class=\"brush:bash;toolbar:false\">#!/bin/bash\r\n\r\ni=1\r\nprintf&nbsp;&quot;%-4s&nbsp;%-30s&nbsp;%-10s\\n&quot;&nbsp;&quot;序号&quot;&nbsp;&quot;目录名&quot;&nbsp;&quot;所在卷&quot;\r\nprintf&nbsp;&quot;%-4s&nbsp;%-30s&nbsp;%-10s\\n&quot;&nbsp;&quot;----&quot;&nbsp;&quot;------------------------------&quot;&nbsp;&quot;----------&quot;\r\n\r\n#&nbsp;临时保存所有路径的数组\r\ndeclare&nbsp;-a&nbsp;paths\r\n\r\nfor&nbsp;path&nbsp;in&nbsp;/volume*/@appstore/*;&nbsp;do\r\n&nbsp;&nbsp;&nbsp;&nbsp;dir_name=$(basename&nbsp;&quot;$path&quot;)\r\n&nbsp;&nbsp;&nbsp;&nbsp;vol_name=$(echo&nbsp;&quot;$path&quot;&nbsp;|&nbsp;awk&nbsp;-F&#39;/&#39;&nbsp;&#39;{print&nbsp;$2}&#39;)\r\n&nbsp;&nbsp;&nbsp;&nbsp;printf&nbsp;&quot;%-4d&nbsp;%-30s&nbsp;%-10s\\n&quot;&nbsp;&quot;$i&quot;&nbsp;&quot;$dir_name&quot;&nbsp;&quot;$vol_name&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;paths[$i]=&quot;$path&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;i=$((i+1))\r\ndone\r\n\r\necho\r\nread&nbsp;-p&nbsp;&quot;请输入要移动套件的序号:&nbsp;&quot;&nbsp;sel\r\n\r\n#&nbsp;校验输入是否有效\r\nif&nbsp;[[&nbsp;!&nbsp;&quot;$sel&quot;&nbsp;=~&nbsp;^[0-9]+$&nbsp;]]&nbsp;||&nbsp;[&nbsp;-z&nbsp;&quot;${paths[$sel]}&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;❌&nbsp;无效的序号，请重新运行脚本。&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;exit&nbsp;1\r\nfi\r\n\r\n#&nbsp;提取目录名与卷名\r\nappname=$(basename&nbsp;&quot;${paths[$sel]}&quot;)\r\nvol_from=$(echo&nbsp;&quot;${paths[$sel]}&quot;&nbsp;|&nbsp;awk&nbsp;-F&#39;/&#39;&nbsp;&#39;{print&nbsp;$2}&#39;)\r\n\r\necho&nbsp;&quot;✅&nbsp;已选择:&quot;\r\necho&nbsp;&quot;要移动的套件：$appname&quot;\r\necho&nbsp;&quot;所在卷：$vol_from&quot;\r\n\r\necho\r\nread&nbsp;-p&nbsp;&quot;请输入目标卷号（例如输入&nbsp;2&nbsp;表示&nbsp;volume2）:&nbsp;&quot;&nbsp;vol_num\r\n\r\n#&nbsp;校验卷号输入\r\nif&nbsp;[[&nbsp;!&nbsp;&quot;$vol_num&quot;&nbsp;=~&nbsp;^[0-9]+$&nbsp;]];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;❌&nbsp;无效的卷号，请输入数字。&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;exit&nbsp;1\r\nfi\r\n\r\nvol_to=&quot;volume${vol_num}&quot;\r\n\r\necho\r\necho&nbsp;&quot;✅&nbsp;准备移动到:&quot;\r\necho&nbsp;&quot;$vol_to&quot;\r\n\r\necho\r\nread&nbsp;-p&nbsp;&quot;确认执行&nbsp;Y/y:&nbsp;&quot;&nbsp;confirm\r\n\r\nif&nbsp;[[&nbsp;&quot;$confirm&quot;&nbsp;==&nbsp;&quot;Y&quot;&nbsp;||&nbsp;&quot;$confirm&quot;&nbsp;==&nbsp;&quot;y&quot;&nbsp;]];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;✅&nbsp;已确认，继续执行...&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;#&nbsp;在这里写你要执行的命令\r\nelse\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;❌&nbsp;操作已取消。&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;exit&nbsp;1\r\nfi\r\n\r\nmkdir&nbsp;-p&nbsp;/$vol_to/@appstore&nbsp;/$vol_to/@appshare&nbsp;/$vol_to/@apphome&nbsp;/$vol_to/@appdata&nbsp;/$vol_to/@appconf\r\n\r\n#&nbsp;停止套件\r\nsynopkg&nbsp;stop&nbsp;$appname\r\n\r\n#&nbsp;移动目录\r\nmv&nbsp;/$vol_from/@appstore/$appname&nbsp;/$vol_to/@appstore/\r\nmv&nbsp;/$vol_from/@appshare/$appname&nbsp;/$vol_to/@appshare/\r\nmv&nbsp;/$vol_from/@apphome/$appname&nbsp;/$vol_to/@apphome/\r\nmv&nbsp;/$vol_from/@appdata/$appname&nbsp;/$vol_to/@appdata/\r\nmv&nbsp;/$vol_from/@appconf/$appname&nbsp;/$vol_to/@appconf/\r\nmv&nbsp;/$vol_from/@apptemp/$appname&nbsp;/$vol_to/@apptemp/\r\n\r\n#&nbsp;删除指向旧应用程序路径的过时符号链接\r\nrm&nbsp;-fv&nbsp;/var/packages/$appname/target\r\nrm&nbsp;-fv&nbsp;/var/packages/$appname/var\r\nrm&nbsp;-fv&nbsp;/var/packages/$appname/tmp\r\nrm&nbsp;-fv&nbsp;/var/packages/$appname/share\r\nrm&nbsp;-fv&nbsp;/var/packages/$appname/home\r\nrm&nbsp;-fv&nbsp;/var/packages/$appname/etc\r\n\r\n#&nbsp;创建指向新的、正确的应用程序路径的新&nbsp;Sim&nbsp;链接。\r\nln&nbsp;-s&nbsp;/$vol_to/@appstore/$appname&nbsp;/var/packages/$appname/target\r\nln&nbsp;-s&nbsp;/$vol_to/@appdata/$appname&nbsp;/var/packages/$appname/var\r\nln&nbsp;-s&nbsp;/$vol_to/@apptemp/$appname&nbsp;/var/packages/$appname/tmp\r\nln&nbsp;-s&nbsp;/$vol_to/@appshare/$appname&nbsp;/var/packages/$appname/share\r\nln&nbsp;-s&nbsp;/$vol_to/@apphome/$appname&nbsp;/var/packages/$appname/home\r\nln&nbsp;-s&nbsp;/$vol_to/@appconf/$appname&nbsp;/var/packages/$appname/etc\r\n\r\n#&nbsp;启动套件\r\n#&nbsp;获取套件状态\r\nstatus=$(synopkg&nbsp;status&nbsp;&quot;$appname&quot;&nbsp;|&nbsp;jq&nbsp;-r&nbsp;&#39;.status&#39;&nbsp;2&gt;/dev/null)\r\nif&nbsp;[&nbsp;&quot;$status&quot;&nbsp;=&nbsp;&quot;stop&quot;&nbsp;];&nbsp;then\r\n&nbsp;&nbsp;&nbsp;&nbsp;echo&nbsp;&quot;正在启动&nbsp;[$appname]&nbsp;...&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;synopkg&nbsp;start&nbsp;$appname\r\nfi\r\n\r\necho&nbsp;&quot;已经把套件&nbsp;$appname&nbsp;从&nbsp;$vol_from&nbsp;移动到&nbsp;$vol_to&nbsp;&quot;</pre>', '1761129654', '0', '72', '', '', '1761129792', '1761198226');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('654', '2', '1', '', '0', '0', '', '0', '0', '飞牛系统创建一般php网站', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>新建一个目录，准备放php的文件<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231000075472736.png\" alt=\"image.png\"/></p></li><li><p>将网站文件上传到这个目录</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231001492582075.png\" alt=\"image.png\"/></p></li></ol><!--autointro-->', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>新建一个目录，准备放php的文件<br/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231000075472736.png\" alt=\"image.png\"/></p></li><li><p>将网站文件上传到这个目录</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231001492582075.png\" alt=\"image.png\"/></p></li><li><p>上传创建网站脚本到此目录，脚本在此处下载：{#ZC_BLOG_HOST#}?id=607</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231004017146479.png\" alt=\"image.png\"/></p></li><li><p>开始ssh，并使用工具连接</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231005143388228.png\" alt=\"image.png\"/></p></li><li><p>使用&nbsp;<span style=\"color: #0070C0;\">sudo -i </span>切换至root账户</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231006054859630.png\" alt=\"image.png\"/></p></li><li><p>在目录中点更多-详细信息，赋值原始路径</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231008537855457.png\" alt=\"image.png\"/><br/></p></li><li><p>在控制台中切换到此路径，<span style=\"color: #0070C0;\">cd&nbsp;/vol1/1000/web/mytvadmin</span></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231009086716641.png\" alt=\"image.png\"/></p></li><li><p>输入&nbsp;<span style=\"color: #0070C0;\">bash nginx.sh</span> 开始安装，第一次安装需要安装一些必要软件</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231009573215179.png\" alt=\"image.png\"/></p><p>期间会提示一个是否自动运行，选yes</p></li><li><p>根据提示设置nginx的端口号，网站名称，端口号</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231013062162237.png\" alt=\"image.png\"/></p></li><li><p>安装完成后，访问ip:端口，即可进入网站</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231013537672591.png\" alt=\"image.png\"/><br/></p></li></ol>', '1761184752', '0', '79', '', '', '1761185692', '1761185692');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('655', '2', '1', '', '0', '0', '', '0', '0', 'Edge浏览器插件保存位置', '<p>所有插件的保存路径：C:\\Users\\用户名\\AppData\\Local\\Microsoft\\Edge\\User Data\\Default\\Extensions</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231514027635813.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231514266700256.png\" alt=\"image.png\"/></p><!--autointro-->', '<p>所有插件的保存路径：C:\\Users\\用户名\\AppData\\Local\\Microsoft\\Edge\\User Data\\Default\\Extensions</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231514027635813.png\" alt=\"image.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231514266700256.png\" alt=\"image.png\"/></p><p>ID对应的目录就是这个插件的保存目录：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510231515006088859.png\" alt=\"image.png\"/></p>', '1761203547', '0', '84', '', '', '1761203702', '1761203702');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('657', '2', '1', '', '0', '0', '', '0', '0', 'TVbox多仓管理系统', '<p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510291746166276163.zip\" title=\"tvbox_admin.zip\"></a></p><!--autointro-->', '<p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510291746166276163.zip\" title=\"tvbox_admin.zip\">tvbox_admin.zip</a></p><p>&nbsp;- [√] 增加多个点播源</p><p>&nbsp;- [√] 增加多个直播源</p><p>&nbsp;- [√] 增加多个emby服务器作为源</p><p>&nbsp;- [√] 增加本地点播源</p><p>&nbsp;- [√] 增加点播源片段</p><p>&nbsp;- [√] 点播源符合片段</p><p>&nbsp;- [√] 点播源选择性复合本地源</p><p>&nbsp;- [√] 选择性复合直播源</p><p>&nbsp;- [√] 多仓管理</p><p>&nbsp;- [√] 下载app页面</p><p>&nbsp;- [√] 系统安装</p><p>&nbsp;- [√] 系统删除</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/10/202510271836415094295.png\" alt=\"image.png\"/></p>', '1761561327', '0', '129', '', '', '1761561402', '1761731464');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('658', '2', '1', '', '0', '0', '', '0', '0', '三星手机隐藏底部导航条', '<p>新版的OneUI默认是没有隐藏导航条的设置的，此时必须使用Good Lock激活此设置，再进行隐藏，并且设置后不能写在Good Lock</p><p>Good Lock也是官方出品，用于三星手机各种高级自定义设置。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031044046687312.png\" alt=\"image.png\"/></p><p>打开Good Lock后安装Nav Star</p><!--autointro-->', '<p>新版的OneUI默认是没有隐藏导航条的设置的，此时必须使用Good Lock激活此设置，再进行隐藏，并且设置后不能写在Good Lock</p><p>Good Lock也是官方出品，用于三星手机各种高级自定义设置。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031044046687312.png\" alt=\"image.png\"/></p><p>打开Good Lock后安装Nav Star</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031044403581071.png\" alt=\"image.png\"/></p><p>打开Nav star, 激活“启用从底部滑动手势”的选项，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031045028813767.png\" alt=\"image.png\"/></p><p>再进去手机系统设置-导航设置时，更多选项即出现，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031046003359697.png\" alt=\"image.png\"/></p><p>关闭手势提醒，即可隐藏手机底部的导航横线</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031046352949860.png\" alt=\"image.png\"/><br/></p><p><br/></p>', '1762137596', '0', '42', '', '', '1762137997', '1762137997');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('659', '2', '1', '', '0', '0', '', '0', '0', '储水式热水器怎么把内档里的水放出来', '<p>卸掉出水管，松掉泄压阀的螺丝，把泄压阀打开，即开始排水，水会从进水管排出</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031049296552157.png\" alt=\"image.png\"/></p><p>此时就可以拧下泄压阀，直接排水</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031049561984584.png\" alt=\"image.png\"/></p><!--autointro-->', '<p>卸掉出水管，松掉泄压阀的螺丝，把泄压阀打开，即开始排水，水会从进水管排出</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031049296552157.png\" alt=\"image.png\"/></p><p>此时就可以拧下泄压阀，直接排水</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031049561984584.png\" alt=\"image.png\"/></p>', '1762138071', '0', '36', '', '', '1762138228', '1762138228');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('660', '2', '1', '', '0', '0', '', '0', '0', '在AutodeskCAD中怎么制作空心文字', '<ol class=\" list-paddingleft-2\" style=\"margin-top: 20px; margin-bottom: 20px; margin-left: 35px; padding: 0px; color: rgb(51, 51, 51); font-family: Arial, &quot;Microsoft Yahei&quot;, &quot;Lucida Grande&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"></ol><!--autointro-->', '<ol class=\" list-paddingleft-2\" style=\"margin-top: 20px; margin-bottom: 20px; margin-left: 35px; padding: 0px; color: rgb(51, 51, 51); font-family: Arial, &quot;Microsoft Yahei&quot;, &quot;Lucida Grande&quot;; text-wrap-mode: wrap; background-color: rgb(255, 255, 255);\"><li><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\">使用单行文字功能输入一个文字，并修改文字属性为粗体文字</p><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\"><span class=\"LightGallery_Item\" lg-data-src=\"https://ljs.fun:4435/zb_users/upload/2025/09/202509021353135078503.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; cursor: pointer;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031752083873993.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; border: 0px; max-width: 90%;\" data-catchresult=\"img_catchSuccess\"/></span><br style=\"margin: 0px; padding: 0px;\"/></p></li><li><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\">使用TXTEXP 把文字转成空心文字，但是此时可能会被打散成多块</p><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\"><span class=\"LightGallery_Item\" lg-data-src=\"https://ljs.fun:4435/zb_users/upload/2025/09/202509021353567003135.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; cursor: pointer;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031752089226745.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; border: 0px; max-width: 90%;\" data-catchresult=\"img_catchSuccess\"/></span><br style=\"margin: 0px; padding: 0px;\"/></p></li><li><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\">使用REGION把文字转成面对象</p><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\"><span class=\"LightGallery_Item\" lg-data-src=\"https://ljs.fun:4435/zb_users/upload/2025/09/202509021354128540721.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; cursor: pointer;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031752088263982.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; border: 0px; max-width: 90%;\" data-catchresult=\"img_catchSuccess\"/></span><br style=\"margin: 0px; padding: 0px;\"/></p></li><li><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\">使用UNIONB把打散的面对象合并成一个对象</p><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\"><span class=\"LightGallery_Item\" lg-data-src=\"https://ljs.fun:4435/zb_users/upload/2025/09/202509021354272624487.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; cursor: pointer;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031752089286555.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; border: 0px; max-width: 90%;\" data-catchresult=\"img_catchSuccess\"/></span></p></li><li><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\">使用list获取文字的周长</p><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\"><span class=\"LightGallery_Item\" lg-data-src=\"https://ljs.fun:4435/zb_users/upload/2025/09/202509021355304564062.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; cursor: pointer;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031752088507867.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; border: 0px; max-width: 90%;\" data-catchresult=\"img_catchSuccess\"/></span></p></li><li><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\">使用BOUNDARY把面域转成多段线。</p><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\"><span class=\"LightGallery_Item\" lg-data-src=\"https://ljs.fun:4435/zb_users/upload/2025/10/202510091741501420549.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; cursor: pointer;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031752088311650.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; border: 0px; max-width: 90%;\" data-catchresult=\"img_catchSuccess\"/></span></p><p style=\"margin-top: 10px; margin-bottom: 10px; padding: 0px; text-indent: 2em;\"><span class=\"LightGallery_Item\" lg-data-src=\"https://ljs.fun:4435/zb_users/upload/2025/10/202510091742053339268.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; cursor: pointer;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031752082210438.png\" alt=\"image.png\" style=\"margin: 0px; padding: 0px; border: 0px; max-width: 90%;\" data-catchresult=\"img_catchSuccess\"/></span></p></li></ol><p><br/></p>', '1762163492', '0', '37', '', '', '1762163538', '1762163538');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('661', '2', '1', '', '0', '0', '', '0', '0', '使用LEDmagic/LEDedit灯光编程软件制作门头文字边缘跑马效果', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>创建门头字的layout，先走外圈，再走内部</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031753463541335.png\" alt=\"image.png\"/></p></li><li><p>在编程软件里创建一条直线，长度等于外圈点数，录制跑马效果</p></li></ol><!--autointro-->', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>创建门头字的layout，先走外圈，再走内部</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031753463541335.png\" alt=\"image.png\"/></p></li><li><p>在编程软件里创建一条直线，长度等于外圈点数，录制跑马效果</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031754478207949.png\" alt=\"image.png\"/></p></li><li><p>导入layout, 此时会保留边缘流动效果，继续录制其他全局效果即可。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511031756023583432.png\" alt=\"image.png\"/><br/></p><p><br/></p></li></ol>', '1762163541', '0', '38', '', '', '1762163772', '1762163772');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('662', '2', '1', '', '0', '0', '', '0', '0', '飞牛无公网通过frp实现外网访问', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>你需要有一个frps服务器，公益的或者自建的<br/></p></li><li><p>在域名解析站获取lucky申请证书需要的密钥，例如dnspod，阿里云，腾讯云</p></li><li><p>飞牛安装frpc和lucky</p><p>网络结构如下：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511141430062432421.png\" alt=\"image.png\"/></p></li></ol><!--autointro-->', '<ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>你需要有一个frps服务器，公益的或者自建的<br/></p></li><li><p>在域名解析站获取lucky申请证书需要的密钥，例如dnspod，阿里云，腾讯云</p></li><li><p>飞牛安装frpc和lucky</p><p>网络结构如下：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511141430062432421.png\" alt=\"image.png\"/><br/></p></li></ol><p>开始搞：<br/></p><ol class=\" list-paddingleft-2\" style=\"list-style-type: decimal;\"><li><p>在frpc里设置frps的连接信息，并添加一个和frps通讯的端口，例如2026</p><p><br/></p><p style=\"text-wrap-mode: wrap;\">[[proxies]]</p><p style=\"text-wrap-mode: wrap;\">name = &quot;brian_fn&quot;</p><p style=\"text-wrap-mode: wrap;\">type = &quot;tcp&quot;</p><p style=\"text-wrap-mode: wrap;\">localIP = &quot;127.0.0.1&quot;</p><p style=\"text-wrap-mode: wrap;\">localPort = 2026</p><p style=\"text-wrap-mode: wrap;\">remotePort = 2026</p></li><li><p>在服务器所在的网络主路由上，把这个端口映射出来</p><p>内部2026，外部2026</p></li><li><p>在域名解析站增加一条cname记录</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511141403251439559.png\" alt=\"image.png\"/></p></li><li><p>在lucky上创建SSL服务</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511141404261049317.png\" alt=\"image.png\"/></p></li><li><p>在lucky上创建web服务，选上v4,设置监听端口，激活TLS</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511141405188597320.png\" alt=\"image.png\"/></p></li><li><p>添加反代子规则</p><p>注意：服务类型默认的反向代理，前端地址填写一个带前缀的二级域名，后端地址填写&nbsp;http://1<strong>72.17.0.1</strong>:内部端口，例如飞牛的http默认端口5666，需要带协议http或者https,内部地址不是172.0.0.1&nbsp;！</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511141410386766819.png\" alt=\"image.png\"/><br/></p></li><li><p>设置好后的样子：</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511141409394401657.png\" alt=\"image.png\"/></p></li><li><p>在外网使用二级域名访问试试吧。<br/></p></li></ol><p><br/></p><p><br/></p>', '1763099709', '0', '49', '', '', '1763100657', '1763101809');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('663', '2', '1', '', '0', '0', '', '0', '0', '飞牛安装配置网站', '<p>先下载脚本：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2026/01/202601051038317231680.rar\" title=\"web_configer_for_FN.rar\"></a></p><!--autointro-->', '<p>先下载脚本：</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2026/01/202601051038317231680.rar\" title=\"web_configer_for_FN.rar\">web_configer_for_FN.rar</a></p><br/><p>上传文件到网站根目录，直接bash&nbsp;web_configer_for_FN.sh根据菜单提示执行安装，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/12/202512181916209707143.png\" alt=\"image.png\"/></p><p>第一次使用期间按提示设置nginx和网站名称，端口，</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511191808065887511.png\" alt=\"22.png\" title=\"22.png\"/></p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511191808279154046.png\" alt=\"33.png\" title=\"33.png\"/></p><p>仅第一次需要安装环境，用时稍长，以后只需要设置网站名称和端口，几秒的事。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511191809048633978.png\" alt=\"44.png\" title=\"44.png\"/></p><p><br/></p>', '1763117067', '0', '140', '', '', '1763117365', '1767580718');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('674', '2', '1', '', '0', '0', '', '0', '0', '修改飞牛应用万能编辑器，隐藏侧边目录树', '<p>sed -i &#39;s/width: 256px; min-width: 256px; transition: width 0.3s ease;/width: 256px; min-width: 256px; transition: width 0.3s ease; display: none;/g&#39; /<strong><span style=\"color: #0070C0;\">vol1</span></strong>/@appcenter/all.editor/server/dist/index.html<br/></p><!--autointro-->', '<p>sed -i &#39;s/width: 256px; min-width: 256px; transition: width 0.3s ease;/width: 256px; min-width: 256px; transition: width 0.3s ease; display: none;/g&#39; /<strong><span style=\"color: #0070C0;\">vol1</span></strong>/@appcenter/all.editor/server/dist/index.html<br/><br/>注意根据自己应用安装的储存空间，修改<strong style=\"text-wrap-mode: wrap;\"><span style=\"color: #0070C0;\">vol1。</span></strong></p><p><strong style=\"text-wrap-mode: wrap;\"><span style=\"color: #0070C0;\"><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/12/202512221508499628481.jpg\" alt=\"f22971ecd37f908f5ea6ed2a00261b0d_720.jpg\"/></span></strong></p>', '1766387217', '0', '81', '', '', '1766387333', '1766387333');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('664', '2', '1', '', '0', '0', '', '0', '0', '飞牛定时开关机脚本', '<p>增加执行权限</p><p>chmod +x power_scheduler.sh</p><p>使用方法</p><p>./power_scheduler.sh shutdown HH:MM&nbsp; &nbsp; &nbsp; &nbsp; # 设置每天定时关机</p><p>./power_scheduler.sh wakeup HH:MM&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 设置每天定时开机</p><p>./power_scheduler.sh cancel shutdown&nbsp; &nbsp; &nbsp; &nbsp;# 取消定时关机</p><!--autointro-->', '<p>增加执行权限</p><p>chmod +x power_scheduler.sh</p><p>使用方法</p><p>./power_scheduler.sh shutdown HH:MM&nbsp; &nbsp; &nbsp; &nbsp; # 设置每天定时关机</p><p>./power_scheduler.sh wakeup HH:MM&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 设置每天定时开机</p><p>./power_scheduler.sh cancel shutdown&nbsp; &nbsp; &nbsp; &nbsp;# 取消定时关机</p><p>./power_scheduler.sh cancel wakeup&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;# 取消定时开机</p><p>./power_scheduler.sh cancel all&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 取消所有定时任务</p><p>./power_scheduler.sh status&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; # 查看当前定时任务状态</p><p><br/></p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511181412541718032.rar\" title=\"定时开关机.rar\">定时开关机.rar</a></p><p><br/></p>', '1763446346', '0', '40', '', '', '1763446377', '1763446377');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('665', '2', '1', '', '0', '0', '', '0', '0', '飞牛计划任务管理', '<p>此压缩包中包含计划任务管理的目录结构，路径中请勿使用中文，以免执行异常。</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511181414168412772.rar\" title=\"飞牛计划任务.rar\"></a></p><!--autointro-->', '<p>此压缩包中包含计划任务管理的目录结构，路径中请勿使用中文，以免执行异常。</p><p style=\"line-height: 16px;\"><img style=\"vertical-align: middle; margin-right: 2px;\" src=\"{#ZC_BLOG_HOST#}zb_users/plugin/Neditor/dialogs/attachment/fileTypeImages/icon_rar.gif\"/><a style=\"font-size:12px; color:#0066cc;\" href=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/11/202511181414168412772.rar\" title=\"飞牛计划任务.rar\">飞牛计划任务.rar</a></p><p><br/></p>', '1763446380', '0', '43', '', '', '1763446458', '1763446458');
INSERT INTO `zbp_post` (`log_ID`, `log_CateID`, `log_AuthorID`, `log_Tag`, `log_Status`, `log_Type`, `log_Alias`, `log_IsTop`, `log_IsLock`, `log_Title`, `log_Intro`, `log_Content`, `log_PostTime`, `log_CommNums`, `log_ViewNums`, `log_Template`, `log_Meta`, `log_CreateTime`, `log_UpdateTime`) VALUES ('671', '2', '1', '', '0', '0', '', '0', '0', '飞牛安装docker版咪咕zb订阅工具', '<p>先去咪咕官网登陆账号：<a href=\"https://www.miguvideo.com/\">咪咕视频体育频道-精彩赛事在线直播</a></p><p>登陆成功后，按F12打开开发工具，切换到控制台，输入以下内容，回车：</p><p><span style=\"text-wrap-mode: nowrap;\"></span></p><pre class=\"brush:bash;toolbar:false\">function&nbsp;generateSubscriptionUrl()&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;getCookie&nbsp;=&nbsp;(name)&nbsp;=&gt;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;value&nbsp;=&nbsp;&#39;;&nbsp;&#39;&nbsp;+&nbsp;document.cookie;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;parts&nbsp;=&nbsp;value.split(&#39;;&nbsp;&#39;&nbsp;+&nbsp;name&nbsp;+&nbsp;&#39;=&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(parts.length&nbsp;===&nbsp;2)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;parts.pop().split(&#39;;&#39;).shift();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;};\r\n&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;user_info&nbsp;=&nbsp;JSON.parse(decodeURIComponent(getCookie(&#39;userInfo&#39;)));\r\n&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(user_info)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;user_id&nbsp;=&nbsp;user_info.userId;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;user_token&nbsp;=&nbsp;user_info.userToken;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(user_id&nbsp;&amp;&amp;&nbsp;user_token)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;console.log(`userId:&nbsp;${user_id}`);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;console.log(`userToken:&nbsp;${user_token}`);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;{&nbsp;userId:&nbsp;user_id,&nbsp;userToken:&nbsp;user_token&nbsp;};\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}&nbsp;else&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;console.log(&#39;用户Cookie缺失&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;}&nbsp;else&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;console.log(&#39;用户Cookie找不到&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n}\r\ngenerateSubscriptionUrl();</pre><!--autointro-->', '<p>先去咪咕官网登陆账号：<a href=\"https://www.miguvideo.com/\">咪咕视频体育频道-精彩赛事在线直播</a></p><p>登陆成功后，按F12打开开发工具，切换到控制台，输入以下内容，回车：</p><p><span style=\"text-wrap-mode: nowrap;\"></span></p><pre class=\"brush:bash;toolbar:false\">function&nbsp;generateSubscriptionUrl()&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;getCookie&nbsp;=&nbsp;(name)&nbsp;=&gt;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;value&nbsp;=&nbsp;&#39;;&nbsp;&#39;&nbsp;+&nbsp;document.cookie;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;parts&nbsp;=&nbsp;value.split(&#39;;&nbsp;&#39;&nbsp;+&nbsp;name&nbsp;+&nbsp;&#39;=&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(parts.length&nbsp;===&nbsp;2)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;parts.pop().split(&#39;;&#39;).shift();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;};\r\n&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;user_info&nbsp;=&nbsp;JSON.parse(decodeURIComponent(getCookie(&#39;userInfo&#39;)));\r\n&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(user_info)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;user_id&nbsp;=&nbsp;user_info.userId;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;const&nbsp;user_token&nbsp;=&nbsp;user_info.userToken;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;if&nbsp;(user_id&nbsp;&amp;&amp;&nbsp;user_token)&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;console.log(`userId:&nbsp;${user_id}`);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;console.log(`userToken:&nbsp;${user_token}`);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;return&nbsp;{&nbsp;userId:&nbsp;user_id,&nbsp;userToken:&nbsp;user_token&nbsp;};\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}&nbsp;else&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;console.log(&#39;用户Cookie缺失&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;}&nbsp;else&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;console.log(&#39;用户Cookie找不到&#39;);\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n}\r\ngenerateSubscriptionUrl();</pre><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/12/202512181219428158465.png\" alt=\"image.png\"/></p><p>复制id和token，填充在下面的compose中：</p><pre class=\"brush:bash;toolbar:false\">services:\r\n&nbsp;&nbsp;migu_video:\r\n&nbsp;&nbsp;&nbsp;&nbsp;image:&nbsp;develop767/migu_video:latest\r\n&nbsp;&nbsp;&nbsp;&nbsp;container_name:&nbsp;migu_video\r\n&nbsp;&nbsp;&nbsp;&nbsp;ports:\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;&quot;1111:1111&quot;\r\n&nbsp;&nbsp;&nbsp;&nbsp;environment:\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;muserId=你的id\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;mtoken=你的token\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;mport=1111\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;-&nbsp;mrateType=3&nbsp;#&nbsp;清晰度：2=标清，3=高清，4=蓝光(VIP)\r\n&nbsp;&nbsp;&nbsp;&nbsp;restart:&nbsp;always</pre><p>如果你的账号是咪咕vip，可以把mrateType改为4，</p><p>在飞牛docker中，创建compose，并构建容器。</p><p><img src=\"{#ZC_BLOG_HOST#}zb_users/upload/2025/12/202512181222277207331.png\" alt=\"image.png\"/></p><p>容器运行成功后，访问:</p><p>直接访问&nbsp;&nbsp;&nbsp;&nbsp;<strong>域名:端口</strong>，获取m3u格式的订阅地址，</p><p>访问&nbsp;&nbsp;&nbsp;<strong>&nbsp;域名:端口/txt</strong>，获取txt格式的订阅地址（diyp）.</p>', '1766030911', '0', '103', '', '', '1766031882', '1767580793');
